import{n as e,r as t}from"./rolldown-runtime-CNOWq4Kh.js";var n=t({default:()=>r}),r;function i(){return(i=e((()=>{r={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Paramètres de l’environnement d’exécution ACP permettant d’activer la répartition, de sélectionner les backends, de limiter les agents cibles autorisés et de choisir le comportement de projection des tours diffusés en continu.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Agents ACP autorisés`},help:{"v1-f2mw0d-3a":`Liste des identifiants d’agents cibles ACP autorisés pour les sessions de l’environnement d’exécution ACP. Une liste vide n’impose aucune restriction supplémentaire.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Backend ACP`},help:{"v1-1s1l6bz-2v":`Identifiant du backend par défaut de l’environnement d’exécution ACP (par exemple : acpx). Doit correspondre au backend d’un plugin d’exécution ACP enregistré.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Agent ACP par défaut`},help:{"v1-7donnu-2c":`Identifiant de l’agent cible ACP de secours utilisé lorsque les lancements ACP ne précisent pas explicitement de cible.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Répartition ACP activée`},help:{"v1-1ug9t9m-3w":`Contrôle indépendant de la répartition des tours de session ACP (par défaut : true). Définissez la valeur sur false pour garder les commandes ACP disponibles tout en bloquant l’exécution des tours ACP.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP activé`},help:{"v1-1uonl1v-2a":`Contrôle global de la fonctionnalité ACP. Laissez-le désactivé tant que l’environnement d’exécution ACP et la politique ne sont pas configurés.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Backends de secours ACP`},help:{"v1-1wvdifq-5m":`Liste ordonnée des identifiants des backends ACP de secours à essayer lorsque le backend principal échoue avec UNAVAILABLE (par exemple : limite de débit atteinte ou quota épuisé). Chaque entrée doit correspondre à un backend de plugin d’exécution ACP enregistré.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Commande d’installation de l’environnement d’exécution ACP`},help:{"v1-1jjuv9m-39":"Commande facultative d’installation ou de configuration destinée à l’opérateur, affichée par `/acp install` et `/acp doctor` lorsque le raccordement au backend ACP est manquant."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Flux ACP`},help:{"v1-1bka5p-2v":`Paramètres de projection du flux ACP pour la taille des fragments, la visibilité des métadonnées et le comportement de transmission sans doublons.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Mode de transmission du flux ACP`},help:{"v1-19gdmx1-3s":`Mode de transmission ACP : live diffuse progressivement la sortie projetée, tandis que final_only met en mémoire tampon toute la sortie ACP projetée jusqu’aux événements de fin de tour.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Suppression des répétitions dans le flux ACP`},help:{"v1-manh32-3d":`Lorsque la valeur est true (par défaut), supprime les lignes répétées de projection d’état ou d’outil ACP au cours d’un tour, sans modifier les événements ACP bruts.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Visibilité des balises du flux ACP`},help:{"v1-1ybhx22-34":`Remplacements de visibilité par sessionUpdate pour la projection ACP (par exemple usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agents`},help:{"v1-2rc4v8-55":`Racine de la configuration d’exécution des agents. Les éléments de même niveau à la racine définissent l’infrastructure et les valeurs par défaut communes aux agents ; agents.defaults définit le comportement de la boucle des agents ; les entrées des agents peuvent remplacer les paramètres de l’un ou de l’autre lorsque cela est pris en charge.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Paramètres par défaut des agents`},help:{"v1-1af7k5b-5a":`Paramètres par défaut partagés dont héritent les agents, sauf s’ils sont remplacés dans une entrée de agents.entries. Utilisez les valeurs par défaut pour garantir un comportement de base cohérent et réduire les doublons dans la configuration de chaque agent.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Cible de l’héritage d’authentification`},help:{"v1-2d16wl-2x":`Propriétaire du magasin d’identifiants hérité, défini pour assurer la compatibilité lors de la mise à niveau, jusqu’à ce que les identifiants soient déplacés vers chaque agent.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Propriétaire de l’héritage d’authentification`},help:{"v1-1a1s7nm-4s":`Agent dont l’ancien magasin d’identifiants reste la source d’héritage après le retrait du marqueur par défaut. Renseigné automatiquement lors de la mise à niveau lorsque l’ancien propriétaire n’était pas main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Nombre maximal de caractères d’amorçage`},help:{"v1-drlo3i-37":`Nombre maximal de caractères de chaque fichier d’amorçage de l’espace de travail injectés dans le prompt système avant troncature (par défaut : 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Nombre total maximal de caractères d’amorçage`},help:{"v1-1evwsjb-2c":`Nombre total maximal de caractères pour l’ensemble des fichiers d’amorçage de l’espace de travail injectés (par défaut : 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Compactage`},help:{"v1-1qxdwz8-5p":`Comportement du compactage lorsque le contexte approche des limites de tokens, notamment la stratégie et le comportement de sauvegarde de la mémoire avant compactage. Utilisez ce réglage lorsque les sessions de longue durée nécessitent une continuité stable avec des fenêtres de contexte restreintes.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Compactage automatique intégré`},help:{"v1-1et7vwu-5l":`Active la compaction automatique proactive intégrée (par défaut : true). Définissez sur false pour arrêter la compaction intégrée déclenchée par un seuil, tout en conservant la récupération après dépassement d’OpenClaw, la compaction préalable et la commande manuelle /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Politique de conservation des identifiants lors de la compaction`},help:{"v1-hby01l-4l":`Politique de conservation des identifiants dans les résumés de compaction : "strict" ajoute en préfixe les consignes intégrées de conservation des identifiants opaques (par défaut), tandis que "off" désactive ce préfixe.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Tokens récents à conserver lors de la compaction`},help:{"v1-tgysub-5h":`Budget minimal de tokens conservés dans la fenêtre de conversation la plus récente lors de la compaction. Utilisez des valeurs plus élevées pour préserver la continuité du contexte immédiat et des valeurs plus faibles pour conserver davantage d’historique ancien.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-476m1y-11":`Seuil de taille de la conversation active pour la compaction`},help:{"v1-7p9ney-ah":`Seuil en octets déclenchant la compaction locale préalable dans l’environnement d’exécution intégré (octets ou chaînes telles que "20mb"). Pour Codex app-server, limite plutôt l’historique initial des nouveaux fils : une seule tentative de résumé par l’hôte, uniquement si une partie de l’historique non résumé serait omise, jamais lors des échanges ordinaires ni après un /compact natif. Définissez la valeur sur 0 ou laissez-la non définie pour désactiver cette fonction. Les garde-fous natifs de taille de rollout et de nombre de tokens restent inchangés.`}},"agents%2Edefaults%2Ecompaction%2EmaxSummaryChars":{label:{"v1-18p81ru-x":`Nombre maximal de caractères du résumé de compactage`},help:{"v1-em0nj5-8b":`Nombre maximal de caractères dans un résumé de compactage enregistré côté client (par défaut : 16000 ; plage : 1000–200000). Les résumés plus longs conservent davantage de contexte généré, mais augmentent le coût de réutilisation lors des requêtes ultérieures. Le budget de tokens du modèle actif peut imposer un résumé plus court. Ce paramètre ne contrôle pas le compactage natif du fournisseur.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Sauvegarde de la mémoire avant compaction`},help:{"v1-1xbzc1i-6t":`Paramètres de sauvegarde de la mémoire avant compactage, qui déclenchent une écriture en mémoire par l’agent avec le modèle de la session active et sa chaîne de repli habituelle avant un compactage important. Laissez cette option activée pour les longues sessions afin de conserver les éléments de contexte essentiels avant une réduction drastique.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Sauvegarde de la mémoire avant compactage activée`},help:{"v1-9xllgp-5o":`Active la sauvegarde de la mémoire avant que l’environnement d’exécution ne réduise davantage l’historique à l’approche des limites de tokens. Laissez cette option activée, sauf si vous souhaitez désactiver les effets sur la mémoire dans les environnements contraints.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-1mr3mj1-17":`Seuil de taille de la conversation pour la sauvegarde de la mémoire avant compaction`},help:{"v1-pihai2-8y":`Force la sauvegarde de la mémoire avant compaction lorsque l’historique de conversation visible par le modèle atteint ce seuil (en octets ou sous forme de chaînes telles que "2mb"). Après compaction, cela comprend la fin de l’historique conservée et les échanges suivants, plutôt que l’historique supprimé. Utilisez ce paramètre pour éviter les blocages lors des longues sessions, même lorsque les compteurs de tokens ne sont plus à jour ; définissez-le sur 0 pour le désactiver.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Seuil souple de sauvegarde de la mémoire avant compactage`},help:{"v1-1dqo2l1-5c":`Marge avant le compactage (en tokens) qui déclenche la sauvegarde de la mémoire. Utilisez des seuils plus précoces pour une conservation plus sûre, ou des seuils plus proches du compactage pour réduire la fréquence des sauvegardes.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Vérification préalable du compactage en cours de tour`},help:{"v1-12ud1gw-6c":`Seuil facultatif de pression estimée entre les cycles d’outils, utilisant la réserve de compactage. Le maintien du seuil mesuré par le fournisseur et le contrôle strict d’admission dans la fenêtre de contexte s’exécutent indépendamment, en réutilisant les mécanismes de récupération par troncature sûre ou compactage.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Vérification préalable du compactage en cours de tour activée`},help:{"v1-1or5cwa-57":`Active le seuil facultatif de pression estimée entre les cycles d’outils. Valeur par défaut : false. Le maintien du seuil mesuré et le contrôle strict de la fenêtre de contexte restent actifs lorsque cette option est désactivée.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Mode de compactage`},help:{"v1-1unahwc-76":`Mode de la stratégie de compactage : "safeguard" (mode appliqué par défaut si aucune valeur n’est définie) utilise des garde-fous pour préserver le contexte récent, tandis que "default" utilise une synthèse de base sans ces protections. Définissez "default" uniquement si la synthèse en mode "safeguard" pose des problèmes avec votre fournisseur.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Remplacement du modèle de compactage`},help:{"v1-cfeys9-6q":`Référence facultative au format fournisseur/modèle ou alias simple configuré, utilisé uniquement pour la synthèse lors du compactage. Les alias simples sont résolus avant l’envoi ; un identifiant de modèle littéral configuré est prioritaire en cas de conflit avec un alias. Laissez ce paramètre non défini pour continuer à utiliser le modèle principal de l’agent.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Notification de l’utilisateur lors du compactage`},help:{"v1-lvymm8-bv":`Lorsque cette option est activée, de brèves notifications de maintenance du contexte sont envoyées à l’utilisateur : au début et à la fin de la compaction (par exemple, « 🧹 Compaction du contexte... » et « 🧹 Compaction terminée »), ainsi que lorsque les tentatives de vidage de la mémoire avant la compaction sont épuisées et que la réponse se poursuit en mode dégradé (par exemple, « ⚠️ La maintenance de la mémoire a temporairement échoué ; la rédaction de votre réponse se poursuit. »). Cette option est désactivée par défaut pour que la maintenance du contexte reste silencieuse et discrète.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Sections de contexte après compaction`},help:{"v1-1n0ln2u-5f":`Noms des sections H2/H3 de AGENTS.md à réinjecter après la compaction, sur activation explicite. Laissez ce paramètre non défini ou définissez-le sur [] pour désactiver la réinjection. Définissez-le explicitement sur ["Session Startup", "Red Lines"] pour activer l’ancienne paire de sections par défaut.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Synchronisation de l’index après compaction`},help:{"v1-ekpjeq-6l":`Contrôle le mode de réindexation de la mémoire de session après la compaction : "off", "async" ou "await" (par défaut : "async"). Utilisez "await" pour garantir des données aussi à jour que possible, "async" pour réduire la latence de compaction et "off" uniquement si la synchronisation de la mémoire de session est gérée ailleurs.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Fournisseur de compaction`},help:{"v1-2zoy3b-7v":`Identifiant d’un plugin fournisseur de compactage enregistré, utilisé pour la génération de résumés. Lorsque cet identifiant est défini et que le fournisseur est enregistré, sa méthode summarize() est appelée à la place de la requête de résumé intégrée. En cas d’échec du fournisseur, le mécanisme intégré prend le relais. Laissez ce paramètre non défini pour utiliser la génération de résumés intégrée par défaut.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Contrôle qualité de la compaction`},help:{"v1-u9ognp-4k":`Paramètres de nouvelle tentative d’audit qualité pour les résumés de compactage en mode de protection. Ce mode active cette fonctionnalité par défaut ; définissez enabled: false pour ignorer les audits et la régénération des résumés.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Contrôle qualité du compactage activé`},help:{"v1-1xk2vt3-36":`Active les audits qualité des résumés et les nouvelles tentatives de régénération pour le compactage en mode de protection. Valeur par défaut : true en mode de protection.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Nombre maximal de nouvelles tentatives du contrôle qualité du compactage`},help:{"v1-n7l46y-3y":`Nombre maximal de nouvelles tentatives de régénération après l’échec d’un audit qualité du résumé en mode de protection. Utilisez de petites valeurs pour limiter la latence supplémentaire et le coût en jetons.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Conservation des échanges récents lors du compactage`},help:{"v1-y34ihi-5k":`Nombre d’échanges utilisateur/assistant les plus récents conservés tels quels, sans être inclus dans le résumé en mode de protection (valeur par défaut : 3). Augmentez cette valeur pour préserver le contexte exact du dialogue récent, ou réduisez-la pour maximiser les économies réalisées par le compactage.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Niveau de réflexion du compactage`},help:{"v1-1vafgaw-g1":`Niveau de réflexion utilisé uniquement pour les résumés de compactage intégrés d’OpenClaw : "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" ou "inherit". Utilise par défaut la préférence de compactage du fournisseur, sinon "low" ; l’intégration native locale d’Ollama privilégie "off". Définissez "inherit" pour réutiliser le niveau de la session. Les paramètres explicites remplacent les valeurs par défaut du fournisseur, et le niveau sélectionné est limité aux capacités du modèle et de l’environnement d’exécution réellement utilisés pour le compactage. Le compactage natif de Codex app-server ignore ce paramètre, car sa requête de compactage ne permet pas de remplacer le niveau de réflexion pour chaque opération ; OpenClaw consigne alors un avertissement.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Délai d’expiration du compactage (secondes)`},help:{"v1-p0ymcy-c4":`Durée en secondes pendant laquelle une requête au modèle de compaction intégré peut rester sans progression (par défaut : 180). Chaque début de requête et chaque token de sortie diffusé en continu réinitialisent ce délai ; une requête lente qui continue à produire des tokens n’est donc pas interrompue. La compaction complète s’arrête après 10 périodes de ce type. La compaction gérée par un plugin dispose d’une seule période, sauf si le moteur déclare explicitement onProgress dans info.acceptedHostParams et signale sa progression ; le même plafond de 10 périodes s’applique.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Injection de contexte`},help:{"v1-u18x0-7u":`Contrôle l’injection des fichiers d’initialisation de l’espace de travail dans l’environnement d’exécution intégré : "always" utilise l’injection normale (par défaut), "continuation-skip" ignore les tours de continuation admissibles après un tour enregistré avec initialisation complète, et "never" désactive l’injection. Ne contrôle pas la préparation des prompts via la CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Limites de contexte par défaut`},help:{"v1-1coeez8-5d":`Valeurs par défaut ciblées du budget de contexte de chaque agent pour certains extraits volumineux et blocs de prompt injectés. Permet d’ajuster les limites de taille des lectures et des injections sans réactiver de chemins d’appel non bornés.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Nombre maximal de caractères par défaut pour memory_get`},help:{"v1-1qb40qv-4v":`Nombre maximal de caractères renvoyés par défaut par memory_get avant l’ajout des métadonnées de troncature et de l’avis de continuation. Augmentez cette valeur pour retrouver des extraits plus longs, comme auparavant, tout en conservant une limite raisonnable.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Nombre maximal de caractères après compactage par défaut`},help:{"v1-64qo8g-5r":`Nombre maximal de caractères conservés par défaut depuis AGENTS.md lors de l’injection de rafraîchissement du contexte après compactage. Réduisez cette valeur pour diminuer le coût de la reprise après compactage, ou augmentez-la pour les agents qui dépendent de consignes de démarrage plus longues.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Répertoire de travail`},help:{"v1-1y8wlxn-6a":`Répertoire de travail pour les exécutions de réponse de l’agent, distinct de l’initialisation de l’espace de travail et des fichiers de mémoire. Les valeurs cwd propres à l’agent et celles définies à la création d’une session sont prioritaires. Prend en charge ~ et les chemins relatifs ; un cwd distinct nécessite une exécution hors bac à sable.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Modèle de décision`},help:{"v1-7nd7ze-64":`Fournisseur/modèle facultatif pour les choix typés, les scores et les probabilités booléennes. Une valeur non définie ou vide désactive les appels de décision. Les plugins compatibles envoient à ce fournisseur un ensemble limité d’éléments contextuels liés à la tâche ; les modèles de conversation et utilitaires restent inchangés.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`OpenClaw intégré`},help:{"v1-1keek32-3k":`Contrôles de renforcement de la sécurité du moteur d’exécution OpenClaw intégré, qui déterminent comment les paramètres d’agent locaux à l’espace de travail sont considérés comme fiables et appliqués dans les sessions OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Basculement en cas de refus lié à la politique de cybersécurité`},help:{"v1-pl298d-4c":`Escalade automatique vers Daybreak avec le même modèle en cas de refus liés à la politique de cybersécurité d’OpenAI pouvant être retentés sans risque dans l’environnement d’exécution intégré, sous réserve des contrôles d’accès et de conformité existants.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Délai d’attente du basculement lié à la politique de cybersécurité`},help:{"v1-1hhmb1o-2l":`Durée pendant laquelle l’accès indisponible à Daybreak pour le modèle actif est ignoré au cours de la session actuelle.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Mode de basculement lié à la politique de cybersécurité`},help:{"v1-rzsd2b-2h":`Activer l’escalade automatique ("auto", par défaut) ou conserver les refus du fournisseur comme définitifs ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Contrat d’exécution d’OpenClaw intégré`},help:{"v1-1fch2ig-66":`Contrat d’exécution d’OpenClaw intégré : "default" conserve le comportement standard du moteur d’exécution, tandis que "strict-agentic" active le suivi structuré des plans et la reprise non visible des tours pour les exécutions compatibles de la famille GPT-5 d’OpenAI/OpenAI Codex.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Politique des paramètres de projet d’OpenClaw intégré`},help:{"v1-fdyy04-65":'Définit la manière dont OpenClaw intégré gère le fichier `.openclaw/settings.json` local à l’espace de travail : "sanitize" (par défaut) supprime shellPath/shellCommandPrefix, "ignore" désactive entièrement les paramètres du projet et "trusted" les applique tels quels.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Options expérimentales de l’agent`},help:{"v1-cvv5cl-2w":`Options expérimentales par défaut de l’agent. Laissez-les désactivées, sauf si vous testez volontairement une fonctionnalité en préversion.`}},"agents%2Edefaults%2Eexperimental%2EdecisionAssistance":{label:{"v1-1tepbyi-y":`Aide à la décision (expérimental)`},help:{"v1-1fmo3r9-ew":`Activation globale de l’assistance expérimentale du modèle Decision configuré pour l’agent concerné (par défaut : false ; nécessite la valeur explicite true). Le decisionModel effectif peut être hérité des paramètres globaux par défaut ou sélectionné pour chaque agent ; une valeur vide pour un agent désactive l’assistance. Les utilisations prises en charge peuvent envoyer certaines données à ce fournisseur et entraîner des frais facturés par celui-ci. Consultez la documentation de l’assistance Decision pour connaître les utilisations prises en charge, la configuration et le traitement des données. Ce paramètre ne conditionne pas les appels explicites à decision_evaluate, ne sélectionne aucun fournisseur et n’autorise aucune action.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Activer le mode allégé pour les modèles locaux (expérimental)`},help:{"v1-gj06u6-7b":`Paramètre de dépannage avancé qui restreint les outils facultatifs tels que browser, automations et message. Désactivé par défaut ; les environnements d’exécution locaux pris en charge utilisent la recherche automatique d’outils sans cette restriction. Les autorisations explicites d’outils et les outils de livraison requis sont conservés.`}},"agents%2Edefaults%2Eexperimental%2EusageRankedToolIndex":{label:{"v1-ndslef-12":`Index des outils classé par utilisation (expérimental)`},help:{"v1-1jpzjov-bq":`Activer le classement par utilisation des index de prompt de Code Mode, de Tool Search et du répertoire d’outils MCP dans l’environnement d’exécution OpenClaw intégré (par défaut : false). Stocke uniquement les identifiants d’outils, les scores à décroissance temporelle et les horodatages dans le stockage de l’agent appartenant à l’opérateur pendant 90 jours ; exclut les sessions de navigation privée. Les classements restent figés jusqu’à une limite de préfixe de prompt. Ne modifie ni les autorisations des outils ni Codex. Consultez les données, importez l’historique d’utilisation ou réinitialisez-les avec openclaw tools usage.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Mode rapide par défaut de l’agent`},help:{"v1-6q8gx8-3c":`Politique par défaut du mode rapide pour la boucle de l’agent ("auto", "ultrafast", true ou false). Les paramètres propres à chaque agent prévalent sur cette politique.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Délai humain maximal (ms)`},help:{"v1-vnmvli-1m":`Délai maximal en ms pour le paramètre humanDelay personnalisé (par défaut : 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Délai humain minimal (ms)`},help:{"v1-5nrtr5-1l":`Délai minimal en ms pour le paramètre humanDelay personnalisé (par défaut : 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Mode de délai humain`},help:{"v1-k7hyg3-1n":`Type de délai pour les réponses par blocs ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Dimension maximale des images (px)`},help:{"v1-1j31o2j-2s":`Longueur maximale du côté d’une image, en pixels, lors de l’assainissement des données d’image des conversations et des résultats d’outils (par défaut : 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Modèles d’image de secours`},help:{"v1-1kgx5i9-1b":`Modèles d’image de secours par ordre de priorité (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Modèle d’image`},help:{"v1-dstqyh-2c":`Modèle d’image facultatif (provider/model) utilisé lorsque le modèle principal ne prend pas en charge les images en entrée.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Qualité des images`},help:{"v1-1uyxc5s-6u":`Préférence de compression des médias pour l’outil d’image : "auto" s’adapte aux limites du fournisseur et du modèle ainsi qu’au nombre d’images, "efficient" économise des tokens et des octets, "balanced" conserve le compromis actuel et "high" préserve davantage de détails pour les captures d’écran et les images de documents.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Modèles de secours pour la génération d’images`},help:{"v1-oljfk4-1m":`Modèles de secours pour la génération d’images, par ordre de priorité (fournisseur/modèle).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Modèle de génération d’images`},help:{"v1-g4yw0h-2o":`Modèle facultatif de génération d’images (fournisseur/modèle) utilisé par la fonctionnalité partagée de génération d’images.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Délai d’expiration de la génération d’images (ms)`},help:{"v1-9yesfj-31":`Délai d’expiration par défaut des requêtes au fournisseur, en millisecondes, pour les appels image_generate. Le paramètre timeoutMs défini pour chaque appel remplace cette valeur.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Modèles de secours pour la génération de musique`},help:{"v1-wyg9xe-1m":`Modèles de secours pour la génération de musique, par ordre de priorité (fournisseur/modèle).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Modèle de génération de musique`},help:{"v1-xs1e2h-2o":`Modèle facultatif de génération de musique (fournisseur/modèle) utilisé par la fonctionnalité partagée de génération de musique.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Modèles de secours pour la génération de vidéos`},help:{"v1-wpbf1e-1m":`Modèles de génération vidéo de secours, par ordre de priorité (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Modèle de génération vidéo`},help:{"v1-hfmlbl-2o":`Modèle de génération vidéo facultatif (provider/model) utilisé par la fonctionnalité partagée de génération vidéo.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Délai d’expiration de la génération vidéo (ms)`},help:{"v1-1bqj80s-4i":`Délai d’expiration par défaut des requêtes au fournisseur, en millisecondes, pour les appels video_generate. Le paramètre timeoutMs défini pour chaque appel remplace cette valeur, qui remplace elle-même les valeurs par défaut définies par le fournisseur.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Modèles de secours`},help:{"v1-t4djq2-24":`Modèles de secours, par ordre de priorité (provider/model). Utilisés en cas d’échec du modèle principal.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Modèle principal`},help:{"v1-1i8a1v4-v":`Modèle principal (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Politique des modèles`},help:{"v1-z0txb7-2e":`Politique explicite de remplacement du modèle. Omettez-la ou laissez allow vide pour autoriser n’importe quel modèle.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Modèles autorisés`},help:{"v1-1vy0b57-5c":`Références autorisées pour le remplacement du modèle. Accepte les alias, les références complètes « provider/model » et les préfixes suivis d’un caractère générique tels que « openai/* », « clawrouter/anthropic/* » ou « openai/gpt-* ». Si la liste est vide, tous les modèles sont autorisés.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modèles`},help:{"v1-13cvq23-4i":`Catalogue des modèles configurés et paramètres propres à chaque modèle. Les entrées fournissent des alias, des paramètres, des métadonnées d’exécution et des remplacements pour Code Mode ; elles ne limitent pas les remplacements du modèle.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Environnement d’exécution du modèle de l’agent par défaut`},help:{"v1-6km9kx-41":`Politique d’exécution facultative par modèle pour l’agent par défaut. Utilisez-la pour définir des exceptions d’exécution propres à un modèle plutôt qu’un environnement d’exécution pour l’ensemble de l’agent.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`Identifiant de l’environnement d’exécution du modèle de l’agent par défaut`},help:{"v1-1co96w7-4a":`Identifiant de l’environnement d’exécution du modèle de l’agent par défaut : "openclaw", "auto", un identifiant de harnais de plugin enregistré tel que "codex", ou un alias de backend CLI pris en charge tel que "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Mode Code`},help:{"v1-rsdl5o-6x":`Mode code OpenClaw pour cette combinaison précise de fournisseur et de modèle : Activé force son activation, Désactivé le désactive et Par défaut hérite de tools.codeMode.enabled. Les paramètres d’activation propres à l’agent sont prioritaires. Cela ne modifie ni l’environnement d’exécution sélectionné ni le mode code natif de Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Portée de la sélection du modèle`},help:{"v1-sj8owq-bl":`Portée des commandes de chat et des mises à jour du modèle de session du Gateway sans portée explicite : "session" (par défaut) modifie uniquement la session en cours, "agent" met également à jour le modèle principal de cet agent et "global" met également à jour le modèle de repli partagé agents.defaults.model. Les options de portée explicites sont prioritaires ; les modifications des valeurs par défaut configurées nécessitent des droits de propriétaire ou d’administrateur. Les sélecteurs de rappel Telegram et l’interface textuelle locale intégrée restent limités à la session.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Taille maximale des PDF (Mo)`},help:{"v1-1uig1dr-1u":`Taille maximale des fichiers PDF en mégaoctets pour l’outil PDF (par défaut : 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Nombre maximal de pages des PDF`},help:{"v1-11na7hp-1y":`Nombre maximal de pages PDF à traiter par l’outil PDF (par défaut : 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Modèles PDF de secours`},help:{"v1-89ebd8-19":`Modèles PDF de secours par ordre de priorité (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Modèle PDF`},help:{"v1-2ktkxt-2y":`Modèle PDF facultatif (provider/model) pour l’outil d’analyse PDF. Utilise par défaut imageModel, puis le modèle de la session.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Racine du dépôt`},help:{"v1-j3sh74-2h":`Racine du dépôt facultative affichée dans la ligne d’informations d’exécution du prompt système (remplace la détection automatique).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Plage de ports source CDP du navigateur en bac à sable`},help:{"v1-1jkowdc-2b":`Liste d’autorisation CIDR facultative pour le trafic CDP entrant à la périphérie du conteneur (par exemple 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Réseau du navigateur en bac à sable`},help:{"v1-8m74ud-5w":`Réseau Docker pour les conteneurs de navigateur en bac à sable (par défaut : openclaw-sandbox-browser). Utilisez le réseau dédié par défaut ou un réseau de type bridge personnalisé ; "none" n’est pas pris en charge, car le contrôle du navigateur nécessite des ports CDP publiés.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Autoriser Docker en bac à sable à rejoindre l’espace de noms d’un conteneur`},help:{"v1-qm39de-4c":`Dérogation d’urgence DANGEREUSE autorisant le mode réseau Docker container:<id> en bac à sable. Ce mode rejoint l’espace de noms d’un autre conteneur et affaiblit l’isolation du bac à sable.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU Docker du bac à sable`},help:{"v1-jj0yhw-4k":`Valeur facultative d’accès direct aux GPU pour Docker, transmise à --gpus, par exemple "all" ou "device=GPU-uuid". Nécessite un environnement d’exécution compatible sur l’hôte, tel que NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Cible de l’ancien stockage de sessions`},help:{"v1-1xkej6i-2g":`Propriétaire utilisé pour assurer la compatibilité lors de la mise à niveau des anciennes lignes main-agent et des anciens stockages de sessions fixes.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Propriétaire de l’ancien stockage de sessions`},help:{"v1-ommm7e-5w":`Agent propriétaire des anciennes lignes main-agent ou des lignes sans périmètre dans un ancien stockage de sessions fixe après le retrait du marqueur par défaut. Renseigné automatiquement lors de la mise à niveau lorsque l’ancien propriétaire n’était ni main ni l’unique agent.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Liste facultative des compétences autorisées par défaut, dont héritent les agents qui omettent agents.entries.*.skills. Omettez-la pour ne pas restreindre les compétences, définissez [] pour n’accorder aucune compétence aux agents qui en héritent, et notez qu’une valeur explicite de agents.entries.*.skills remplace cette valeur par défaut au lieu de fusionner avec elle.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Ignorer la création des fichiers d’initialisation de l’espace de travail`},help:{"v1-kbstgw-5v":`Ignore la création automatique des fichiers d’initialisation de l’espace de travail, mais pas l’injection des fichiers existants. Pour l’environnement d’exécution intégré, définissez agents.defaults.contextInjection sur "never" pour désactiver l’injection, sauf si ce paramètre est remplacé au niveau d’un agent.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Fichiers d’initialisation facultatifs ignorés`},help:{"v1-1j2z4yj-4c":`Fichiers d’initialisation facultatifs qui ne doivent pas être créés dans les espaces de travail des agents. Valeurs valides : SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md est accepté, mais sans effet).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Contexte de démarrage`},help:{"v1-1ugsihy-5o":`Préambule du premier tour géré par l’environnement d’exécution pour les commandes "/new" et "/reset" sans arguments. Utilisez ce paramètre pour contrôler le préchargement des fichiers de mémoire quotidienne récents dans le premier prompt, plutôt que de demander au modèle de décider quoi lire.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Commandes auxquelles appliquer le contexte de démarrage`},help:{"v1-wav4a5-36":`Détermine quelles commandes de réinitialisation sans arguments reçoivent le contexte de démarrage : incluez "new", "reset" ou les deux (par défaut : ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Nombre de jours de mémoire quotidienne du contexte de démarrage`},help:{"v1-4i5xcm-3p":`Nombre de fichiers de mémoire datés à charger en remontant à partir d’aujourd’hui dans le fuseau horaire configuré pour l’utilisateur (par défaut : 2 pour aujourd’hui et hier).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Activer le contexte de démarrage`},help:{"v1-1d5vz2u-4i":`Active le préambule du contexte de démarrage pour les réinitialisations de session sans arguments (par défaut : true). Désactivez ce paramètre pour revenir à un fonctionnement reposant uniquement sur le prompt, sans mémoire quotidienne chargée par l’environnement d’exécution.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Nombre maximal d’octets par fichier du contexte de démarrage`},help:{"v1-11cbian-41":`Nombre maximal d’octets autorisés par fichier de mémoire quotidienne lors de la création du contexte de démarrage (par défaut : 16384). Les fichiers dépassant cette limite de lecture sécurisée sont ignorés.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Nombre maximal de caractères par fichier du contexte de démarrage`},help:{"v1-10z53s-2u":`Nombre maximal de caractères conservés de chaque fichier de mémoire quotidienne chargé dans le préambule de démarrage (par défaut : 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Nombre total maximal de caractères du contexte de démarrage`},help:{"v1-sf676u-54":`Nombre maximal de caractères conservés dans l’ensemble des fichiers de mémoire quotidienne chargés dans le préambule de démarrage (par défaut : 2800). Une fois cette limite atteinte, le contenu des fichiers supplémentaires est tronqué dans le préambule.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Mode de délégation aux sous-agents`},help:{"v1-pqewbk-5o":`Niveau d’incitation à déléguer aux sous-agents, appliqué uniquement par les instructions du prompt. La valeur par défaut est "prefer" dans la session principale de chaque agent et "suggest" ailleurs ; "prefer" enjoint fortement à l’agent de déléguer les tâches non triviales via sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Cible de l’agent système`},help:{"v1-1wwimo9-34":`Paramètres cibles pour les inférences en arrière-plan de l’agent système OpenClaw et de Custodian, ainsi que pour certaines opérations de lecture de l’opérateur sans portée définie.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Propriétaire de l’agent système`},help:{"v1-15rvt92-8c":`Agent dont le modèle et les identifiants sont utilisés pour les consultations en arrière-plan de l’agent système et de Custodian. Également utilisé lorsque models.list, models.authStatus, skills.status, doctor.memory.status ou une commande CLI infer qui détermine le modèle ou l’état d’authentification propre à un agent omet agentId ou --agent ; un agentId explicite dans la requête est toujours prioritaire.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Intervalle de saisie (secondes)`},help:{"v1-1y701ox-42":`Définit la fréquence de rafraîchissement de l’indicateur de saisie en secondes pour chaque agent. Augmentez cette valeur pour réduire la fréquence des mises à jour sur tous les canaux prenant en charge cet indicateur.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Mode de saisie`},help:{"v1-m2hvpw-3m":`Détermine quand l’indicateur de saisie s’active pour les agents : "never", "instant", "thinking" ou "message". Le paramètre typingMode de chaque agent remplace cette valeur par défaut.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Modèle utilitaire`},help:{"v1-1cfea4z-cl":`Modèle facultatif moins coûteux (provider/model, alias ou { primary, fallbacks }) pour de courtes tâches internes, comme la génération de titres et la description de la progression. Les modèles utilitaires de secours suivent les mêmes règles de nouvelle tentative, de résolution des alias et de sélection de modèle que les modèles de secours configurés, indépendamment de model.fallbacks. Si cette option n’est pas définie, le petit modèle déclaré par le fournisseur principal est utilisé lorsqu’il est disponible (sinon, le modèle principal). Définissez une chaîne vide pour désactiver le routage vers un modèle utilitaire.`}},"agents%2Edefaults%2EutilityModel%2Efallbacks":{label:{"v1-rlvlnh-n":`Modèles utilitaires de secours`},help:{"v1-12k3amd-2v":`Liste ordonnée des modèles utilitaires de secours (provider/model ou alias), indépendante de la liste des modèles de secours du modèle principal.`}},"agents%2Edefaults%2EutilityModel%2Eprimary":{label:{"v1-1rpgua8-l":`Modèle utilitaire principal`},help:{"v1-11k8uor-1c":`Modèle utilitaire principal (fournisseur/modèle ou alias).`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Modèles vocaux de secours`},help:{"v1-faazv4-1b":`Modèles vocaux de secours par ordre de priorité (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Modèle vocal`},help:{"v1-1yeh3h4-2t":`Modèle vocal facultatif (provider/model) utilisé par les fonctionnalités de synthèse vocale, de transcription et de voix en temps réel.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Délai d’expiration vocal (ms)`},help:{"v1-1sbergs-32":`Délai d’expiration par défaut des requêtes au fournisseur, en millisecondes, pour les opérations du modèle vocal, lorsque l’appelant prend en charge les délais d’expiration.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Espace de travail`},help:{"v1-1u5ipll-5t":`Espace de travail par défaut de l’agent pour les fichiers d’initialisation et de mémoire. Également utilisé comme répertoire de travail lorsque agents.defaults.cwd n’est pas défini. Définissez-le explicitement lors de l’exécution via des scripts enveloppants afin de garantir une résolution cohérente des chemins.`}},"agents%2Edefaults%2EworkspaceFileMode":{label:{"v1-13trwkt-k":`Mode des nouveaux fichiers de mémoire`},help:{"v1-11pw0mp-9b":`Permissions des nouveaux fichiers DREAMS.md et MEMORY.md de memory-core et des rapports memory/dreaming : "0600", "0620", "0640" ou "0660". Si ce paramètre n’est pas défini, le mode reste exactement 0600 ; les modes configurés respectent l’umask de l’hôte qui effectue l’écriture. Les fichiers existants, la mémoire quotidienne, le corpus des sessions et l’état privé restent inchangés. Les droits de traversée des répertoires et les ACL par défaut doivent être configurés séparément.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Liste des agents`},help:{"v1-1e0blk1-5i":`Liste explicite des agents configurés, avec leurs identifiants et des paramètres de remplacement facultatifs pour le modèle, les outils, l’identité et l’espace de travail. Conservez des identifiants stables dans le temps afin que les associations, les approbations et le routage des sessions restent cohérents.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Ancien environnement d’exécution de l’agent`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`Identifiant de l’ancien environnement d’exécution de l’agent`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Nombre maximal de caractères par fichier d’initialisation de l’agent`},help:{"v1-rsf1es-4j":`Remplacement par agent du nombre maximal de caractères de chaque fichier d’initialisation de l’espace de travail injecté dans le prompt système de cet agent. Omettez ce paramètre pour hériter de agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Nombre total maximal de caractères d’initialisation de l’agent`},help:{"v1-1bal68p-4y":`Remplacement par agent du nombre total maximal de caractères de l’ensemble des fichiers d’initialisation de l’espace de travail injectés dans le prompt système de cet agent. Omettez ce paramètre pour hériter de agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2Ecompaction":{label:{"v1-1kqcx8z-g":`Compactage de l’agent`},help:{"v1-ioyi1g-2o":`Paramètres de compactage côté client propres à chaque agent. Les paramètres non définis héritent de agents.defaults.compaction.`}},"agents%2Eentries%2E*%2Ecompaction%2EmaxSummaryChars":{label:{"v1-1vend8r-13":`Nombre maximal de caractères du résumé de compactage de l’agent`},help:{"v1-1fwu60v-58":`Nombre maximal de caractères du résumé enregistré côté client pour chaque agent (1000–200000), remplaçant agents.defaults.compaction.maxSummaryChars. Le budget de tokens du modèle actif peut imposer un résumé plus court.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Injection de contexte de l’agent`},help:{"v1-1j68ys8-50":`Paramètre propre à chaque agent pour l’injection des fichiers d’amorçage de l’espace de travail dans l’environnement d’exécution intégré. Omettez-le pour hériter de agents.defaults.contextInjection. Ne contrôle pas la préparation des prompts effectuée via la CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Limites de contexte de l’agent`},help:{"v1-f1qxq8-3c":`Remplacements facultatifs par agent des paramètres ciblés du budget de contexte. Les champs omis héritent de agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Nombre maximal de caractères de memory_get pour l’agent`},help:{"v1-12hlmsv-1v":`Remplacement par agent du budget maximal de caractères par défaut de memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Nombre maximal de caractères après compactage pour l’agent`},help:{"v1-15s0npd-1w":`Remplacement par agent du budget alloué aux extraits d’AGENTS.md après compactage.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Répertoire de travail de l’agent`},help:{"v1-mv43ak-6a":`Répertoire de travail pour les exécutions de réponse de cet agent. Remplace agents.defaults.cwd, mais pas le cwd défini lors de la création de la session ; les fichiers d’amorçage et de mémoire restent dans l’espace de travail. Prend en charge ~ et les chemins relatifs ; un cwd distinct nécessite une exécution hors bac à sable.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Modèle de décision de l’agent`},help:{"v1-1mih8bf-3j":`Modèle de décision propre à chaque agent. Si la valeur n’est pas définie, celle de agents.defaults.decisionModel est utilisée ; une chaîne vide désactive les appels de décision pour cet agent.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`OpenClaw intégré de l’agent`},help:{"v1-uoomza-4b":`Paramètres de remplacement facultatifs par agent pour OpenClaw intégré. Permet d’activer un comportement d’exécution GPT-5 plus strict pour certains agents sans modifier les paramètres globaux par défaut.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Contrat d’exécution d’OpenClaw intégré de l’agent`},help:{"v1-1d1jaoi-7k":`Remplacement facultatif par agent du contrat d’exécution d’OpenClaw intégré. Définissez "strict-agentic" pour activer le suivi structuré du plan et la récupération non visible des tours pour cet agent lors des exécutions compatibles avec les modèles de la famille GPT-5 d’OpenAI/OpenAI Codex, ou "default" pour hériter du comportement standard du moteur d’exécution.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Options expérimentales de l’agent`},help:{"v1-1r06jov-2a":`Options expérimentales par agent. Les champs omis héritent d’agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Mode allégé du modèle local de l’agent`},help:{"v1-5o3tgx-58":`Paramètre de dépannage propre à chaque agent pour le mode allégé des modèles locaux. Activez-le uniquement lorsque la restriction des outils facultatifs résout une défaillance avérée du modèle, sans réduire les outils de tous les agents.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Mode rapide par défaut de l’agent`},help:{"v1-ev6028-41":`Valeur par défaut facultative du mode rapide pour chaque agent ("auto", "ultrafast", true ou false). S’applique lorsqu’aucun paramètre de mode rapide propre au message ou à la session n’est défini.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Avatar de l’identité`},help:{"v1-pzp9gr-1t":`Avatar de l’agent (chemin relatif à l’espace de travail, URL http(s) ou URI de données).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Politique de modèles de l’agent`},help:{"v1-17d5je8-2r":`Politique de remplacement de modèle par agent. Une liste d’autorisation explicite remplace la politique par défaut pour cet agent.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Modèles autorisés pour l’agent`},help:{"v1-1enipb-5w":`Références autorisées pour le remplacement du modèle de cet agent. Accepte les alias, les références complètes « provider/model » et les préfixes suivis d’un caractère générique tels que « provider/* », « provider/namespace/* » ou « provider/family-* » ; si la liste est vide, tous les modèles sont autorisés.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Remplacements de modèles de l’agent`},help:{"v1-nld1vq-1v":`Remplacements du catalogue de modèles propres à chaque agent, indexés par les identifiants complets fournisseur/modèle.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Environnement d’exécution du modèle de l’agent`},help:{"v1-7b59y-3s":`Politique d’exécution facultative par modèle pour cet agent. Utilisez-la pour définir des exceptions de modèle propres à l’agent plutôt que de définir un environnement d’exécution pour l’ensemble de l’agent.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`Identifiant de l’environnement d’exécution du modèle de l’agent`},help:{"v1-1ckfc39-46":`Identifiant de l’environnement d’exécution du modèle propre à l’agent : "openclaw", "auto", un identifiant de harnais de plugin enregistré tel que "codex", ou un alias de backend CLI pris en charge tel que "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Mode Code`},help:{"v1-91zu7f-7m":`Mode code d’OpenClaw pour cet agent et cette combinaison exacte fournisseur/modèle : Activé force son activation, Désactivé le désactive et Par défaut reprend le paramètre d’activation de l’agent, puis le remplacement partagé du modèle, puis tools.codeMode.enabled. Cela ne modifie ni l’environnement d’exécution sélectionné ni le mode code natif de Codex.`}},"agents%2Eentries%2E*%2EnativeRuntimeConsent":{label:{"v1-r2vkr2-11":`Autorisations natives d’exécution mémorisées`},help:{"v1-1uktqfm-79":`Identifiants des environnements d’exécution autorisés à utiliser leurs autorisations natives pour cet agent. Les nouvelles conversations utilisent l’accès complet avec le bac à sable désactivé. Supprimez un identifiant pour révoquer immédiatement le consentement mémorisé ; le consentement explicite propre à chaque conversation reste inchangé. Les contraintes obligatoires de bac à sable et les limites de l’espace de travail continuent de s’appliquer.`}},"agents%2Eentries%2E*%2EnewSessionPermissionMode":{help:{"v1-15v8f6l-5p":`Mode d’autorisation enregistré pour les nouvelles sessions opérateur supervisées et dotées d’un profil lorsqu’aucun mode explicite n’est fourni. Ne modifie pas les sessions existantes, dérivées, déléguées ou autonomes. Le mode complet nécessite toujours operator.admin.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Visibilité du raisonnement par défaut de l’agent`},help:{"v1-13ly0xf-3m":`Visibilité du raisonnement par défaut facultative pour chaque agent (on|off|stream). S’applique lorsqu’aucun remplacement du paramètre de raisonnement n’est défini pour le message ou la session.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Environnement d’exécution de l’agent`},help:{"v1-avjgkf-3l":`Descripteur facultatif de l’environnement d’exécution de cet agent. Utilisez embedded pour l’exécution OpenClaw par défaut ou acp pour les paramètres par défaut d’un harnais ACP externe.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Environnement d’exécution ACP de l’agent`},help:{"v1-91zvdk-3i":`Paramètres par défaut de l’environnement d’exécution ACP pour cet agent lorsque runtime.type=acp. Les paramètres ACP définis au niveau de la liaison restent prioritaires pour chaque conversation.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agent du harnais ACP pour cet agent`},help:{"v1-1pm98vp-37":`Identifiant facultatif de l’agent du harnais ACP à utiliser pour cet agent OpenClaw (par exemple codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Backend ACP de l’agent`},help:{"v1-1u3cdsg-2n":`Backend ACP facultatif à utiliser pour les sessions ACP de cet agent à la place du paramètre global acp.backend.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Répertoire de travail ACP de l’agent`},help:{"v1-d9p9rf-1t":`Répertoire de travail par défaut facultatif pour les sessions ACP de cet agent.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Mode ACP de l’agent`},help:{"v1-yatuk4-21":`Mode de session ACP par défaut facultatif pour cet agent (persistent ou oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Type d’environnement d’exécution de l’agent`},help:{"v1-139fbk6-2r":`Type d’environnement d’exécution pour cet agent : "embedded" (environnement d’exécution OpenClaw par défaut) ou "acp" (paramètres par défaut du harnais ACP).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Plage source CDP du navigateur en bac à sable de l’agent`},help:{"v1-1q1qyso-1d":`Remplacement par agent de la liste des plages CIDR sources autorisées pour CDP.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Réseau du navigateur en bac à sable de l’agent`},help:{"v1-13bdfww-4c":`Remplacement par agent du réseau Docker du navigateur en bac à sable. Utilisez un réseau de type bridge ; "none" n’est pas pris en charge, car le contrôle du navigateur nécessite des ports CDP publiés.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Autoriser la jonction à un espace de noms de conteneur dans Docker pour le bac à sable de l’agent`},help:{"v1-1xtnseb-2i":`Dérogation DANGEREUSE par agent autorisant les jonctions aux espaces de noms de conteneurs en mode réseau Docker du bac à sable.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`GPU Docker du bac à sable de l’agent`},help:{"v1-1kek1n2-1t":`Remplacement par agent du paramètre d’accès direct aux GPU via Docker pour les conteneurs du bac à sable.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Filtre de compétences de l’agent`},help:{"v1-igchue-6v":`Liste facultative des compétences autorisées pour cet agent. Si elle est omise, l’agent hérite de agents.defaults.skills lorsque ce paramètre est défini ; sinon, les compétences restent sans restriction. Définissez [] pour n’autoriser aucune compétence. Une liste explicite remplace entièrement les valeurs par défaut héritées au lieu de fusionner avec elles.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Limites des Skills de l’agent`},help:{"v1-1sv10v9-4y":`Remplacements facultatifs par agent des budgets du sous-système de compétences. À utiliser lorsqu’un agent nécessite un budget différent pour le prompt des compétences, sans introduire une seconde configuration générique des limites de contexte.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Nombre maximal de caractères du prompt des Skills de l’agent`},help:{"v1-dys63y-52":`Remplacement par agent du budget de caractères du prompt des compétences. Ce paramètre étend le chemin existant skills.limits.maxSkillsPromptChars au lieu de faire passer ce même budget par contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegateToolsTo":{label:{"v1-bycm06-m":`Cibles de délégation des outils`},help:{"v1-y7q6z7-d6":`Agents cibles natifs configurés explicitement qui peuvent ignorer tools.deny de cet agent demandeur lors de leur lancement. Nécessite indépendamment allowAgents. Les transferts fondés uniquement sur des interdictions préservent toutes les restrictions non locales ; en présence de profils initiaux ou de listes d’autorisation restrictifs, ou de transports non pris en charge, le transfert est refusé plutôt que d’assouplir ces restrictions. Les assistants natifs visant la même cible conservent leurs propres limites supplémentaires. Les requêtes soumises à des restrictions liées à l’expéditeur et les requêtes ACP n’utilisent jamais cette autorisation. La révocation rétablit l’instantané d’origine du demandeur.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Mode de délégation aux sous-agents`},help:{"v1-1rkgh6p-4s":`Remplacement par agent du degré d’incitation à déléguer aux sous-agents. Omettez ce paramètre pour utiliser "prefer" dans la session principale de cet agent et "suggest" ailleurs ; une valeur explicite "prefer" ou "suggest" est toujours prioritaire.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Niveau de réflexion par défaut de l’agent`},help:{"v1-173q7vy-43":`Niveau de réflexion par défaut facultatif, propre à chaque agent. Remplace agents.defaults.thinkingDefault pour cet agent lorsqu’aucun remplacement par message ou par session n’est défini.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent":{label:{"v1-q7r7ya-o":`Messagerie sortante de l’agent`},help:{"v1-xo2o9d-5d":`Politique de messagerie de l’agent limitée aux envois sortants. Les destinations d’envoi explicites n’accordent aucun accès en lecture aux sessions ni à leur état, et restent soumises aux règles globales de participation aux échanges entre agents et aux restrictions du bac à sable.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent%2Esend":{label:{"v1-1lxwft1-w":`Liste des destinations d’envoi autorisées pour l’agent`},help:{"v1-tfolqu-ar":`Identifiants d’agents ou motifs avec * que cet agent peut contacter via sessions_send, même lorsque tools.sessions.visibility est restreint. Si ce paramètre est omis, la visibilité est héritée ; [] interdit les envois ordinaires entre agents. Les limites globales de tools.agentToAgent et du bac à sable restent applicables. N’accorde aucun accès aux listes, à l’historique, à la recherche, à l’état ni à la surveillance ; les réponses sont limitées au tour envoyé. L’accès aux sessions enfants appartenant au demandeur reste inchangé.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Ajouts à la liste des outils autorisés de l’agent`},help:{"v1-1550ui9-46":`Liste d’outils autorisés supplémentaire par agent, en complément des règles globales et du profil. Limitez-la au strict nécessaire pour éviter toute extension accidentelle des privilèges des agents spécialisés.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Règles d’utilisation des outils de l’agent par fournisseur`},help:{"v1-mthxv9-4t":`Remplacements par agent des règles d’utilisation des outils propres à chaque fournisseur, pour contrôler les capacités au niveau du canal. Utilisez ce paramètre lorsqu’un agent a besoin de restrictions plus strictes pour un fournisseur que pour les autres.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Mode code de l’agent`},help:{"v1-118t8u5-65":`Options du mode code par agent. Une valeur explicite de enabled remplace les paramètres d’activation par défaut du modèle partagé et les paramètres globaux ; une surcharge de codeMode au niveau du modèle propre à l’agent est prioritaire. Les autres options se superposent à tools.codeMode sans modifier l’activation.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Délai d’expiration d’exécution de l’agent (secondes)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Surcharge de l’identité GitHub CLI de l’agent`},help:{"v1-mjwdh4-38":`Surcharge complète de l’identité GitHub CLI gérée et de l’auteur Git pour cet agent. Omettez-la pour hériter de l’identité du système.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EallowInSandbox":{label:{"v1-1rxew98-12":`Autoriser l’identité GitHub de l’agent dans le bac à sable`},help:{"v1-17rsbdj-6g":`Autorise les identifiants GitHub gérés et l’identité d’auteur Git de cet agent dans son propre bac à sable Docker ou Podman (par défaut : false). La portée partagée refuse l’injection d’identité ; les autres backends rejettent le provisionnement. L’audit de sécurité émet un avertissement tant que cette option est activée.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Adresse e-mail de l’auteur Git de l’agent`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Nom de l’auteur Git de l’agent`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Type d’identifiants GitHub de l’agent`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Version du profil GitHub de l’agent`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Liste des actions de messagerie autorisées pour l’agent`},help:{"v1-1g5gov3-67":`Liste des actions de messagerie autorisées par agent pour l’outil message. Définissez une liste minimale telle que ["send"] pour les agents publics en bac à sable afin que les actions de lecture, de modification, de suppression, de réaction et les autres actions de messagerie propres à chaque fournisseur restent masquées et bloquées.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Messagerie intercontextuelle de l’agent (entre fournisseurs)`},help:{"v1-pehesn-49":`Paramètre propre à chaque agent pour l’envoi entre fournisseurs. Hérite du paramètre global (par défaut : true). Définissez-le sur false pour bloquer les messages entre fournisseurs pour cet agent.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Messagerie intercontextuelle de l’agent (même fournisseur)`},help:{"v1-s9u09h-4t":`Restriction propre à chaque agent pour l’envoi de messages vers d’autres conversations sur le même fournisseur. Définissez ce paramètre et allowAcrossProviders sur false pour les agents publics limités à la conversation en cours.`}},"agents%2Eentries%2E*%2Etools%2Eopenclaw":{label:{"v1-1fc612h-p":`Délégation à OpenClaw pour l’agent`},help:{"v1-wjtvl7-25":`Politique d’approbation par agent pour les modifications déléguées à l’agent système OpenClaw.`}},"agents%2Eentries%2E*%2Etools%2Eopenclaw%2EautoApproveChanges":{label:{"v1-lxqapd-10":`Approbation automatique des modifications déléguées pour l’agent`},help:{"v1-1ok03hg-a1":`Remplace tools.openclaw.autoApproveChanges pour cet agent. La valeur true accorde une autorisation permanente d’administration déléguée pouvant permettre l’exécution de code sur l’hôte Gateway ; false exige une approbation individuelle, y compris en mode d’accès complet. Si ce paramètre est omis, le réglage global s’applique, puis les autorisations effectives de l’exécution à l’origine de la demande. Les restrictions relatives au système de fichiers, au bac à sable et aux opérations restent applicables.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Profil d’outils de l’agent`},help:{"v1-1du76ix-57":`Remplacement du profil d’outils par agent lorsqu’un agent a besoin d’un ensemble de capacités de base différent. Utilisez cette option avec parcimonie afin que les différences de politique entre agents restent intentionnelles et vérifiables.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Essaim de l’agent`},help:{"v1-420ljs-2c":`Remplacement des paramètres d’essaim par agent. Les valeurs sont fusionnées avec la configuration tools.swarm de premier niveau et prévalent sur celle-ci.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Mode de saisie de l’agent`},help:{"v1-oxir52-2e":`Remplace la politique par défaut de déclenchement de l’indicateur de saisie pour un agent sans modifier les autres agents.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Modèle utilitaire de l’agent`},help:{"v1-ccb32g-5u":`Modèle utilitaire propre à l’agent, sous forme de chaîne ou de { primary, fallbacks }. Si ce paramètre n’est pas défini, il hérite de agents.defaults.utilityModel. Un primary explicite sans fallbacks supprime les modèles de repli hérités ; une chaîne vide désactive le routage utilitaire.`}},"agents%2Eentries%2E*%2EutilityModel%2Efallbacks":{label:{"v1-17pzdxs-t":`Modèles utilitaires de repli de l’agent`},help:{"v1-v419a0-2k":`Liste ordonnée des modèles utilitaires de repli propres à l’agent. Une liste vide supprime les modèles utilitaires de repli hérités.`}},"agents%2Eentries%2E*%2EutilityModel%2Eprimary":{label:{"v1-lbcmz5-r":`Modèle utilitaire principal de l’agent`},help:{"v1-1d8oent-1z":`Modèle utilitaire principal par agent. Omettez ce paramètre pour hériter du modèle utilitaire principal par défaut.`}},"agents%2Eentries%2E*%2EworkspaceFileMode":{label:{"v1-13trwkt-k":`Mode des nouveaux fichiers de mémoire`},help:{"v1-8mxas6-56":`Remplace agents.defaults.workspaceFileMode pour les nouveaux fichiers de mémoire lisibles par un humain créés par cet agent. Les permissions des fichiers existants sont conservées ; l’hôte qui effectue l’écriture applique son propre umask.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Génération d’attribution des agents`},help:{"v1-1g8mxd3-8u":`Marqueur persistant de génération pour l’attribution des propriétaires en mode multi-agent. "explicit" signifie que les canaux ambiants, les consultations de l’agent système, Talk, cron et les opérations CLI directes doivent déterminer un propriétaire propre à chaque interface ou s’arrêter si aucun propriétaire ne peut être identifié. OpenClaw définit automatiquement ce marqueur lors de la création ou de la migration d’une flotte ; omettez-le pour un agent unique.`}},approvals:{label:{"v1-1m405m7-9":`Approbations`},help:{"v1-4y3in-5w":`Paramètres de routage des approbations permettant de transférer les demandes d’approbation d’exécution et de plugins vers des destinations de discussion en dehors de la session d’origine. Laissez-les désactivés, sauf si les opérateurs ont besoin d’une visibilité explicite sur les approbations hors de la session.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Transfert des approbations d’exécution`},help:{"v1-1r2mozk-5v":`Regroupe les paramètres de transfert des approbations d’exécution, notamment l’activation, le mode de routage, les filtres et les destinations explicites. Configurez ces paramètres lorsque les demandes d’approbation doivent parvenir aux canaux opérationnels plutôt qu’au seul fil d’origine.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Filtre des approbations par agent`},help:{"v1-xip9a-4k":'Liste facultative des identifiants d’agents autorisés à recevoir des approbations transférées, par exemple `["primary", "ops-agent"]`. Utilisez-la pour éviter d’envoyer des notifications aux canaux d’agents non concernés.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Transférer les approbations d’exécution`},help:{"v1-1t0whe8-5s":`Active le transfert des demandes d’approbation d’exécution vers les destinations d’envoi configurées (par défaut : false). Laissez cette option désactivée dans les configurations à faible risque et activez-la uniquement lorsque les personnes chargées des approbations ont besoin de demandes visibles dans les canaux.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Mode de transfert des approbations`},help:{"v1-1dedfo4-69":`Détermine où les demandes d’approbation sont envoyées : "session" utilise la discussion d’origine, "targets" utilise les destinations configurées et "both" utilise les deux. Utilisez "session" comme mode de base et élargissez l’envoi uniquement lorsque le processus opérationnel nécessite une redondance.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Filtre des approbations par session`},help:{"v1-smeg8e-5u":'Filtres facultatifs de clés de session, comparés sous forme de sous-chaînes ou de motifs de type expression régulière, par exemple `["discord:", "^agent:ops:"]`. Utilisez des motifs précis pour que seuls les contextes d’approbation prévus soient transférés vers des destinations partagées.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Cibles de transfert des approbations`},help:{"v1-17ah848-5u":`Cibles de distribution explicites utilisées lorsque le mode de transfert inclut des cibles, chacune précisant le canal et la destination. Limitez les listes de cibles selon le principe du moindre privilège et validez chaque destination avant d’activer un transfert étendu.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`ID du compte cible des approbations`},help:{"v1-16zopng-5e":`Sélecteur de compte facultatif pour les configurations de canaux multicomptes, lorsque les approbations doivent être acheminées via un contexte de compte spécifique. À utiliser uniquement lorsque plusieurs identités sont configurées pour le canal cible.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Canal cible des approbations`},help:{"v1-ji1igl-59":`ID de canal ou de fournisseur utilisé pour la distribution des approbations transférées, comme discord, slack ou un ID de canal de plugin. Utilisez uniquement des ID de canal valides pour éviter que les approbations n’échouent silencieusement en raison de routes inconnues.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`ID du fil cible des approbations`},help:{"v1-1axynw7-59":`Fil ou sujet cible facultatif pour les canaux qui prennent en charge la distribution des approbations transférées dans des fils de discussion. Utilisez cette option pour limiter les échanges liés aux approbations aux fils opérationnels plutôt qu’aux canaux principaux.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Destination cible des approbations`},help:{"v1-1ijng7e-5n":`Identifiant de destination au sein du canal cible (ID de canal, ID utilisateur ou racine du fil selon le fournisseur). Vérifiez la signification de cet identifiant pour chaque fournisseur, car le format de destination varie selon les intégrations de canaux.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Transfert des demandes d’approbation des plugins`},help:{"v1-1m6pzxv-6b":`Regroupe les paramètres de transfert des demandes d’approbation des plugins, notamment l’activation, le mode de routage, les filtres et les cibles explicites. Indépendant du transfert des demandes d’approbation d’exécution. Configurez ces paramètres lorsque les demandes d’approbation des plugins doivent parvenir aux canaux opérationnels.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Filtre d’agents pour les approbations des plugins`},help:{"v1-b3test-4y":'Liste facultative des identifiants d’agents autorisés à recevoir des approbations de plugins transférées, par exemple `["primary", "ops-agent"]`. Utilisez-la pour sélectionner les agents dont les demandes d’approbation sont transférées.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Transférer les demandes d’approbation des plugins`},help:{"v1-1ntctaf-3v":`Active le transfert des demandes d’approbation des plugins vers les destinations de réception configurées (par défaut : false). Indépendant de approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Mode de transfert des demandes d’approbation des plugins`},help:{"v1-1h62vy4-3z":`Détermine où les demandes d’approbation des plugins sont envoyées : "session" utilise la conversation d’origine, "targets" utilise les cibles configurées et "both" utilise les deux.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Filtre de sessions pour les approbations des plugins`},help:{"v1-1eppxmt-57":'Filtres facultatifs sur les clés de session, appliqués par correspondance de sous-chaînes ou de motifs de type expression régulière, par exemple `["discord:", "^agent:ops:"]`. Utilisez des motifs précis pour ne transférer que les demandes d’approbation correspondant aux contextes souhaités.'}},"approvals%2Eplugin%2Eslack":{label:{"v1-o7dlxi-m":`Validateurs des plugins sur Slack`},help:{"v1-1svd0ag-4x":`Politique de validation sur Slack pour les approbations de plugins. Omettez la liste des approbateurs par défaut pour conserver l’autorisation allowFrom/defaultTo du compte ; définissez-la sur [] pour refuser les décisions Slack par défaut.`}},"approvals%2Eplugin%2Eslack%2Eapprovers":{label:{"v1-r39jnl-u":`Validateurs par défaut des plugins sur Slack`},help:{"v1-auy576-5v":`Validateurs par défaut des plugins sur Slack, sous forme d’identifiants utilisateur U/W bruts au sein du compte Slack sélectionné, ou de valeurs team:<team-id>:user:<user-id> qualifiées par espace de travail. Les listes propres aux plugins et aux outils remplacent cette liste pour leurs demandes respectives.`}},"approvals%2Eplugin%2Eslack%2Eplugins":{label:{"v1-13wg4dk-v":`Remplacements des validateurs des plugins sur Slack`},help:{"v1-16kb0vj-2r":`Remplacements des validateurs indexés par l’identifiant du plugin d’outil natif sélectionné. Les clés des outils encodent le nom brut de l’outil.`}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Cibles de transfert des approbations de plugins`},help:{"v1-o92qze-3k":`Cibles de réception explicites utilisées lorsque le mode de transfert des approbations de plugins inclut des cibles, chacune précisant le canal et la destination.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`ID du compte cible des approbations de plugins`},help:{"v1-1wf3lqn-3j":`Sélecteur de compte facultatif pour les configurations de canaux multicomptes, lorsque les approbations de plugins doivent être acheminées via un compte spécifique.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Canal cible des approbations de plugins`},help:{"v1-1mzhzi9-34":`ID du canal ou du fournisseur utilisé pour transmettre les approbations de plugins transférées, par exemple discord, slack ou un ID de canal de plugin.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`ID du fil cible des approbations de plugins`},help:{"v1-1scaw9c-2v":`Fil ou sujet cible facultatif pour les canaux prenant en charge la réception des approbations de plugins transférées dans des fils de discussion.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Destination cible des approbations de plugins`},help:{"v1-sh5te1-31":`Identifiant de destination au sein du canal cible (ID de canal, ID utilisateur ou racine du fil selon le fournisseur).`}},attachments:{label:{"v1-8925gh-b":`Pièces jointes`},help:{"v1-1xvgkss-40":`Comportement global de conservation partagé par les fournisseurs et les outils qui stockent des médias de manière persistante. Utilisez ttlHours lorsque les médias temporairement stockés doivent être supprimés après un délai défini.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`Durée de conservation des pièces jointes (TTL, en heures)`},help:{"v1-r7enyq-98":`Durée de conservation facultative, en heures, des médias enregistrés traités par le nettoyage général basé sur mtime. Laissez ce paramètre non défini pour désactiver ce nettoyage, ou définissez des valeurs telles que 24 (1 jour) ou 168 (7 jours) pour supprimer périodiquement les anciens médias en attente. Les médias sortants gérés (pièces jointes générées dans les conversations) sont exclus et suivent leur propre politique de conservation, qui s’appuie sur SQLite et tient compte des conversations.`}},audio:{label:{"v1-11wczsp-5":`Audio`}},auth:{label:{"v1-5xz433-4":`Authentification`},help:{"v1-1eu3aud-5c":`Racine des profils d’authentification utilisée pour les identifiants des fournisseurs à profils multiples et l’ordre de basculement basé sur les délais d’attente. Gardez les profils minimaux et explicites afin que le comportement du basculement automatique reste vérifiable.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Ordre des profils d’authentification`},help:{"v1-1x6kknp-1w":`Identifiants ordonnés des profils d’authentification par fournisseur (utilisés pour le basculement automatique).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Profils d’authentification`},help:{"v1-kzoqcn-1j":`Profils d’authentification nommés (fournisseur + mode + adresse e-mail facultative).`}},bindings:{label:{"v1-1hcih9f-8":`Liaisons`},help:{"v1-y7hrzb-4i":`Règles de liaison de premier niveau pour le routage et l’attribution persistante des conversations ACP. Utilisez type=route pour le routage normal et type=acp pour les liaisons persistantes à l’environnement d’exécution ACP.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Paramètres de remplacement de la liaison ACP`},help:{"v1-1t4lisi-44":`Paramètres de remplacement ACP facultatifs par liaison pour bindings[].type=acp. Cette couche remplace les valeurs par défaut de agents.entries.*.runtime.acp pour la conversation correspondante.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend de la liaison ACP`},help:{"v1-rsrbkp-2x":`Backend ACP de remplacement pour cette liaison (utilise à défaut le backend ACP de l’environnement d’exécution de l’agent, puis le paramètre global acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Répertoire de travail de la liaison ACP`},help:{"v1-ngpkj0-1y":`Répertoire de travail à utiliser pour les sessions ACP créées à partir de cette liaison.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Libellé de la liaison ACP`},help:{"v1-azce82-23":`Libellé lisible pour l’état et les diagnostics ACP dans cette conversation liée.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Mode de la liaison ACP`},help:{"v1-cgq8xv-1v":`Mode de session ACP à utiliser pour cette liaison (persistent ou oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`ID de l’agent de la liaison`},help:{"v1-17ra0cl-4m":`ID de l’agent cible qui reçoit le trafic lorsque la règle de correspondance de la liaison est satisfaite. Utilisez uniquement des ID d’agents configurés valides afin d’éviter les échecs de routage à l’exécution.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Règle de correspondance de la liaison`},help:{"v1-sc1w2e-51":`Objet de règle de correspondance déterminant quand une liaison s’applique, avec le canal et des contraintes facultatives de compte ou de pair. Définissez des règles précises pour éviter qu’un agent ne prenne accidentellement le relais dans d’autres contextes.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`ID de compte de la liaison`},help:{"v1-1d209g7-56":`Sélecteur de compte facultatif pour les configurations de canaux à plusieurs comptes, afin que la liaison ne s’applique qu’à une seule identité. Utilisez-le lorsque le routage doit être limité à un compte et laissez-le non défini dans les autres cas.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Canal de la liaison`},help:{"v1-d22m5-54":"Identifiant du canal ou du fournisseur auquel cette liaison s’applique, par exemple `telegram`, `discord` ou un ID de canal de plugin. Utilisez exactement la clé du canal configuré pour garantir la fiabilité de l’évaluation de la liaison."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`ID de guilde de la liaison`},help:{"v1-jzzfj1-4x":`Contrainte facultative sur l’identifiant de guilde/serveur de type Discord pour l’évaluation des liaisons dans les déploiements multiserveurs. Utilisez-la lorsque les mêmes identifiants d’interlocuteur peuvent apparaître dans différentes guildes.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Correspondance d’interlocuteur de la liaison`},help:{"v1-gcjxff-4i":`Critère facultatif de correspondance d’interlocuteur pour des conversations spécifiques, comprenant le type et l’identifiant de l’interlocuteur. Utilisez-le lorsqu’une seule cible (conversation directe, groupe ou canal) doit être affectée à un agent.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`Identifiant de l’interlocuteur de la liaison`},help:{"v1-86fbh7-4b":`Identifiant de conversation utilisé pour la correspondance d’interlocuteur, par exemple un identifiant de discussion, de canal ou de groupe provenant du fournisseur. Respectez exactement cet identifiant pour éviter les échecs de correspondance silencieux.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Type d’interlocuteur de la liaison`},help:{"v1-uufscp-4x":`Type de conversation de l’interlocuteur : "direct", "group", "channel" ou l’ancienne valeur "dm" (alias obsolète de direct). Privilégiez "direct" pour les nouvelles configurations et veillez à ce que kind reste cohérent avec la sémantique du canal.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Rôles de la liaison`},help:{"v1-6s891m-4k":`Liste facultative de filtres par rôle utilisée par les fournisseurs qui associent des rôles au contexte de discussion. Utilisez-la pour acheminer le trafic des rôles privilégiés ou opérationnels vers des agents spécialisés.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`Identifiant d’équipe de la liaison`},help:{"v1-hh9ps2-48":`Contrainte facultative sur l’identifiant d’équipe ou d’espace de travail utilisée par les fournisseurs qui rattachent les discussions à des équipes. Ajoutez-la lorsque vous devez limiter les liaisons au contexte d’un seul espace de travail.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Session de la liaison`},help:{"v1-x325l2-4v":`Paramètres de session facultatifs propres à cette route pour les conversations correspondant à cette liaison. Utilisez-les lorsqu’une route ciblée doit conserver le même agent tout en isolant différemment la continuité des sessions.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Portée des sessions de messages privés de la liaison`},help:{"v1-10sg3xw-4s":`Remplacement facultatif de la portée des sessions de messages privés pour cette liaison de route. Par exemple, conservez le paramètre global session.dmScope="main" tout en utilisant "per-account-channel-peer" pour certains interlocuteurs directs.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Portée des sessions de groupe de la liaison`},help:{"v1-1ys2u7k-6n":`Remplacement facultatif de la portée des sessions de groupe ou de canal pour cette liaison de route. "per-group" maintient les salons correspondants séparés et surveillés en arrière-plan par la session principale de l’agent, indépendamment de dmScope ; "main" fusionne leur contexte dans la session principale et ne nécessite aucune surveillance.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Type de liaison`},help:{"v1-172mhtk-3o":`Type de liaison. Utilisez "route" (ou omettez ce paramètre pour les anciennes entrées de route) pour le routage normal, et "acp" pour les liaisons de conversation ACP persistantes.`}},broadcast:{label:{"v1-awqjh0-j":`Fils de discussion des groupes d’agents`},help:{"v1-1tz72sr-6b":`Utilisez les fils de discussion des groupes d’agents pour exécuter plusieurs agents configurés sur une même conversation entrante, chacun dans sa propre session. Les entrées qualifiées par canal permettent un nombre limité de tours de suivi ; les anciens tableaux de correspondants WhatsApp conservent leur fonctionnement en un seul passage.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Participants et options du groupe d’agents`},help:{"v1-1b63zmt-7d":`Utilisez un identifiant de correspondant qualifié par canal (par exemple "telegram:-100123") pour configurer un tableau d’identifiants d’agents ou un objet strict contenant agents, mentionGating, maxRounds et maxTurns. Les entrées qualifiées ont priorité sur les anciennes clés de correspondants WhatsApp et autorisent au maximum 16 agents.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Participants du groupe d’agents`},help:{"v1-g5o0ky-43":`Identifiants des agents participants issus de agents.entries (maximum : 16). Chaque participant utilise sa propre session pour ce canal, ce compte, cette conversation et ce fil de discussion.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Nombre maximal de cycles du groupe d’agents`},help:{"v1-i6v4jc-5a":`Nombre maximal de cycles par message entrant, cycle initial compris (entier : 1–4, valeur par défaut : 1). Les cycles suivants partagent les réponses des autres participants, en quantité limitée et avec indication de leur auteur, et s’arrêtent lorsque tous les participants passent leur tour.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Nombre maximal de tours du groupe d’agents`},help:{"v1-1kiv8dy-72":`Nombre maximal de tours des participants par message entrant, tous cycles confondus (entier : 1–32, valeur par défaut : agents.length). Les créneaux sont réservés avant le lancement en parallèle ; cette limite porte sur les tours des agents, et non sur les fragments de messages effectivement envoyés ou les envois d’outils. Les budgets ne sont pas repris après un redémarrage.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Sélection par mention dans le groupe d’agents`},help:{"v1-uay9zu-5u":`Sélectionner uniquement les participants explicitement mentionnés avec @ lorsqu’une correspondance est trouvée ; sinon, exécuter tous les participants (valeur par défaut : true). Les noms seuls ou les émojis ne sélectionnent pas de participants. Les listes d’autorisation des canaux et les règles d’admission restent applicables.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Stratégie du groupe d’agents`},help:{"v1-p4k9hu-4q":`Ordre d’exécution des participants : "parallel" (par défaut) exécute les agents simultanément, tandis que "sequential" les exécute dans l’ordre configuré. Chaque cycle se termine avant le début du suivant.`}},browser:{label:{"v1-13dzmen-7":`Navigateur`},help:{"v1-5b74wi-5l":`Paramètres d’exécution du navigateur pour la connexion CDP locale ou distante, le routage des profils et le comportement des captures d’écran et des instantanés. Conservez les valeurs par défaut, sauf si votre flux d’automatisation nécessite des paramètres de transport personnalisés pour le navigateur.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Autoriser l’importation du profil système`},help:{"v1-1lsvlxw-5w":`Permet aux hôtes macOS d’importer les cookies d’un profil système local d’un navigateur de la famille Chrome dans un profil de navigateur géré par OpenClaw. Désactivez cette option pour empêcher l’importation des cookies du profil de navigateur et l’affichage de la demande de consentement du trousseau macOS associée.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Mode de connexion uniquement du navigateur`},help:{"v1-xaw7xm-4s":`Limite le navigateur à la connexion à une instance existante, sans démarrer de processus de navigateur locaux. Utilisez cette option lorsque toutes les sessions du navigateur sont gérées en externe par un fournisseur CDP distant.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`URL CDP du navigateur`},help:{"v1-2n72jb-65":`URL du point de terminaison CDP/DevTools utilisée pour se connecter à une instance de navigateur gérée en externe. Utilisez cette option pour les hôtes de navigateur centralisés, les tunnels ou la connexion à une session existante, et limitez l’accès à l’URL aux chemins réseau de confiance.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Profil par défaut du navigateur`},help:{"v1-a6xo96-52":`Nom du profil de navigateur sélectionné par défaut lorsque les appelants ne choisissent pas explicitement de profil. Utilisez par défaut un profil stable doté de privilèges limités pour réduire le risque d’utilisation accidentelle d’un état provenant d’un autre contexte.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Navigateur activé`},help:{"v1-1m3zcs-5g":`Active l’intégration des fonctionnalités de navigation dans le Gateway afin de permettre l’exécution des outils de navigateur et des flux de travail pilotés par CDP. Désactivez ce paramètre lorsque l’automatisation du navigateur n’est pas nécessaire pour réduire les fonctionnalités disponibles et les tâches au démarrage.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Évaluation dans le navigateur activée`},help:{"v1-1oa79mq-59":`Active les fonctions auxiliaires d’évaluation côté navigateur pour permettre l’évaluation de scripts à l’exécution, lorsque cette fonctionnalité est prise en charge. Laissez cette option désactivée, sauf si vos workflows nécessitent des fonctions d’évaluation allant au-delà des instantanés et de la navigation.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Chemin de l’exécutable du navigateur`},help:{"v1-1dshhkn-6g":`Chemin explicite de l’exécutable du navigateur lorsque la détection automatique ne suffit pas dans votre environnement hôte. Utilisez un chemin absolu stable, ou un chemin commençant par ~ pour le répertoire personnel de votre système d’exploitation, afin que le comportement au lancement reste prévisible après chaque redémarrage.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Relais de l’extension de navigateur`},help:{"v1-6ywlwr-4e":`Paramètres de compatibilité de l’authentification du relais de l’extension Chrome. Ne maintenez la période de compatibilité avec l’ancienne authentification que tant que des extensions appairées anciennes ou des clients CDP externes en ont encore besoin.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Autoriser l’ancienne authentification du relais de navigateur`},help:{"v1-pj2e90-63":`Accepte temporairement l’ancienne authentification du relais via Bearer, Basic et le sous-protocole de jeton. Valeur par défaut : true pendant une période de migration. Définissez cette option sur false une fois que toutes les extensions et tous les clients CDP externes utilisent l’authentification du relais de navigateur v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Mode sans interface du navigateur`},help:{"v1-hlkywz-56":`Les navigateurs locaux gérés s’exécutent par défaut sans interface graphique. Définissez ce paramètre sur false pour afficher une fenêtre de navigateur. Les navigateurs utilisant une session existante, une extension, une connexion distante ou uniquement le rattachement à une instance existante conservent leur mode sélectionné en externe.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Mode sans bac à sable du navigateur`},help:{"v1-slntux-4w":`Désactive les options d’isolation par bac à sable de Chromium pour les environnements où cette isolation échoue à l’exécution. Laissez cette option désactivée autant que possible, car elle réduit les protections d’isolation des processus.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Profils de navigateur`},help:{"v1-1x8lf05-51":`Table de connexions des profils de navigateur nommés, utilisée pour le routage explicite vers des ports ou des URL CDP, avec des métadonnées facultatives. Veillez à la cohérence des noms de profils et évitez les définitions de points de terminaison qui se chevauchent.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Mode de connexion seule du profil de navigateur`},help:{"v1-2b5zs0-5a":`Paramètre propre au profil qui impose la connexion seule : il ignore le lancement d’un navigateur local et se connecte uniquement à un point de terminaison CDP existant. Utile lorsqu’un profil est géré de manière externe tandis que les autres sont lancés localement.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Port CDP du profil de navigateur`},help:{"v1-gx1yiq-49":`Port CDP local propre au profil, utilisé pour se connecter aux instances de navigateur par port plutôt que par URL. Utilisez un port distinct pour chaque profil afin d’éviter les conflits de connexion.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`URL CDP du profil de navigateur`},help:{"v1-x491r0-64":`URL du point de terminaison CDP/DevTools propre au profil, utilisée pour le routage explicite du navigateur par nom de profil. Utilisez-la pour les hôtes CDP distants, les tunnels ou les profils de sessions existantes qui doivent se connecter via un point de terminaison Chrome DevTools en cours d’exécution.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Pilote du profil de navigateur`},help:{"v1-17byyx6-5r":`Mode du pilote de navigateur par profil. Utilisez "openclaw" (ou l’ancien "clawd") pour les profils basés sur CDP, "existing-session" pour la connexion via Chrome DevTools MCP, ou "extension" pour le relais authentifié de l’extension Chrome.`}},"browser%2Eprofiles%2E*%2Eengine":{label:{"v1-w0e8eg-m":`Moteur du profil de navigateur`},help:{"v1-1n0drki-ab":`Préréglage des fonctionnalités du moteur de navigateur : "chromium" (par défaut) ou les moteurs expérimentaux "lightpanda" / "kitesurf" pour la navigation CDP externe. Les moteurs externes nécessitent un cdpUrl ws/wss explicite dédié à un seul profil et attachOnly: true, ne lancent jamais de navigateur local et n’exposent que les opérations qu’ils prennent en charge. Lightpanda ne permet pas de faire des captures d’écran ; Kitesurf propose des captures d’écran expérimentales.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Chemin de l’exécutable du profil de navigateur`},help:{"v1-29azyv-4w":`Chemin de l’exécutable du navigateur par profil pour les profils de navigateur gérés lancés localement. Remplace browser.executablePath et accepte les chemins commençant par ~ pour le répertoire personnel du système d’exploitation.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Mode sans interface graphique du profil de navigateur`},help:{"v1-p4jtgv-4u":`Réglage du mode sans interface graphique par profil pour les instances de navigateur lancées localement. Utilisez-le lorsqu’un profil doit rester sans interface graphique sans imposer browser.headless à tous les autres profils.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Arguments Chrome MCP du profil de navigateur`},help:{"v1-rc45ke-5g":`Arguments Chrome DevTools MCP supplémentaires par profil pour la connexion en mode existing-session, tels que --no-usage-statistics. Les arguments de point de terminaison définis ici remplacent la connexion automatique intégrée ou la sélection de l’URL du navigateur.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Commande Chrome MCP du profil de navigateur`},help:{"v1-1xpty8o-2h":`Commande Chrome DevTools MCP par profil pour la connexion en mode existing-session. La valeur par défaut est npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Répertoire des données utilisateur du profil de navigateur`},help:{"v1-5xvgex-9h":`Répertoire de données utilisateur Chromium propre à chaque profil, permettant de se rattacher à une session existante via Chrome DevTools MCP. Utilisez-le pour Brave, Edge, Chromium ou les profils Chrome autres que celui par défaut lorsque le mécanisme de connexion automatique intégré sélectionnerait le mauvais répertoire de données du navigateur sur l’hôte ou le nœud de navigateur sélectionné. Les chemins commençant par ~ sont résolus vers le répertoire personnel du système d’exploitation.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Paramètres par défaut des instantanés du navigateur`},help:{"v1-v19wdy-4y":`Configuration de capture d’instantanés par défaut utilisée lorsque les appelants ne fournissent pas d’options explicites. Ajustez-la pour obtenir un comportement de capture cohérent entre les canaux et les processus d’automatisation.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Mode d’instantané du navigateur`},help:{"v1-joeyxp-5c":`Mode d’extraction des instantanés par défaut qui détermine la transformation du contenu des pages pour son utilisation par l’agent. Choisissez le mode offrant le meilleur équilibre entre lisibilité, fidélité et consommation de tokens pour vos flux de travail.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Politique SSRF du navigateur`},help:{"v1-1qbp9im-5e":`Paramètres de protection contre la falsification de requêtes côté serveur pour les accès via le navigateur ou le réseau susceptibles d’atteindre des hôtes internes. Conservez les paramètres restrictifs par défaut en production et n’autorisez que les cibles explicitement approuvées.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Noms d’hôtes autorisés pour le navigateur`},help:{"v1-1rng39-2k":`Noms d’hôtes exacts ou adresses IP littérales autorisés par les vérifications de la politique SSRF du navigateur. Limitez cette liste au strict nécessaire.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Autoriser la plage d’adresses locales uniques IPv6 pour le navigateur`},help:{"v1-1glx5cy-2c":`Autoriser les adresses locales uniques IPv6 (fc00::/7) dans les environnements de proxy de confiance utilisant des adresses IP fictives.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Autoriser la plage de test RFC 2544 dans le navigateur`},help:{"v1-10ateu3-2i":`Autoriser les adresses IP de la plage de test RFC 2544 (198.18.0.0/15) pour les environnements proxy de confiance utilisant des IP fictives.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Noms d’hôte bloqués dans le navigateur`},help:{"v1-nug0we-6k":`Modèles de noms d’hôte bloqués avant la résolution DNS et l’application des règles d’autorisation, même lorsque l’accès au réseau privé est activé. Accepte les noms d’hôte exacts et "*.example.com" pour les sous-domaines uniquement ; ajoutez "example.com" séparément pour bloquer le domaine racine. Une valeur vide ou non définie n’ajoute aucun blocage.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Autoriser l’accès au réseau privé dans le navigateur (dangereux)`},help:{"v1-17103pi-4m":`Autorise l’accès aux plages d’adresses des réseaux privés depuis les outils du navigateur. Désactivé par défaut si non défini ; à activer uniquement pour des destinations de réseau privé explicitement approuvées.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Nettoyage des onglets du navigateur`},help:{"v1-1ctwaad-4y":`Politique de nettoyage sans garantie de résultat pour les onglets du navigateur ouverts par les sessions de l’agent principal. Laissez cette option activée pour éviter l’accumulation d’onglets obsolètes du bac à sable ou du navigateur géré sur les instances Gateway fonctionnant sur de longues périodes.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Nettoyage des onglets du navigateur activé`},help:{"v1-4sv97p-3u":`Active le nettoyage des onglets du navigateur suivis et inactifs pour les sessions de l’agent principal. À désactiver uniquement lorsque des outils externes gèrent entièrement le cycle de vie des onglets.`}},channels:{label:{"v1-1ju93md-8":`Canaux`},help:{"v1-18k1gv4-50":`Configurations des fournisseurs de canaux et valeurs par défaut communes qui régissent les politiques d’accès et le comportement de chaque interface. Centralisez les valeurs par défaut et ne les remplacez pour un fournisseur que si nécessaire.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Paramètres par défaut des canaux`},help:{"v1-uz6veb-4p":`Comportement par défaut des canaux appliqué à tous les fournisseurs lorsqu’aucun paramètre propre au fournisseur n’est défini. Utilisez ces paramètres pour appliquer une politique de base cohérente avant les ajustements par fournisseur.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Protection par défaut contre les boucles entre bots`},help:{"v1-1lpznyk-4w":`Paramètres par défaut de protection contre les boucles par paire pour les fournisseurs de canaux prenant en charge les protections contre les boucles entre bots. Ne définissez des paramètres propres à un fournisseur que lorsqu’un canal nécessite un quota différent.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Délai de suspension par défaut des boucles entre bots en secondes`},help:{"v1-1yl5ird-2z":`Délai de suspension en secondes appliqué à une paire après le dépassement du quota de boucle. La valeur par défaut pour les canaux compatibles est de 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Protection contre les boucles entre bots activée par défaut`},help:{"v1-3ruik-4r":`Active par défaut la protection contre les boucles par paire pour les canaux compatibles lorsque les messages rédigés par des bots peuvent être acheminés. Les fournisseurs peuvent toutefois désactiver la protection lorsque les bots sont ignorés.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Nombre d’événements de boucle entre bots par fenêtre par défaut`},help:{"v1-1u0mdjc-41":`Nombre maximal d’événements qu’une paire émetteur/destinataire peut échanger dans la fenêtre configurée avant le début du blocage. La valeur par défaut pour les canaux compatibles est de 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Durée par défaut de la fenêtre de boucle entre bots en secondes`},help:{"v1-12xpmen-2m":`Durée de la fenêtre glissante en secondes pour les quotas de boucles par paire. La valeur par défaut pour les canaux compatibles est de 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Visibilité du contexte par défaut`},help:{"v1-1hze3g1-5o":`Visibilité par défaut du contexte supplémentaire pour les contenus récupérés dans les citations, fils de discussion et historiques : "all" (conserver tout le contexte), "allowlist" (uniquement les expéditeurs de la liste d’autorisation) ou "allowlist_quote" (liste d’autorisation + conservation des citations explicites).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Politique de groupe par défaut`},help:{"v1-ntl9m4-4n":`Politique de groupe par défaut pour tous les canaux : "open", "disabled" ou "allowlist". Conservez "allowlist" pour des configurations de production plus sûres, sauf si une participation étendue aux groupes est souhaitée.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Mentions implicites par défaut`},help:{"v1-4gtdyv-48":`Règle par défaut déterminant si les réponses au bot, les citations du bot et les messages dans les fils auxquels le bot a participé activent les canaux de messagerie compatibles sans mention explicite.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Mentions implicites par défaut lors de citations du bot`},help:{"v1-va1u5v-2v":`Traite par défaut les citations de messages du bot comme des mentions implicites. La valeur par défaut est true pour assurer la rétrocompatibilité.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Mentions implicites par défaut lors de réponses au bot`},help:{"v1-lm44c3-39":`Traite par défaut les réponses aux propres messages du bot comme des mentions implicites. La valeur par défaut est true pour assurer la rétrocompatibilité.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Mentions implicites par défaut dans les fils où le bot a participé`},help:{"v1-160205h-3o":`Traite par défaut les messages suivants dans les fils auxquels le bot a participé comme des mentions implicites. La valeur par défaut est true pour assurer la rétrocompatibilité.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Remplacements de modèle par canal`},help:{"v1-1b01spx-2p":`Correspondance fournisseur -> identifiant de canal / identifiant d’interlocuteur en message privé -> remplacement de modèle (les valeurs sont au format provider/model ou sont des alias).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Workers cloud`},help:{"v1-10carc4-5v":`Profils de workers cloud à activer explicitement pour des environnements distants jetables. Si cette section est omise ou ne contient aucun profil, la création de workers cloud reste indisponible et le comportement existant du statut de la Gateway et des nœuds reste inchangé.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Bureau des workers cloud (Labs)`},help:{"v1-sly85c-3k":`Active l’interface expérimentale worker.desktop.observe et le panneau Bureau de l’application web pour les environnements de workers cloud prenant en charge les fonctionnalités de bureau.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Réserve de workers cloud préparés`},help:{"v1-rw51o5-6b":`Limites applicables aux workers cloud préparés et maintenus prêts pour les sessions ultérieures. Les réserves entraînent des frais de fonctionnement des machines jusqu’à la fin du nettoyage par le fournisseur ; leur échéance fixe dépend de la demande réelle du projet et de la politique d’inactivité existante du fournisseur.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Plafond de la réserve de workers cloud prêts`},help:{"v1-1mpd1dt-7u":`Plafond global de Gateway pour les workers cloud préparés et non affectés, tous projets et profils confondus (par défaut : 4). Les workers en cours de préparation et les réserves dont le nettoyage n’est pas confirmé sont comptabilisés dans ce plafond. Définissez la valeur sur 0 pour vider les réserves non affectées et désactiver leur réapprovisionnement, tout en préservant la réutilisation des instantanés et les sessions actives.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Profils de workers cloud`},help:{"v1-eii67l-3j":`Profils nommés de workers cloud. Chaque profil sélectionne un fournisseur de workers enregistré par un plugin et contient les paramètres propres à ce fournisseur.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Profil de worker cloud`},help:{"v1-1v2w7jl-4u":`Profil de worker cloud sélectionné par son nom lors de la création d’un environnement. Conservez les identifiants du fournisseur dans des références prises en charge plutôt que d’intégrer des secrets dans ce bloc.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Méthode d’installation du worker cloud`},help:{"v1-blrtbf-74":`Méthode d’installation du worker : "bundle" (par défaut) transfère la version installée de la Gateway, identifiée par le hachage de son contenu, et prend en charge les versions publiées, de développement et non publiées ; "npm" installe la version exacte de la Gateway et n’est disponible que si cette version est publiée.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Fournisseur de workers cloud`},help:{"v1-1p4s4c1-44":`Identifiant du fournisseur de workers enregistré par un plugin. Le plugin configuré doit exposer cet identifiant avant que le Gateway puisse provisionner des environnements à partir du profil.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Objectif de la réserve de workers cloud prêts`},help:{"v1-1nwve9s-7w":`Nombre cible de workers préparés et non affectés par projet éligible utilisant ce profil (par défaut : 1), dans la limite du plafond global du pool de workers préparés de Gateway. Définissez la valeur sur 0 pour désactiver les réserves de ce profil tout en préservant la réutilisation des instantanés. Les workers en cours de préparation et les réserves dont le nettoyage n’est pas confirmé sont comptabilisés dans cet objectif.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Paramètres du fournisseur de workers cloud`},help:{"v1-mq7u32-4j":`Paramètres propres au fournisseur, validés par le plugin sélectionné. Utilisez des objets SecretRef pour les valeurs contenant des secrets ; les paramètres opaques ne bénéficient pas de la résolution automatique des secrets.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Délai de suspension des workers cloud inactifs`},help:{"v1-1keuwgh-4w":`Libère automatiquement les ressources d’un worker cloud inactif après ce délai, par exemple 45m ou 2h ; le message suivant provisionne un worker de remplacement. Minimum : 1m. Laissez ce paramètre non défini pour maintenir les workers en fonctionnement.`}},"cloudWorkers%2Eprofiles%2E*%2EworkspaceDurability":{label:{"v1-1yi22sz-v":`Durabilité de l’espace de travail du dépôt`},help:{"v1-1r6ow8r-6o":`Mis en miroir par défaut. Les dépôts sur disque conservé nécessitent un fournisseur de nœuds gérés avec des ressources exactes et une fenêtre de calcul finie explicitement définie en secondes. Le disque d’origine reste la référence entre les tours ; Déplacer vers Gateway l’exporte et le met hors service.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Profils de workers cloud par projet`},help:{"v1-1kkfrif-46":`Noms des profils de workers cloud par défaut, indexés par l’identité du dépôt normalisée en minuscules (host/owner/repo). Les identifiants de profil explicitement indiqués lors de la répartition sont prioritaires.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Profil de worker cloud du projet`},help:{"v1-1mux5u0-30":`Nom du profil de worker cloud utilisé par défaut lorsque l’origine du worktree d’une session correspond à cette identité de dépôt.`}},"cloudWorkers%2ErequiredProfile":{label:{"v1-1rqoa9j-n":`Profil de worker requis`},help:{"v1-1q30qf7-57":`Exiger que chaque session s’exécute avec ce profil de worker. Les sessions sont affectées automatiquement et ne peuvent pas se rabattre sur une exécution sur Gateway. L’indisponibilité des workers bloque les tours, mais pas le démarrage de Gateway.`}},commands:{label:{"v1-15x4mpf-8":`Commandes`},help:{"v1-1gi0dr2-5a":`Contrôle les interfaces de commandes du chat, les restrictions d’accès au propriétaire et le comportement des accès privilégiés aux commandes pour tous les fournisseurs. Conservez les valeurs par défaut, sauf si vous avez besoin de contrôles plus stricts pour les opérateurs ou d’une disponibilité plus large des commandes.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Règles d’accès privilégié aux commandes`},help:{"v1-7azkw-5g":`Définit les règles d’autorisation des commandes à privilèges élevés par canal et par expéditeur pour les interfaces de commande réservées au propriétaire. Utilisez des identités spécifiques à chaque fournisseur et strictement ciblées afin de ne pas exposer les commandes privilégiées à un large public dans les discussions.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Autoriser la commande Bash dans les discussions`},help:{"v1-83ah7w-36":"Autorise la commande bash dans les discussions (`!` ; alias `/bash`) à exécuter des commandes shell sur l’hôte (par défaut : false ; nécessite tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Durée de maintien de Bash au premier plan (ms)`},help:{"v1-1o0o4dw-2c":`Durée d’attente de bash avant le passage en arrière-plan (par défaut : 2000 ; 0 entraîne un passage immédiat en arrière-plan).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Autoriser /config`},help:{"v1-151bb7c-21":`Autorise la commande /config dans les discussions à lire et à écrire la configuration sur disque (par défaut : false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Autoriser /debug`},help:{"v1-y1lc3j-1y":`Autorise la commande /debug dans les discussions pour des remplacements de paramètres limités à l’exécution en cours (par défaut : false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Autoriser /mcp`},help:{"v1-1rtwcgd-2o":`Autorise la commande /mcp dans les discussions à gérer la configuration des serveurs MCP d’OpenClaw sous mcp.servers (par défaut : false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Commandes natives`},help:{"v1-dighr2-5n":`Enregistre les commandes natives avec barre oblique ou accessibles par menu auprès des canaux prenant en charge l’enregistrement des commandes (Discord, Slack, Telegram). Laissez cette option activée pour faciliter leur découverte, sauf si vous utilisez volontairement des flux de travail avec des commandes uniquement textuelles.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Commandes natives de compétences`},help:{"v1-19gtqci-5h":`Enregistre les commandes natives de compétences afin que les utilisateurs puissent invoquer les compétences directement depuis les menus de commandes des fournisseurs qui le permettent. Veillez à la cohérence avec votre politique de compétences afin que les commandes proposées correspondent aux attentes des opérateurs.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Propriétaires des commandes`},help:{"v1-1di38gv-3y":`Liste explicite des propriétaires autorisés pour les commandes réservées aux propriétaires. Utilisez les identifiants natifs du canal (éventuellement préfixés, comme "whatsapp:+15551234567"). '*' est ignoré.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Autoriser /plugins`},help:{"v1-akwy9y-33":`Autoriser la commande de chat /plugins à lister les plugins détectés et à activer ou désactiver les plugins dans la configuration (par défaut : false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Autoriser le redémarrage`},help:{"v1-m32fv2-27":`Autoriser /restart, /update et les demandes externes de redémarrage via SIGUSR2 (par défaut : true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Commandes textuelles`},help:{"v1-1utu76s-5j":`Active l’analyse des commandes textuelles dans les messages de chat, en complément des interfaces de commandes natives lorsqu’elles sont disponibles. Gardez cette option activée pour assurer la compatibilité avec les canaux qui ne prennent pas en charge l’enregistrement de commandes natives.`}},cron:{label:{"v1-1qlte4b-b":`Automatisations`},help:{"v1-4md8ic-5u":`Paramètres globaux du planificateur pour les automatisations enregistrées, les exécutions simultanées, les solutions de repli pour la transmission et la conservation des sessions d’exécution. Conservez les valeurs par défaut, sauf si vous augmentez le volume d’automatisations ou intégrez des récepteurs de webhooks externes.`}},"cron%2Eagents":{label:{"v1-13sapf2-u":`Paramètres par défaut des automatisations par agent`},help:{"v1-15ynqdo-4x":`Paramètres par défaut des automatisations par agent, indexés par identifiant d’agent. Chaque automatisation utilise l’entrée de son agent effectif (son agentId, sinon l’agent de sa clé de session, sinon l’agent par défaut).`}},"cron%2Eagents%2E*%2Edelivery":{label:{"v1-106qeoh-y":`Destination par défaut des automatisations de l’agent`},help:{"v1-fgez3q-5r":"Destination par défaut des annonces pour les automatisations de cet agent qui ne précisent aucun routage. Remplace intégralement `cron.delivery` pour cet agent ; les champs ne sont pas fusionnés. Les paramètres par défaut du créateur humain de la tâche sont prioritaires."}},"cron%2Eagents%2E*%2EfailureAlert":{label:{"v1-15hpccn-11":`Routage des alertes d’échec des automatisations de l’agent`},help:{"v1-ppqxgd-6j":"Routage par défaut des alertes d’échec (`mode`, `channel`, `to`, `threadId`, `accountId`) pour les automatisations de cet agent. Remplace intégralement les champs de routage de `cron.failureAlert` ; `enabled`, `after`, `cooldownMs` et `includeSkipped` restent définis à l’échelle de Gateway."}},"cron%2Ecreators":{label:{"v1-8luomx-w":`Paramètres par défaut des automatisations par créateur`},help:{"v1-12liwzq-9q":`Paramètres par défaut des automatisations par créateur, indexés par l’identifiant de profil Gateway de la personne ayant créé l’automatisation. S’applique uniquement lorsque l’automatisation enregistre un profil humain comme créateur (directement, ou comme profil ayant délégué la création à un agent) ; les automatisations anciennes et celles dont le créateur est identifié uniquement par un canal, est inconnu, est un agent ou est le système n’utilisent aucune entrée de créateur. Les clés doivent correspondre exactement.`}},"cron%2Ecreators%2E*%2Edelivery":{label:{"v1-85aipy-10":`Destination par défaut des automatisations du créateur`},help:{"v1-ybgvfk-4j":"Destination par défaut des annonces pour les automatisations de cette personne qui ne précisent aucun routage. Est prioritaire sur `cron.agents.<agentId>.delivery` et `cron.delivery` et les remplace intégralement."}},"cron%2Ecreators%2E*%2EfailureAlert":{label:{"v1-1e8apq2-13":`Routage des alertes d’échec des automatisations du créateur`},help:{"v1-mlj76p-7m":"Routage par défaut des alertes d’échec (`mode`, `channel`, `to`, `threadId`, `accountId`) pour les automatisations de cette personne. Il prévaut sur celui de l’agent propriétaire et remplace intégralement les champs de routage de `cron.failureAlert` ; `enabled`, `after`, `cooldownMs` et `includeSkipped` restent définis à l’échelle de Gateway."}},"cron%2EdefaultTools":{label:{"v1-huhclk-o":`Outils par défaut des automatisations`},help:{"v1-1x80rr1-7x":`Outils ajoutés lorsque l’outil d’automatisation crée ou modifie explicitement une liste toolsAllow non vide, avant les vérifications de la politique du créateur et l’approbation. Si ce paramètre n’est pas défini, aucun outil n’est ajouté. Utilisez toolsAllowMode: "exact" dans cette requête pour désactiver cet ajout ; [] reste sans outils. Les tâches existantes et les modifications sans rapport ne sont pas affectées.`}},"cron%2Edelivery":{label:{"v1-11v82ye-s":`Diffusion par défaut des automatisations`},help:{"v1-1rndf98-aj":"Destination d’annonce par défaut à l’échelle de Gateway pour les automatisations sans routage propre (aucun canal autre que `last`, ni `to`, `threadId`, `accountId` ou ciblage du propriétaire). Elle remplace le routage de session mémorisé au moment de l’exécution et ne s’applique jamais aux modes de diffusion `none` ou `webhook`. Une valeur par défaut définie dans `cron.creators.<profileId>.delivery` ou `cron.agents.<agentId>.delivery` prévaut sur celle-ci."}},"cron%2Edelivery%2EaccountId":{label:{"v1-192kjm5-10":`Compte de diffusion par défaut des automatisations`},help:{"v1-1ishqby-2j":`Compte de canal facultatif pour la destination par défaut lorsque le canal possède plusieurs comptes.`}},"cron%2Edelivery%2Echannel":{label:{"v1-b4tjph-10":`Canal de diffusion par défaut des automatisations`},help:{"v1-x3hpfs-39":"Canal de la destination par défaut, par exemple `telegram`. Omettez-le pour utiliser la résolution `last` avec le destinataire par défaut."}},"cron%2Edelivery%2EthreadId":{label:{"v1-16jecza-z":`Fil de discussion de diffusion par défaut des automatisations`},help:{"v1-12h3hbw-2g":`Fil de discussion ou sujet de forum facultatif pour la destination par défaut, par exemple un identifiant de sujet Telegram.`}},"cron%2Edelivery%2Eto":{label:{"v1-1iipxgp-12":`Destinataire de diffusion par défaut des automatisations`},help:{"v1-1odj9jz-3j":"Destinataire de la destination par défaut, selon la syntaxe de ciblage du canal (par exemple, un identifiant de discussion Telegram tel que `-100123456789`)."}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automatisations activées`},help:{"v1-y8otx6-5i":`Active l’exécution des automatisations selon les planifications enregistrées gérées par la passerelle. Gardez cette option activée pour le fonctionnement normal des rappels et des automatisations, et désactivez-la uniquement pour suspendre toutes les automatisations sans supprimer les tâches.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Conservation des sessions d’automatisation`},help:{"v1-4wagu6-7e":"Définit la durée de conservation des sessions d’exécution d’automatisation terminées avant leur purge (`24h`, `7d`, `1h30m`, ou `false` pour désactiver la purge ; une durée nulle telle que `0h` la désactive également ; valeur par défaut : `24h`). Utilisez une durée de conservation plus courte pour limiter la croissance du stockage lorsque les exécutions sont fréquentes."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Ignorer les automatisations récurrentes manquées`},help:{"v1-w9wfmo-66":`Ignore les créneaux récurrents cron/every manqués au démarrage de Gateway et planifie leur prochaine occurrence au lieu de les rattraper. Valeur par défaut : false. Activez cette option pour éviter les rappels obsolètes après une interruption ; les tâches ponctuelles at restent rattrapées.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Politique SSRF des webhooks d’automatisation`},help:{"v1-1xlfqnu-5h":`Politique SSRF appliquée à chaque webhook d’automatisation sortant. Les destinations privées, de bouclage, de liaison locale et internes restent bloquées, sauf si cette politique les autorise explicitement. Laissez ce paramètre non défini pour conserver des restrictions d’envoi strictes.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Noms d’hôte autorisés pour les webhooks d’automatisation`},help:{"v1-1i94hyz-3n":`Noms d’hôte exacts ou adresses IP littérales autorisés pour l’envoi des webhooks d’automatisation, y compris les destinations normalement bloquées. Limitez cette liste au strict nécessaire.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Autoriser la plage locale unique IPv6 pour les webhooks d’automatisation`},help:{"v1-rke0oj-3b":`Autorise les webhooks d’automatisation vers les adresses locales uniques IPv6 (fc00::/7). À utiliser uniquement dans des environnements de proxy de confiance utilisant des adresses IP fictives.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Autoriser la plage de test de performances RFC 2544 pour les webhooks d’automatisation`},help:{"v1-x1usg4-3h":`Autorise les webhooks d’automatisation vers les adresses IP de la plage de test RFC 2544 (198.18.0.0/15). À utiliser uniquement dans des environnements de proxy à IP fictives de confiance.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Noms d’hôte bloqués pour les webhooks d’automatisation`},help:{"v1-16cv1ic-6a":`Modèles de noms d’hôte refusés avant la résolution DNS et l’application des règles d’autorisation pour l’envoi des webhooks d’automatisation. Prend en charge les noms d’hôte exacts et "*.example.com" pour les sous-domaines uniquement ; ajoutez "example.com" séparément pour bloquer le domaine racine. Si ce paramètre est vide ou non défini, aucun refus n’est ajouté.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Autorisation dangereuse du réseau privé pour les webhooks d’automatisation`},help:{"v1-1n9710c-3t":`Autorise les webhooks d’automatisation vers des destinations sur des réseaux privés et internes. Laissez ce paramètre désactivé, sauf si toutes les destinations de webhook configurées sont de confiance.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Jeton Bearer des webhooks d’automatisation`},help:{"v1-1l90hxg-5l":`Jeton Bearer joint aux envois POST des webhooks d’automatisation lorsque le mode webhook est utilisé. Privilégiez la substitution par un secret ou une variable d’environnement et renouvelez régulièrement ce jeton si les points de terminaison de webhook partagés sont accessibles depuis Internet.`}},database:{label:{"v1-1ur2pjs-8":`Base de données`},help:{"v1-zxclpq-90":`Sélection du moteur de base de données. SQLite est le moteur par défaut ; PostgreSQL est une alternative prise en charge pour les cinq familles configurables. Doctor indique les moteurs configurés et observés et signale les incohérences, les fonctionnalités manquantes ou les espaces de stockage indisponibles. Consultez le guide d’exploitation PostgreSQL pour connaître les limites de qualification des plateformes et des mises à niveau.`}},"database%2Eengine":{label:{"v1-we5l2i-f":`Moteur de base de données`},help:{"v1-6hsgz2-6j":`Moteur de stockage par défaut (par défaut : sqlite). PostgreSQL prend en charge state, agent, workboard, logbook et team-reports, sauf si database.families définit d’autres moteurs ; les espaces de stockage de sécurité restent en local sous SQLite. Le changement de moteur ne migre pas les données existantes.`}},"database%2Efamilies":{label:{"v1-1xrm7s9-n":`Moteurs de base de données par famille`},help:{"v1-12i1jst-75":`Remplacements facultatifs du moteur pour state, agent, workboard, logbook et team-reports. Chaque remplacement nécessite engine. Les familles state et agent peuvent utiliser des moteurs différents ; les journaux de sécurité locaux ne sont pas configurables. Toutes les familles PostgreSQL partagent database.postgres.`}},"database%2Efamilies%2Eagent%2Eengine":{label:{"v1-1e7sns0-m":`Moteur de base de données de la famille`},help:{"v1-fv44v3-77":`Remplace database.engine pour cette famille. Changer de moteur nécessite database port --family et un redémarrage ; modifier la configuration ne migre pas les données existantes. La sauvegarde et la restauration avec plusieurs moteurs préservent le moteur de chaque espace de stockage, et les mises à jour nécessitent que la version candidate prenne en charge la famille.`}},"database%2Efamilies%2Elogbook%2Eengine":{label:{"v1-1e7sns0-m":`Moteur de base de données de la famille`},help:{"v1-fv44v3-77":`Remplace database.engine pour cette famille. Changer de moteur nécessite database port --family et un redémarrage ; modifier la configuration ne migre pas les données existantes. La sauvegarde et la restauration avec plusieurs moteurs préservent le moteur de chaque espace de stockage, et les mises à jour nécessitent que la version candidate prenne en charge la famille.`}},"database%2Efamilies%2Estate%2Eengine":{label:{"v1-1e7sns0-m":`Moteur de base de données de la famille`},help:{"v1-fv44v3-77":`Remplace database.engine pour cette famille. Le changement de moteur nécessite la commande database port --family et un redémarrage ; la modification de la configuration ne migre pas les données existantes. La sauvegarde et la restauration avec plusieurs moteurs préservent le moteur de chaque stockage, et les mises à jour nécessitent la prise en charge de la famille par la version candidate.`}},"database%2Efamilies%2Eteam-reports%2Eengine":{label:{"v1-1e7sns0-m":`Moteur de base de données de la famille`},help:{"v1-fv44v3-77":`Remplace database.engine pour cette famille. Le changement de moteur nécessite la commande database port --family et un redémarrage ; la modification de la configuration ne migre pas les données existantes. La sauvegarde et la restauration avec plusieurs moteurs préservent le moteur de chaque stockage, et les mises à jour nécessitent la prise en charge de la famille par la version candidate.`}},"database%2Efamilies%2Eworkboard%2Eengine":{label:{"v1-1e7sns0-m":`Moteur de base de données de la famille`},help:{"v1-fv44v3-77":`Remplace database.engine pour cette famille. Le changement de moteur nécessite la commande database port --family et un redémarrage ; la modification de la configuration ne migre pas les données existantes. La sauvegarde et la restauration avec plusieurs moteurs préservent le moteur de chaque stockage, et les mises à jour nécessitent la prise en charge de la famille par la version candidate.`}},"database%2Epostgres":{label:{"v1-11caiz7-a":`PostgreSQL`},help:{"v1-1hstnlv-7j":`Connexion à PostgreSQL et nommage des schémas. Les versions 16 à 18 de PostgreSQL sont qualifiées ; les autres versions majeures admises restent expérimentales dans l’attente d’une validation de conformité. Sauvegardez chaque schéma de stockage avec son ancrage SQLite local. Consultez le guide d’exploitation de PostgreSQL pour connaître les limites de qualification des déploiements.`}},"database%2Epostgres%2Econnection":{label:{"v1-17ej0zp-l":`Connexion PostgreSQL`},help:{"v1-1gbko0p-9s":`DSN PostgreSQL partagé, requis dès qu’un moteur effectivement utilisé par une famille est postgres. Prend en charge les SecretRefs de type env, file et exec ainsi que les connexions TLS ; consultez le guide d’exploitation PostgreSQL pour la configuration et les limites de qualification. Les références adossées à un magasin ne peuvent pas initialiser la base de données. L’hôte le résout une seule fois pour les processus de travail de la base de données. Les échecs de connexion n’entraînent jamais de repli vers SQLite.`}},"database%2Epostgres%2Eownership":{label:{"v1-87ucg-s":`Propriété de l’état de Gateway dans PostgreSQL`},help:{"v1-1e7fkqn-cj":`Portée de la propriété de l’état de Gateway (par défaut : state-directory, un fichier de verrouillage local). Le mode installation maintient également un verrou consultatif de session PostgreSQL dont la clé est déterminée par la base de données et le préfixe de schéma. Ainsi, une seconde instance de Gateway ou un autre propriétaire chargé de la maintenance de la même installation est refusé sur tout hôte, et la perte de cette session entraîne l’arrêt de Gateway. Nécessite que toutes les familles configurables utilisent postgres. Les points d’ancrage du stockage et les autres fichiers locaux restent inchangés ; consultez le guide d’exploitation de PostgreSQL.`}},"database%2Epostgres%2ErecoveryCaptures":{label:{"v1-dlnk9p-s":`Captures de récupération PostgreSQL`},help:{"v1-1qes8ml-9m":`Emplacement de stockage des lignes PostgreSQL dans les captures de retour arrière des mises à jour et de Doctor (par défaut : portable). portable écrit une image d’exportation SQLite locale. server conserve les lignes dans un schéma restore_ de la même base de données et n’écrit localement que l’ancre et le manifeste ; ce mode économise de l’espace disque local et du temps d’exportation, mais ne permet pas la récupération en cas de perte du serveur. Les sauvegardes utilisateur restent portables.`}},"database%2Epostgres%2EschemaPrefix":{label:{"v1-1s0mt2q-o":`Préfixe des schémas PostgreSQL`},help:{"v1-1a5738a-7o":`Préfixe des nouveaux schémas de stockage PostgreSQL (par défaut : openclaw). Utilisez entre 1 et 27 lettres minuscules, chiffres ou traits de soulignement, en commençant par une lettre ou un trait de soulignement. Le préfixe pg et les préfixes commençant par pg_ génèrent des noms de schémas réservés dans PostgreSQL. Les ancres existantes conservent leur schéma.`}},desktop:{label:{"v1-rs698z-7":`Bureau`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Bureau local`},help:{"v1-99weio-30":`Observation du bureau pour les nœuds appairés ou la source expérimentale de l’hôte Gateway, via un serveur VNC local.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Partage du bureau`},help:{"v1-m9lbcj-83":`Active la source de bureau de cette machine. Elle est activée par défaut sur les nœuds macOS, Windows et Linux appairés ; une préférence de partage explicite dans l’application de bureau est prioritaire. La source Labs de l’hôte Gateway est désactivée par défaut et applique les modifications en direct. Redémarrez un nœud appairé après avoir modifié sa configuration de bureau.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Bureau géré de l’hôte Linux`},help:{"v1-1r7n22m-49":`Exécute et supervise un bureau TigerVNC/XFCE sans écran sous Linux, accessible uniquement via l’interface de bouclage. Un port explicitement défini ou un serveur VNC existant sur le port par défaut reste prioritaire.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Fichier de mot de passe VNC local`},help:{"v1-1m5lsox-37":`Chemin absolu du fichier de mot de passe VNC. Sous macOS, laissez ce champ vide pour saisir les identifiants du compte à l’ouverture de la visionneuse de bureau.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Port VNC local`},help:{"v1-1ku4w9b-2b":`Port RFB sur l’interface de bouclage d’un serveur VNC déjà en cours d’exécution sur cette machine (par défaut : 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnostics`},help:{"v1-1d5rnym-5p":`Paramètres de diagnostic pour le traçage ciblé, l’exportation de télémétrie et l’inspection du cache pendant le débogage. Limitez les diagnostics de base au minimum en production et n’activez les données plus détaillées que lors de l’analyse de problèmes.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Traçage du cache`},help:{"v1-10523zm-5b":`Paramètres de journalisation du traçage du cache permettant d’observer les décisions relatives au cache et le contexte des données utiles lors des exécutions intégrées. Activez cette fonction temporairement pour le débogage, puis désactivez-la afin de limiter les données sensibles dans les journaux.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Traçage du cache activé`},help:{"v1-2c1umi-1v":`Enregistre des instantanés de traçage du cache pour les exécutions de l’agent intégré (par défaut : false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnostics activés`},help:{"v1-a46pxt-4h":`Interrupteur principal contrôlant la sortie de l’instrumentation de diagnostic dans les journaux et les circuits de télémétrie. Activé par défaut ; définissez-le sur false uniquement dans les environnements soumis à de fortes contraintes.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Indicateurs de diagnostic`},help:{"v1-x4w5ok-33":`Activez des journaux de diagnostic ciblés par indicateur (par exemple ["telegram.http"]). Prend en charge les caractères génériques comme "telegram.*" ou "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Paramètres d’exportation OpenTelemetry pour les traces, les métriques et les journaux émis par les composants de Gateway. À utiliser pour l’intégration à des plateformes d’observabilité centralisées et à des pipelines de traçage distribué.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Capture de contenu OpenTelemetry`},help:{"v1-19tid4t-2t":`Capture facultative du contenu des spans OTEL. Désactivée par défaut ; true capture le contenu des messages non système et des outils.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry activé`},help:{"v1-193bm0-5b":`Active le pipeline d’exportation OpenTelemetry pour les traces, les métriques et les journaux selon les paramètres de point de terminaison et de protocole configurés. Laissez cette option désactivée tant que le point de terminaison du collecteur et l’authentification ne sont pas entièrement configurés.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Point de terminaison OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL du point de terminaison du collecteur utilisée pour le transport des exportations OpenTelemetry, incluant le schéma et le port. Utilisez un point de terminaison de collecteur accessible et fiable, et surveillez les erreurs d’ingestion après le déploiement.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Intervalle d’envoi OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Intervalle en millisecondes entre les envois périodiques des données de télémétrie depuis les tampons vers le collecteur. Augmentez-le pour réduire la fréquence des exportations, ou diminuez-le pour obtenir une visibilité plus rapide lors d’une intervention sur incident.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`En-têtes OpenTelemetry`},help:{"v1-s26t2a-52":`En-têtes de requête HTTP supplémentaires envoyés avec les requêtes d’exportation OpenTelemetry, souvent utilisés pour l’authentification des locataires ou le routage. Conservez les secrets dans des valeurs issues de variables d’environnement et évitez la multiplication inutile des en-têtes.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Journaux OpenTelemetry activés`},help:{"v1-12wo6rv-4k":`Active l’exportation des signaux de journalisation via OpenTelemetry, en complément des destinations de journalisation locales. Utilisez cette option lorsqu’une corrélation centralisée des journaux entre services et agents est nécessaire.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Point de terminaison des journaux OpenTelemetry`},help:{"v1-1vgzldu-40":`Point de terminaison OTLP/HTTP propre au signal de journalisation. Lorsqu’il est défini, il remplace diagnostics.otel.endpoint et OTEL_EXPORTER_OTLP_ENDPOINT uniquement pour l’exportation des journaux.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Exportateur de journaux OpenTelemetry`},help:{"v1-9bzywd-5q":`Destination d’exportation des journaux pour diagnostics.otel.logs. Utilisez "otlp" pour le point de terminaison des journaux OTLP configuré, "stdout" pour produire un enregistrement JSON par ligne stdout dans les pipelines de journaux de conteneurs, et "both" lorsque les deux destinations sont nécessaires.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Préfixe des noms de métriques OpenTelemetry`},help:{"v1-1epdpi9-b2":`Remplace le préfixe par défaut "openclaw." des noms de métriques propres à OpenClaw. Utilisez une chaîne vide pour supprimer le préfixe, ou une chaîne de 128 caractères maximum composée de lettres ASCII, de chiffres, de traits de soulignement, de points, de traits d’union et de barres obliques, commençant par une lettre. Incluez tout séparateur nécessaire, par exemple "acme." ; les noms de métriques standard gen_ai.* restent inchangés. La modification de cette valeur nécessite la mise à jour des tableaux de bord et des alertes qui utilisent les anciens noms dans leurs requêtes.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Métriques OpenTelemetry activées`},help:{"v1-13r4cf4-4x":`Active l’exportation des métriques vers le point de terminaison du collecteur OpenTelemetry configuré. Gardez cette option activée pour les tableaux de bord de santé d’exécution et ne la désactivez que si le volume de métriques doit être réduit au minimum.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Point de terminaison des métriques OpenTelemetry`},help:{"v1-qlfh7x-47":`Point de terminaison OTLP/HTTP propre au signal de métriques. Lorsqu’il est défini, il remplace diagnostics.otel.endpoint et OTEL_EXPORTER_OTLP_ENDPOINT uniquement pour l’exportation des métriques.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Protocole OpenTelemetry`},help:{"v1-17ine8s-5e":`Protocole de transport OTel pour l’exportation de la télémétrie. Seul "http/protobuf" est accepté ; exécutez "openclaw doctor --fix" pour corriger une ancienne valeur "grpc" enregistrée ou obtenir des instructions de modification manuelle adaptées à la source.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Taux d’échantillonnage des traces OpenTelemetry`},help:{"v1-brcwep-50":`Taux d’échantillonnage des traces (0-1) qui détermine la proportion de traces exportées vers les plateformes d’observabilité. Un taux plus faible réduit la surcharge et les coûts, tandis qu’un taux plus élevé améliore la précision du débogage.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Nom du service OpenTelemetry`},help:{"v1-1hpiqon-5d":`Nom du service indiqué dans les attributs de ressource de télémétrie pour identifier cette instance de passerelle dans les plateformes d’observabilité. Utilisez des noms stables afin de préserver la cohérence des tableaux de bord et des alertes au fil des déploiements.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Traces OpenTelemetry activées`},help:{"v1-j7zrrp-4s":`Active l’exportation des traces vers le point de terminaison du collecteur OpenTelemetry configuré. Gardez cette option activée si vous avez besoin de traces pour analyser la latence ou déboguer, et désactivez-la si vous souhaitez uniquement des métriques et des journaux.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Point de terminaison des traces OpenTelemetry`},help:{"v1-8yw5p1-43":`Point de terminaison OTLP/HTTP des traces propre à ce type de signal. Lorsqu’il est défini, il remplace diagnostics.otel.endpoint et OTEL_EXPORTER_OTLP_ENDPOINT uniquement pour l’exportation des traces.`}},discovery:{label:{"v1-l2sr05-9":`Découverte`},help:{"v1-1sqleij-4w":`Paramètres de découverte des services pour l’annonce mDNS locale et la signalisation facultative de présence sur un réseau étendu. Limitez la découverte aux réseaux prévus pour éviter toute fuite de métadonnées des services.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Découverte mDNS`},help:{"v1-vtbyyq-4w":`Groupe de paramètres de découverte mDNS permettant de régler l’annonce sur le réseau local et le comportement de découverte. Conservez le mode minimal pour la découverte courante sur le réseau local, sauf si des métadonnées supplémentaires sont nécessaires.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Mode de découverte mDNS`},help:{"v1-1p28pd5-2m":`Mode de diffusion mDNS ("minimal" par défaut, "full" inclut cliPath/sshPort, "off" désactive mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Découverte sur réseau étendu`},help:{"v1-1akkqjm-53":`Groupe de paramètres de découverte sur réseau étendu permettant d’exposer les signaux de découverte au-delà de la liaison locale. À activer uniquement dans les déploiements qui regroupent volontairement les informations de présence des passerelles sur plusieurs sites.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Domaine de découverte sur réseau étendu`},help:{"v1-rxrygo-4m":`Domaine DNS-SD unicast facultatif pour la découverte sur réseau étendu, tel que openclaw.internal. À utiliser lorsque vous publiez volontairement les informations de découverte des passerelles au-delà de la portée mDNS locale.`}},env:{label:{"v1-1zc80q-b":`Environnement`},help:{"v1-1ao5po6-55":`Paramètres d’importation et de remplacement de l’environnement utilisés pour fournir des variables d’exécution au processus de passerelle. Utilisez cette section pour contrôler le chargement de l’environnement du shell et le comportement d’injection explicite des variables.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Importation de l’environnement du shell`},help:{"v1-1gw487t-4y":`Paramètres d’importation de l’environnement du shell permettant de charger les variables de votre shell de connexion au démarrage. Laissez cette option activée si vous dépendez de secrets définis dans le profil ou de personnalisations de PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Importation de l’environnement du shell activée`},help:{"v1-5tiuup-5u":`Active le chargement des variables d’environnement depuis le profil du shell de l’utilisateur lors de l’initialisation au démarrage. Laissez cette option activée sur les machines de développement, ou désactivez-la dans les environnements de service verrouillés où l’environnement est géré explicitement.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Délai d’expiration de l’importation de l’environnement du shell (ms)`},help:{"v1-nsk2yf-5c":`Durée maximale en millisecondes accordée à la résolution de l’environnement du shell avant l’application du mécanisme de repli. Réduisez ce délai pour accélérer le démarrage, ou augmentez-le si l’initialisation du shell est longue.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Remplacements des variables d’environnement`},help:{"v1-1uloveo-5t":`Remplacements explicites de variables d’environnement sous forme de paires clé/valeur, fusionnés dans l’environnement du processus d’exécution d’OpenClaw. Utilisez cette option pour une configuration prévisible de l’environnement plutôt que de dépendre uniquement des effets de bord du profil du shell.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-1hooncl-5s":`Paramètres d’exécution du Gateway pour le mode d’écoute, l’authentification, l’application web, le transport distant et les contrôles de sécurité opérationnelle. Conservez les valeurs par défaut prudentes, sauf si vous exposez volontairement le Gateway au-delà des interfaces locales de confiance.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Autoriser le repli sur x-real-ip pour Gateway`},help:{"v1-1wr3qmw-4c":`Active le repli sur x-real-ip lorsque x-forwarded-for est absent dans les configurations avec proxy. Laissez cette option désactivée, sauf si votre infrastructure d’entrée nécessite ce comportement de compatibilité.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Authentification de Gateway`},help:{"v1-70b6ni-50":`Politique d’authentification pour l’accès HTTP/WebSocket au Gateway, notamment le mode, les identifiants, le comportement du proxy de confiance et la limitation du débit. Gardez l’authentification activée pour tout déploiement accessible hors de l’interface de bouclage.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Autoriser l’identité Tailscale pour l’authentification du Gateway`},help:{"v1-vqtmgw-53":`Permet aux mécanismes d’identité Tailscale de confiance de satisfaire aux vérifications d’authentification du Gateway lorsqu’ils sont configurés. Utilisez cette option uniquement si la sécurité des identités de votre tailnet est solide et si les processus des opérateurs en dépendent.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Autorisations de portée par identité du Gateway`},help:{"v1-1h0zxy7-5n":`Associe les identités vérifiées issues d’un proxy de confiance ou de Tailscale à des autorisations de portée opérateur valables uniquement pour la connexion. La correspondance des clés d’adresse e-mail ne tient pas compte de la casse ; les autorisations complètent les portées de l’appareil avant l’application du plafond de portée de la connexion.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Mode d’authentification du Gateway`},help:{"v1-j8rodq-9t":`Mode d’authentification du Gateway : "none", "token", "password" ou "trusted-proxy", selon votre architecture périmétrique. Le mode par jeton ou mot de passe sélectionne le secret configuré (gateway.auth.token ou gateway.auth.password) ; les clients peuvent l’envoyer dans l’un ou l’autre des champs d’authentification de connexion. Utilisez un jeton ou un mot de passe en cas d’exposition directe, et trusted-proxy uniquement derrière des proxys sécurisés prenant en compte l’identité.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Mot de passe du Gateway`},help:{"v1-1ndt0u2-4g":`Secret partagé sélectionné par gateway.auth.mode=password. Les clients peuvent l’envoyer dans auth.token ou auth.password. Le mode par mot de passe est requis pour Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Limitation du débit d’authentification du Gateway`},help:{"v1-1kstr42-54":`Paramètres de limitation des tentatives de connexion et d’authentification pour réduire le risque d’attaques par force brute sur les identifiants au niveau du Gateway. Gardez cette protection activée dans les environnements exposés et adaptez les seuils à votre trafic habituel.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Jeton du Gateway`},help:{"v1-16i7cxs-5q":`Secret partagé sélectionné par gateway.auth.mode=token, le mode par défaut pour les nouvelles configurations locales. Les clients peuvent l’envoyer dans auth.token ou auth.password. L’écoute sur des adresses autres que celles de bouclage nécessite un mode d’authentification activé.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Authentification du Gateway par proxy de confiance`},help:{"v1-12fsi5d-58":`Mappage des en-têtes d’authentification par proxy de confiance pour les fournisseurs d’identité en amont qui injectent des attributs utilisateur. À utiliser uniquement avec des plages CIDR de proxy connues et des listes d’autorisation d’en-têtes strictes pour empêcher l’usurpation des en-têtes d’identité.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Identité GitHub via Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Identité GitHub vérifiée facultative provenant d’un fournisseur OIDC Cloudflare Access sélectionné. Nécessite les en-têtes standard d’adresse e-mail et d’assertion d’Access. En l’absence de revendications, les profils restent basés uniquement sur l’adresse e-mail ; les rôles et les préférences de co-auteur des profils existants sont conservés.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Revendication d’identifiant de compte GitHub`},help:{"v1-qd4qvh-87":`Attribut OIDC transmis exact dont la valeur est un identifiant de compte GitHub vérifié, sous forme de chaîne représentant un entier décimal positif. Configurez Access pour le transmettre, puis examinez la réponse d’identité authentifiée d’Access. OpenClaw lit oidc_fields, ou custom si oidc_fields est absent. N’utilisez jamais un attribut non vérifié modifiable par l’utilisateur.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Émetteur Cloudflare Access`},help:{"v1-gykv03-56":`Origine HTTPS exacte de l’équipe Cloudflare Access de confiance, par exemple https://example.cloudflareaccess.com, sans barre oblique finale. Les revendications provenant d’autres émetteurs ne fournissent pas d’identité GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`ID du fournisseur OIDC Cloudflare Access`},help:{"v1-kbyo5w-44":`ID exact du fournisseur d’identité Access pour l’intégration OIDC de confiance. Le nom d’affichage d’un fournisseur ou un nom de revendication correspondant ne suffit pas à établir la confiance.`}},"gateway%2Eauth%2EtrustedProxy%2Edelegation":{label:{"v1-gzv594-t":`Délégation du navigateur d’entreprise`},help:{"v1-1i9071w-4d":`Accepter l’identité du navigateur OCE et les autorisations de portée limitées à une révision via le proxy de confiance privé. Les profils délégués n’utilisent ni alias d’adresse e-mail ni autorisations d’appareil.`}},"gateway%2Eauth%2EtrustedProxy%2Edelegation%2EcredentialFile":{label:{"v1-vi5w92-q":`Fichier d’identifiants de délégation`},help:{"v1-1tfpp2u-4t":`Chemin absolu vers un fichier privé contenant l’identifiant de 32 octets de la révision sous la forme de 64 caractères hexadécimaux minuscules. Le remplacement ou la suppression du fichier invalide les autorisations existantes.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Approbation automatique des appareils par proxy de confiance`},help:{"v1-uh32ha-6z":`Politique facultative permettant d’approuver automatiquement les nouveaux appareils des opérateurs utilisant un navigateur ou une interface native, ainsi que les extensions de portée pour une même clé, après une authentification par proxy de confiance. Les autorisations accordées sont limitées par deviceAutoApprove.scopes et par l’en-tête x-openclaw-scopes du proxy, s’il est présent.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Approbation automatique des appareils par proxy de confiance activée`},help:{"v1-1nntwls-78":`Approuve automatiquement les nouveaux appareils des opérateurs utilisant un navigateur ou une interface native, ainsi que les extensions de portée pour une même clé, après que le proxy inverse a authentifié un utilisateur autorisé. Valeur par défaut : false. À activer uniquement lorsque la protection de l’identité assurée par le proxy est suffisamment robuste pour remplacer l’appairage manuel des appareils.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Portées d’autorisation pour l’approbation automatique des appareils via un proxy de confiance`},help:{"v1-raeila-g3":`Portées d’autorisation maximales accordées aux appareils opérateurs approuvés automatiquement. Valeurs par défaut : operator.read, operator.write, operator.approvals et operator.questions. Les portées demandées sont limitées à cette liste ; les demandes sans portée reçoivent cette liste. Si ce paramètre n’est pas défini, l’approbation automatique ajoute également operator.questions pour les anciens clients de l’interface utilisateur ; une liste explicite n’est jamais étendue. Inclure explicitement operator.admin permet à chaque utilisateur authentifié par proxy d’obtenir automatiquement tous les droits d’administration et accorde automatiquement ces droits aux demandes sans portée ; cela déclenche également un constat critique lors de l’audit de sécurité et un avertissement au démarrage de Gateway.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor":{help:{"v1-dai5ie-71":`Coordonnées de co-auteur par défaut facultatives de l’organisation, issues des en-têtes du proxy authentifié. Le proxy doit écraser ces champs. Ils ne vérifient pas l’identité GitHub et n’accordent aucune autorisation ; les adresses e-mail fournies nécessitent un consentement enregistré avant d’apparaître dans l’historique des commits.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EemailHeader":{help:{"v1-1j8gxp7-2h":`En-tête contenant l’adresse e-mail d’attribution des commits fournie par l’organisation pour l’entité authentifiée.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EemailVerifiedHeader":{help:{"v1-64bvpw-49":`En-tête facultatif dont la valeur doit être true pour que les coordonnées par défaut de l’organisation soient importées. Ne l’omettez que si l’assertion du proxy concernant l’adresse e-mail suffit à satisfaire votre politique.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EnameHeader":{help:{"v1-14uvheq-2c":`En-tête contenant le nom de coauteur défini par l’organisation pour l’entité authentifiée.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Mode de liaison réseau de Gateway`},help:{"v1-1unqude-4y":`Profil de liaison réseau : "auto", "lan", "loopback", "custom" ou "tailnet" pour contrôler l’exposition des interfaces. Conservez "loopback" pour un fonctionnement exclusivement local ; "auto" peut exposer toutes les interfaces.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`Agents CLI`},help:{"v1-1unx5p8-57":`Découverte, dans l’application web, des moteurs de session CLI externes exposés par le catalogue de sessions du Gateway. Activée par défaut ; désactivez-la pour empêcher le démarrage de ces moteurs depuis le sélecteur de modèle des nouvelles sessions.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`Agents CLI activés`},help:{"v1-9ei1mn-8m":`Affiche les agents CLI issus du catalogue dans le sélecteur de modèle des nouvelles sessions de l’application web lorsque la valeur est true (par défaut : true). Définissez la valeur sur false pour désactiver les agents CLI et la création de sessions CLI natives. Seuls les catalogues annonçant la prise en charge de la création de sessions sont répertoriés, et le sélecteur reste masqué lorsque le Gateway n’annonce pas la prise en charge du catalogue de sessions.`}},"gateway%2EcontrolUi":{label:{"v1-zyppo6-7":`Application web`},help:{"v1-v2rtyb-5f":`Paramètres d’hébergement de l’application web, notamment l’activation, les chemins et le renforcement de la sécurité des origines du navigateur et de l’authentification. Limitez au minimum l’exposition de l’interface et mettez en place des contrôles d’authentification robustes avant tout déploiement accessible depuis Internet.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-14ny3x-n":`Origines autorisées pour l’application web`},help:{"v1-1br04sw-aq":`Origines de navigateur autorisées pour les connexions à l’application web et à WebChat (origines complètes uniquement, par exemple https://control.example.com). Si ce paramètre est omis, gateway.publicOrigin est utilisé par défaut s’il est configuré. Une liste explicite, y compris [], remplace cette valeur par défaut ; les règles existantes relatives aux origines locales et privées restent applicables. La valeur ["*"] autorise toutes les origines de navigateur et doit être évitée en dehors de tests locaux strictement contrôlés.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-ylb79x-x":`Autoriser les URL externes intégrées à l’application web`},help:{"v1-y8g73z-62":`Option DANGEREUSE qui permet aux contenus intégrés hébergés de charger des URL http(s) externes absolues. Laissez cette option désactivée, sauf si votre application web intègre volontairement des pages tierces de confiance ; les documents hébergés sous /__openclaw__/canvas n’en ont pas besoin.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Récupérer automatiquement les favicons des liens`},help:{"v1-1dimlov-ac":`Récupérer les favicons des liens et les aperçus des pages des liens externes via la Gateway (activé par défaut). Les aperçus de pages chargent les métadonnées publiques des pages et les images déclarées, sans cookies du navigateur ni identifiants de connexion aux sites. Toutes les requêtes sont soumises à des contrôles SSRF stricts et à des limites de traitement du HTML et des images. Définissez la valeur sur false pour désactiver la récupération automatique des favicons et des aperçus de pages ; les captures d’écran du navigateur en direct ne sont pas affectées.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-zclsby-h":`Chemin de base de l’application web`},help:{"v1-npn03b-1t":`Préfixe d’URL facultatif sous lequel l’application web est accessible (par exemple /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-13uozha-s":`Invitation à rejoindre la communauté dans l’application web`},help:{"v1-1m3mu0g-7i":`Affiche une carte Communauté pouvant être masquée dans la barre latérale de l’application web (activée par défaut), avec des liens vers Discord, Reddit et X. Définissez ce paramètre sur false pour la masquer dans tous les navigateurs utilisant ce déploiement de l’interface. Les modifications s’appliquent après l’actualisation du navigateur ou la reconnexion. Les choix de masquage déjà enregistrés localement dans les navigateurs restent respectés.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Autoriser le repli dangereux sur l’origine de l’en-tête Host`},help:{"v1-1i3oa94-7s":`Option DANGEREUSE qui active une solution de repli basée sur l’en-tête Host pour les vérifications d’origine des connexions WebSocket de l’application web et de WebChat. Ce mode est pris en charge lorsque votre déploiement repose délibérément sur une politique d’origine basée sur l’en-tête Host ; la configuration explicite de gateway.controlUi.allowedOrigins reste le choix par défaut recommandé pour une sécurité renforcée.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-kc00jb-q":`Mode sandbox des contenus intégrés à l’application web`},help:{"v1-176jrc2-79":'Politique sandbox des iframes pour les contenus intégrés à l’application web hébergée. "strict" désactive les scripts, "scripts" autorise les contenus intégrés interactifs tout en maintenant l’isolation des origines (par défaut), et "trusted" ajoute `allow-same-origin` pour les documents du même site qui nécessitent délibérément des privilèges plus élevés.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-vpzojz-f":`Application web activée`},help:{"v1-1u14fve-4l":`Permet de servir l’application web depuis le processus HTTP de la passerelle lorsque la valeur est true. Gardez cette option activée pour l’administration locale et désactivez-la lorsqu’une interface de contrôle externe la remplace.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-1d85isf-j":`Environnement de l’application web`},help:{"v1-vlhh70-4k":`Identité publique facultative de l’environnement, affichée dans le bandeau de l’application web, l’avatar de l’agent, les pastilles de libellé, le titre du navigateur et la favicon. Omettez-la pour conserver l’apparence par défaut.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-1h2k80-p":`Couleur de l’environnement de l’application web`},help:{"v1-mp6cta-2i":`Palette de couleurs nommée de l’environnement : teal, amber, purple, coral, pink, blue, green, red ou gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-vrxwqd-p":`Libellé de l’environnement de l’application web`},help:{"v1-1l8ng2x-3w":`Libellé de l’environnement affiché dans l’application web et l’onglet du navigateur ; les espaces en début et en fin sont supprimés et le libellé doit contenir entre 1 et 24 caractères.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-1oh9bbh-t":`Fonctionnalités expérimentales de l’application web`},help:{"v1-d3p8ng-3m":`Fonctionnalités expérimentales de l’application web et options de remplacement avancées conservées. Les fonctionnalités expérimentales sont désactivées par défaut, sauf indication contraire dans la documentation de leur paramètre.`}},"gateway%2EcontrolUi%2Eexperimental%2EchatBubbles":{label:{"v1-1i4j62s-e":`Bulles de conversation`},help:{"v1-19ex4en-5j":`Activer les bulles de conversation expérimentales dans l’application web (par défaut : false). Lorsqu’elles sont activées, l’accueil utilise les bulles par défaut ; les choix par session enregistrés localement dans le navigateur sont prioritaires. Les modifications s’appliquent sans redémarrage de Gateway.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Interface des plugins personnalisés`},help:{"v1-18073xm-by":`Autoriser les plugins activés installés par l’utilisateur à exécuter du JavaScript natif dans l’application web (par défaut : true). Ce paramètre est conservé comme option avancée de désactivation, accessible uniquement dans la configuration ; les valeurs false existantes maintiennent la désactivation. Les vues des plugins intégrés ne sont pas affectées. L’interface native dispose des mêmes autorisations Gateway que l’opérateur connecté ; installez uniquement des plugins de confiance. Les modifications s’appliquent sans redémarrage de Gateway. Après la désactivation, rechargez les pages ouvertes de l’application web pour supprimer le code des plugins précédemment chargé.`}},"gateway%2EcontrolUi%2Eexperimental%2Etemplates":{label:{"v1-it5x1k-9":`Modèles`},help:{"v1-1879y2q-3u":`Activer la découverte sur ClawHub et l’ajout unidirectionnel via l’application web et Gateway (par défaut : false). Les agents existants continuent de fonctionner lorsque cette option est désactivée.`}},"gateway%2EcontrolUi%2Egithub%2Ehost":{label:{"v1-rjp3f8-r":`Hôte du service GitHub de l’application web`},help:{"v1-qaa5xb-3z":`Hôte auquel cet identifiant de service peut accéder. Omettez-le pour github.com ; définissez-le sur gateway.github.host pour la découverte des projets Enterprise et les métadonnées des comptes.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1ia5u0n-x":`Identifiant d’authentification du service GitHub de l’application web`},help:{"v1-uw4wdq-b5":`Identifiant d’authentification de service reposant sur SecretRef pour la découverte de projets dans l’application web et les aperçus GitHub au survol sans identité gérée. Définissez gateway.controlUi.github.host pour Enterprise ; si l’hôte est omis, github.com est utilisé. Les aperçus au survol privilégient l’identité GitHub configurée de l’agent sélectionné. Le recours à GH_TOKEN/GITHUB_TOKEN ne s’applique qu’à github.com. Les requêtes utilisant un identifiant d’authentification incompatible ou indisponible sont rejetées.`}},"gateway%2EcontrolUi%2EnewSessionModelDefaults":{label:{"v1-bxfhmu-q":`Paramètres par défaut du modèle pour les nouvelles sessions`},help:{"v1-1r6o74t-98":`Choisissez "configured" pour créer de nouveaux brouillons dans l’application web avec le modèle, l’environnement d’exécution et les paramètres de raisonnement par défaut configurés pour l’agent sélectionné, plutôt qu’avec les sélections mémorisées. Valeur par défaut : "last-used". Les choix explicites pour les brouillons et les conversations restent modifiables ; le mode rapide et les préférences de placement restent inchangés. S’applique après l’actualisation du navigateur ou la reconnexion.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-1ke8erh-j":`Répertoire racine des ressources de l’application web`},help:{"v1-192j3ry-22":`Répertoire racine facultatif du système de fichiers pour les ressources de l’application web (par défaut : dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-zsqsj8-o":`Observateur de sessions de l’application web`},help:{"v1-1uilm4q-87":`Génère des résumés en temps réel de l’état des sessions pour les clients abonnés de l’application web à l’aide du modèle utilitaire de chaque agent (activé par défaut). Définissez la valeur sur false pour désactiver les appels au modèle d’observation sur l’ensemble de la passerelle ; définir agents.defaults.utilityModel sur une chaîne vide désactive l’observation par modèle utilitaire pour les agents qui ne remplacent pas ce paramètre.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Hôte d’écoute personnalisé du Gateway`},help:{"v1-lwjcyo-4d":`Adresse IPv4 utilisée pour une écoute personnalisée. Les adresses IPv4 spécifiques nécessitent également le même port Gateway sur 127.0.0.1 ; évitez 0.0.0.0 sauf si une exposition sur toutes les interfaces est requise.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`API HTTP du Gateway`},help:{"v1-9vup6v-4y":`Configuration de l’API HTTP du Gateway regroupant les options d’activation des points de terminaison et les contrôles d’exposition de l’API au niveau du transport. N’activez que les points de terminaison nécessaires afin de limiter les accès des appelants distants.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Points de terminaison HTTP du Gateway`},help:{"v1-1a0r104-55":`Options d’activation des points de terminaison HTTP de l’API du Gateway pour les routes de compatibilité et les intégrations facultatives. Activez les points de terminaison de manière délibérée et surveillez les schémas d’accès après le déploiement.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Point de terminaison OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Activer le point de terminaison `POST /v1/chat/completions` compatible avec OpenAI (par défaut : false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Limites des images pour OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Paramètres de récupération et de validation des images pour les éléments `image_url` compatibles avec OpenAI."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Liste des types MIME d’image autorisés pour OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Types MIME autorisés pour les éléments `image_url` (liste insensible à la casse)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Autoriser les URL d’image pour OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Autoriser la récupération par URL côté serveur pour les éléments `image_url` (par défaut : false ; les URI de données restent prises en charge). Définissez cette option sur `false` pour désactiver entièrement la récupération par URL."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Taille maximale des images en octets pour OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Nombre maximal d’octets par image `image_url` récupérée ou décodée (par défaut : 10 Mo)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Nombre maximal de redirections pour les images OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Nombre maximal de redirections HTTP autorisées lors de la récupération des URL `image_url` (par défaut : 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Délai d’expiration des images OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Délai d’expiration en millisecondes pour la récupération des URL `image_url` (par défaut : 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Liste d’autorisation des URL d’images OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Liste facultative des noms d’hôte autorisés pour la récupération des URL `image_url` ; prend en charge les noms d’hôte exacts et les motifs génériques de type `*.example.com`. Une liste vide ou omise signifie qu’aucune restriction par liste d’autorisation des noms d’hôte ne s’applique."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`En-têtes de sécurité HTTP du Gateway`},help:{"v1-n8z1hb-44":`En-têtes de sécurité facultatifs des réponses HTTP, appliqués par le processus Gateway lui-même. Configurez-les de préférence au niveau de votre proxy inverse si la terminaison TLS s’y effectue.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`En-tête de sécurité stricte du transport`},help:{"v1-1buwhc3-3v":`Valeur de l’en-tête de réponse Strict-Transport-Security. À définir uniquement pour les origines HTTPS que vous contrôlez entièrement ; utilisez false pour le désactiver explicitement.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Mode du Gateway`},help:{"v1-nfjirv-5m":`Mode de fonctionnement du Gateway : "local" exécute les canaux et l’environnement d’exécution de l’agent sur cet hôte, tandis que "remote" se connecte via un transport distant. Conservez "local", sauf si vous utilisez délibérément une topologie de Gateway distant répartie.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills des nœuds du Gateway activés`},help:{"v1-1xwu6at-3g":`Accepter les Skills publiés par les nœuds appairés tant qu’ils sont connectés (valeur par défaut : true). Définissez cette option sur false pour ignorer les Skills publiés par les nœuds.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Mode de routage du navigateur des nœuds du Gateway`},help:{"v1-oeu1nc-69":`Routage du navigateur via les nœuds (« auto » = privilégier le navigateur de l’hôte et utiliser un seul nœud de navigateur connecté lorsque la fonctionnalité locale est indisponible ; « manual » = exiger la sélection explicite d’un nœud ou une affectation fixe configurée ; « off » = désactiver le routage via les nœuds).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Nœud fixe pour le navigateur du Gateway`},help:{"v1-1cykty2-1p":`Fixer le routage du navigateur sur un nœud précis à l’aide de son identifiant ou de son nom (facultatif).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Liste d’autorisation des nœuds du Gateway (commandes supplémentaires)`},help:{"v1-6l4otb-5m":"Commandes node.invoke supplémentaires à autoriser en plus de celles autorisées par défaut par le Gateway (tableau de chaînes de commandes). L’activation de commandes dangereuses ici constitue une dérogation sensible en matière de sécurité et est signalée par `openclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Liste de blocage des nœuds du Gateway`},help:{"v1-u7c8wx-53":"Noms des commandes de nœud à bloquer, même si elles figurent dans les capacités déclarées par le nœud ou dans la liste d’autorisation par défaut (correspondance exacte du nom de commande uniquement, par exemple `system.run` ; le texte shell contenu dans cette commande n’est pas inspecté)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Appairage des nœuds du Gateway`},help:{"v1-gldsi2-4s":`Paramètres de la politique d’appairage des nœuds. L’approbation automatique vérifiée par SSH est activée par défaut ; l’approbation automatique par CIDR reste désactivée tant que des listes d’autorisation explicites de CIDR/IP de confiance ne sont pas configurées.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR d’approbation automatique de l’appairage des nœuds Gateway`},help:{"v1-jeel9f-6u":`Liste d’autorisation CIDR/IP facultative permettant d’approuver automatiquement le premier appairage des appareils ayant le rôle de nœud, sans aucune portée demandée. Désactivée si elle n’est pas définie. Les appairages d’opérateurs, de navigateurs et de l’application web, ainsi que tout appairage impliquant une modification de rôle, de portée, de métadonnées ou de clé publique, nécessitent toujours une approbation manuelle.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Approbation automatique de l’appairage local des nœuds Gateway`},help:{"v1-glzm36-41":`Approuve sans confirmation les appairages locaux de confiance et les extensions d’accès (par défaut : true) ; définissez sur false pour privilégier l’approbation explicite de chaque appareil plutôt que la facilité d’utilisation.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Vérification SSH de l’appairage des nœuds Gateway`},help:{"v1-1e4da92-ct":"Approbation automatique vérifiée par SSH pour le premier appairage d’appareils ayant le rôle de nœud (activée par défaut). La passerelle se connecte en retour par SSH à l’hôte demandant l’appairage (BatchMode, vérification stricte des clés d’hôte) et n’approuve que si la sortie distante de `openclaw node identity` correspond à la clé de l’appareil en attente. Définissez sur false pour désactiver la vérification SSH (indépendamment de autoApproveCidrs, qui reste actif) ; pour un appairage exclusivement manuel, supprimez également la valeur de autoApproveCidrs. Fournissez un objet pour remplacer user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Outils de plugins des nœuds Gateway`},help:{"v1-1c24iq3-28":`Détermine si les nœuds appairés peuvent publier des descripteurs d’outils de plugins visibles par les agents.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Outils de plugins des nœuds du Gateway activés`},help:{"v1-14lgfu6-47":`Accepter les descripteurs d’outils de plugins visibles par l’agent et publiés par les nœuds appairés (par défaut : true). Définissez cette option sur false pour ignorer et supprimer tous les outils de plugins publiés par les nœuds.`}},"gateway%2EopenclawId":{label:{"v1-ezzq9b-p":`Accès à distance OpenClaw ID`},help:{"v1-1ulzsn4-95":`Accès à distance expérimental OpenClaw ID (Labs). Lorsque cette option est activée, la passerelle supervise un processus enfant de tunnel qui accepte les connexions iroh provenant d’appareils autorisés et les transmet à cette passerelle. Cette option est désactivée par défaut ; tant qu’elle est désactivée, la passerelle ne lance aucun processus enfant, n’ouvre aucun socket de tunnel et ne contacte ni OpenClaw ID, ni Discovery, ni aucun service de relais.`}},"gateway%2EopenclawId%2EclientId":{label:{"v1-1g7ikna-t":`Identifiant client OpenClaw ID de l’application web`},help:{"v1-4vjfwu-8r":`Client OAuth public (code d’autorisation avec PKCE) utilisé par l’application web pour la connexion avec OpenClaw ID dans son menu de compte. Son URI de redirection est <web app origin>/openclaw-id/callback. Sur cette machine, la connexion utilise cette redirection ; une application web accessible via une connexion personnelle telle que Tailscale utilise le flux d’autorisation d’appareil de l’émetteur.`}},"gateway%2EopenclawId%2EdiscoveryUrl":{label:{"v1-hnez1c-p":`URL de Discovery pour OpenClaw ID`},help:{"v1-14rpvwb-5h":`Service Discovery qui réplique le descripteur du claw et l’instantané des adhésions, et relaie les messages de la boîte aux lettres. Ce service n’est pas considéré comme fiable : chaque déclaration qu’il renvoie est vérifiée à l’aide de la racine de confiance épinglée du propriétaire du claw.`}},"gateway%2EopenclawId%2Eenabled":{label:{"v1-c5v95y-x":`Accès à distance OpenClaw ID activé`},help:{"v1-19yjuzt-66":`Active l’accès à distance expérimental OpenClaw ID (valeur par défaut : false). Les modifications s’appliquent sans redémarrage de la passerelle. L’accès à distance nécessite également relayUrl ; l’association d’un claw nécessite en plus issuerUrl, discoveryUrl et loaderDomain.`}},"gateway%2EopenclawId%2EissuerUrl":{label:{"v1-g27qab-m":`URL de l’émetteur OpenClaw ID`},help:{"v1-dmrsc-4e":`Émetteur OpenClaw ID utilisé pour se connecter uniquement à des fins d’identification lors de l’association d’un claw. Il n’est jamais considéré comme une autorité de confiance pour les adhésions, l’approbation des appareils ou le choix du serveur auquel un client se connecte.`}},"gateway%2EopenclawId%2EloaderDomain":{label:{"v1-1m8dm2q-p":`Domaine du chargeur OpenClaw ID`},help:{"v1-1xj9br0-4o":`Domaine DNS seul du chargeur OpenClaw ID ; un claw lié est accessible à l’adresse https://<name>-<account tag>.<loaderDomain> et sa liaison au serveur est signée pour ce nom d’hôte.`}},"gateway%2EopenclawId%2EmemberDeviceInactivityDays":{label:{"v1-bv2n4v-17":`Inactivité des appareils des membres OpenClaw ID (jours)`},help:{"v1-1n802ug-3g":`Nombre de jours pendant lesquels le navigateur d’un membre peut rester sans contacter ce claw avant que celui-ci ne le supprime (par défaut : 30). Le membre reste dans la liste.`}},"gateway%2EopenclawId%2EownerDeviceInactivityDays":{label:{"v1-1elnzyi-16":`Inactivité des appareils des propriétaires OpenClaw ID (jours)`},help:{"v1-cy2c02-3x":`Nombre de jours pendant lesquels l’appareil d’un propriétaire peut rester sans contacter ce claw avant que celui-ci ne le retire de sa liste d’autorisation (par défaut : 90). Les appareils approuvés par cet appareil sont conservés.`}},"gateway%2EopenclawId%2ErelayUrl":{label:{"v1-1r8to4f-l":`URL du relais OpenClaw ID`},help:{"v1-1f4exuo-3w":`Le seul relais iroh dans la carte des relais du point de terminaison du tunnel (aucun relais n0 public, ni DNS, ni pkarr). Les navigateurs accèdent au claw uniquement via ce relais.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Port du Gateway`},help:{"v1-af1nrn-51":`Port TCP utilisé par le service d’écoute de la passerelle pour l’API, l’application web et les points d’entrée des canaux. Utilisez un port dédié et évitez les conflits avec les proxys inverses ou les services de développement locaux.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Portails du Gateway`},help:{"v1-1v2lkw9-1c":`Paramètres de publication des portails et de point d’entrée privé.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Point d’entrée privé des portails`},help:{"v1-20w4gq-69":`Proxy inverse HTTPS privé facultatif, géré par l’opérateur et prenant en charge les sous-domaines génériques. Transmettez l’en-tête Host d’origine, les chemins et les demandes de mise à niveau WebSocket au service d’écoute dédié sur l’interface de bouclage. L’authentification du portail par jeton bearer reste obligatoire. Nécessite un redémarrage du Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Domaine générique des portails`},help:{"v1-1ffvdzt-50":`Domaine DNS nu pour les sous-domaines aléatoires des portails (par exemple previews.example.net). Configurez le DNS générique et HTTPS de manière privée ; ne partagez pas l’espace de noms d’hôte de Gateway ou de l’application web.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Port de bouclage du point d’entrée des portails`},help:{"v1-1mb98cv-4g":`Port HTTP de bouclage dédié recevant le trafic du proxy HTTPS privé à domaine générique. Il doit être différent du port du Gateway. Il s’agit du port du serveur backend, et non du port HTTPS public.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Origine publique du Gateway`},help:{"v1-1c6onp0-ae":`Origine HTTPS de Gateway accessible depuis l’extérieur. Également utilisée comme origine par défaut du navigateur lorsque gateway.controlUi.allowedOrigins n’est pas défini. HTTP n’est autorisé que pour localhost, 127.0.0.1 ou [::1]. Le mécanisme OAuth de MCP propre à chaque demandeur l’utilise pour construire l’URL de rappel à l’adresse /oauth/mcp/callback ; les liens de session des canaux et les liens de visualisation générés par les plugins l’utilisent pour accéder à l’application web et aux routes de Gateway.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Envoi de notifications push du Gateway`},help:{"v1-h23oz7-5s":`Paramètres d’envoi de notifications push utilisés par le Gateway lorsqu’il doit réveiller les appareils appairés ou leur envoyer une notification. Configurez ici les APNs via relais pour les versions iOS officielles ; l’authentification APNs directe reste fondée sur les variables d’environnement pour les versions locales ou manuelles.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Envoi APNs du Gateway`},help:{"v1-4bbafr-4e":`Paramètres d’envoi APNs pour les appareils iOS appairés à ce Gateway. Utilisez les paramètres de relais pour les versions officielles de l’App Store qui s’enregistrent via le relais externe de notifications push.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Relais APNs du Gateway`},help:{"v1-7glbel-6x":`Paramètres du relais externe pour les envois APNs via un relais. Le Gateway utilise par défaut le relais OpenClaw hébergé, ou ce relais personnalisé pour push.test, les sollicitations de réveil et les réveils de reconnexion, après qu’une version iOS officielle appairée a publié un enregistrement via un relais.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`URL de base du relais APNs du Gateway`},help:{"v1-1o8mgnq-69":`URL HTTPS de base personnalisée facultative pour le service de relais APNs externe utilisé par les versions iOS officielles de l’App Store. Veillez à ce qu’elle corresponde à l’URL du relais intégrée à la version iOS, afin que le trafic d’enregistrement et d’envoi atteigne le même déploiement.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Délai d’expiration du relais APNs du Gateway (ms)`},help:{"v1-a0jkb1-4z":`Délai d’expiration en millisecondes des requêtes d’envoi du Gateway au relais APNs (par défaut : 10000). Augmentez-le pour les relais ou réseaux plus lents, ou réduisez-le pour interrompre plus rapidement les tentatives de réveil infructueuses.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Rechargement de la configuration`},help:{"v1-d02mvq-4w":`Politique de rechargement de la configuration à chaud définissant comment les modifications sont appliquées et quand des redémarrages complets sont déclenchés. Conservez le comportement hybride pour des mises à jour opérationnelles aussi sûres que possible, sauf si vous déboguez les mécanismes internes du rechargement.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Mode de rechargement de la configuration`},help:{"v1-1q1etcf-3m":`Détermine comment les modifications de configuration sont appliquées : "off" ignore les modifications à chaud et "hybrid" applique celles qui peuvent l’être sans risque, puis redémarre si nécessaire.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Gateway distant`},help:{"v1-6xv7gd-5a":`Paramètres de connexion au Gateway distant par transport direct ou SSH lorsque cette instance sert de proxy vers un autre hôte d’exécution. Utilisez le mode distant uniquement lorsqu’un fonctionnement réparti sur plusieurs hôtes est intentionnellement configuré.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`En-têtes d’authentification périphérique du Gateway distant`},help:{"v1-jg9p7d-5o":`En-têtes HTTP reposant sur des secrets, présentés à un proxy tenant compte de l’identité placé devant le Gateway distant configuré. Les en-têtes sont envoyés uniquement à l’origine exacte de gateway.remote.url via WSS et ne suivent jamais les redirections.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Mot de passe du Gateway distant`},help:{"v1-16jc0yx-7y":`Secret partagé envoyé dans le champ de mot de passe pour authentifier ce client auprès d’un Gateway distant. Le paramètre gateway.auth.mode du serveur sélectionne le secret configuré ; le champ de jeton ou de mot de passe du client est accepté. Gérez ce secret en externe et évitez les valeurs en clair dans la configuration placée sous gestion de versions.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Politique de clé d’hôte SSH du Gateway distant`},help:{"v1-7qoxtb-49":`Politique de vérification des clés d’hôte SSH sous macOS. "strict" exige une clé d’hôte déjà approuvée ; "openssh" délègue explicitement la vérification à la configuration OpenSSH effective.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Identité SSH du Gateway distant`},help:{"v1-hz2hsm-1f":`Chemin facultatif du fichier d’identité SSH (transmis à ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Cible SSH du Gateway distant`},help:{"v1-85w39w-2t":`Gateway distant via SSH (redirige le port du Gateway vers localhost par un tunnel). Format : user@host ou user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Empreinte TLS du Gateway distant`},help:{"v1-1ri16lk-23":`Empreinte TLS sha256 attendue pour le Gateway distant (à épingler pour éviter les attaques MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Jeton du Gateway distant`},help:{"v1-1pb9q8w-7v":`Secret partagé envoyé dans le champ token pour authentifier ce client auprès d’un Gateway distant. Le paramètre gateway.auth.mode du serveur sélectionne le secret configuré ; le champ token ou password du client est accepté. Stockez-le via une substitution de secret ou de variable d’environnement et renouvelez-le lors des modifications de l’authentification du Gateway distant.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transport du Gateway distant`},help:{"v1-1acfs7m-54":`Transport de la connexion distante : "direct" utilise la connectivité de l’URL configurée, tandis que "ssh" établit un tunnel via SSH. Utilisez SSH si vous avez besoin d’un tunnel chiffré sans exposer les ports distants.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL du Gateway distant`},help:{"v1-va7exe-1b":`URL WebSocket du Gateway distant (ws:// ou wss://).`}},"gateway%2ErepositoryIntegration":{label:{"v1-9msrgf-m":`Intégration des dépôts`},help:{"v1-10mbwuf-7d":`Identifiant du plugin requis pour autoriser l’accès des workers au code source des dépôts, notamment via les identifiants natifs, GitHub App et les identifiants OAuth ou PAT gérés. L’accès est refusé si les plugins responsables sont absents, désactivés ou non chargés. Omettez ce paramètre pour utiliser le comportement natif des dépôts ; l’activation d’un plugin ne suffit pas à le sélectionner.`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Rôles d’opérateur du Gateway`},help:{"v1-1h5f6fh-84":`Définitions de rôles d’opérateur nommés pour les Gateways d’équipe. Définir gateway.roles.default active l’application, par profil, des règles d’accès aux sessions, d’isolation des bacs à sable, d’accès aux agents et de périmètre des autorisations des opérateurs. Sans rôle par défaut, les définitions constituent uniquement un catalogue et conservent le comportement d’un Gateway sans gateway.roles.`}},"gateway%2Eroles%2Eassignments":{label:{"v1-hv31t1-p":`Attributions de rôles d’opérateur`},help:{"v1-do2i61-55":`Attributions déclaratives facultatives de rôles aux profils authentifiés. Une attribution explicite valide effectuée avec users.setRole est prioritaire sur ces correspondances, puis le rôle par défaut s’applique.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin":{label:{"v1-wujwr5-u":`Rôles d’opérateur par identifiant GitHub`},help:{"v1-ecgzr1-95":`Nécessite gateway.roles.default, même pour une table de correspondance vide. Associe les identifiants de connexion GitHub mis en cache aux noms de rôles configurés, sans distinction de casse et après suppression des espaces en début et en fin. Les identifiants non valides, les doublons après normalisation et les rôles inconnus sont rejetés. Les profils sans identité GitHub mise en cache utilisent leur attribution explicite ou le rôle par défaut.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin%2E*":{label:{"v1-1wr68uf-q":`Rôle d’opérateur de l’identifiant GitHub`},help:{"v1-dad5ey-5e":`Nom du rôle configuré pour cet identifiant GitHub. S’applique lorsque le profil possède une identité GitHub correspondante en cache et aucune attribution explicite de rôle valide. Les modifications s’appliquent à chaud lorsque le rechargement de la configuration est activé.`}},"gateway%2Eroles%2Edefault":{label:{"v1-12e6yd7-17":`Rôle d’opérateur par défaut (active l’application des règles)`},help:{"v1-18k9r00-7c":`Rôle par défaut facultatif qui active l’application des rôles nommés et s’applique aux profils authentifiés sans attribution valide, explicite ou fondée sur l’identifiant de connexion GitHub. Son nom doit correspondre à une définition configurée. S’il est omis, l’application des rôles nommés reste désactivée, même si des définitions existent.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Définitions des rôles d’opérateur`},help:{"v1-11qtcgr-6w":`Catalogue non vide de rôles nommés par l’administrateur, regroupant les règles de partage des sessions, d’isolation des bacs à sable, d’accès aux agents et de périmètre des autorisations des opérateurs. Les définitions seules n’activent pas l’application des règles ; définissez gateway.roles.default pour appliquer les rôles nommés aux profils authentifiés.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Définition du rôle d’opérateur`},help:{"v1-p8tfws-6q":`Un rôle d’opérateur nommé. Chaque définition doit préciser explicitement sa politique de partage des sessions, les agents autorisés pour les sessions et les exécutions, ainsi que le plafond des autorisations d’opérateur. Elle peut également imposer une isolation en bac à sable pour les nouvelles sessions et une politique d’accès fournie par un plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plugin de politique d’accès du rôle d’opérateur`},help:{"v1-1gq4q08-9n":`Identifiant exact facultatif du plugin dont la politique d’accès au Gateway doit autoriser ce rôle. L’accès est refusé si le plugin est absent, désactivé, ne se charge pas ou ne fournit aucune autorité actuellement valide. Les identifiants de plugins indisponibles restent valides dans la configuration afin que les rôles indépendants du personnel et le propriétaire du Gateway puissent rétablir l’accès. Omettre ce champ n’ajoute aucune dépendance à un plugin.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Agents autorisés pour le rôle d’opérateur`},help:{"v1-fvun18-4v":`Agents disponibles lorsque ce rôle crée des sessions ou démarre des exécutions : définissez "*" pour autoriser tous les agents, indiquez une liste d’identifiants d’agents pour n’autoriser que ceux-ci, ou utilisez une liste vide pour désactiver les deux opérations.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy":{label:{"v1-1b2q6cc-q":`Politique des modèles du rôle d’opérateur`},help:{"v1-r9daa-e8":`Restriction facultative des modèles pour les requêtes de ce rôle et leurs descendantes. Un objet vide autorise uniquement les modèles principaux et de repli configurés pour l’agent source ; l’absence de politique laisse l’accès aux modèles inchangé. Les alias de modèles sont résolus avant l’application de la politique, et les modèles refusés ne peuvent pas être utilisés lors des nouvelles tentatives ou des replis. Lorsque le rechargement de la configuration est activé, les modifications limitées aux politiques de modèles des rôles existants s’appliquent dès leur validation, sans redémarrer les tâches autorisées. Les autres modifications de rôles s’appliquent à chaud et reconnectent les clients avec les autorisations en vigueur.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Eallow":{label:{"v1-zdw95f-s":`Modèles autorisés pour le rôle d’opérateur`},help:{"v1-1dutf3o-8u":`Liste d’autorisation de remplacement facultative contenant des références de modèles, des alias configurés ou des préfixes suivis d’un caractère générique, tels que "provider/*" ou "provider/family-*". Si elle est omise, le modèle principal et les modèles de secours de l’agent source sont utilisés ; une liste vide interdit tous les modèles. Le premier modèle source autorisé reste le modèle par défaut, suivi des modèles explicitement autorisés.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Edeny":{label:{"v1-1hx2vzz-t":`Modèles exclus du rôle opérateur`},help:{"v1-1kx70ze-7o":`Références de modèles, alias de l’agent source ou préfixes suivis d’un caractère générique exclus de ce rôle. Un motif tel que "provider/family-*" exclut également les futurs membres de cette famille. Les exclusions s’appliquent aux identités de modèles résolues et prévalent sur les modèles autorisés et ceux de l’agent source.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2EsourceAgent":{label:{"v1-8bg4yu-w":`Agent source des modèles du rôle opérateur`},help:{"v1-yf7mu-62":`Agent dont le modèle principal, les modèles de secours et les alias de modèles définissent la politique de modèles de ce rôle. Par défaut, il s’agit de l’agent système/par défaut configuré ou de l’unique agent. Définissez-le explicitement lorsqu’un Gateway multi-agent n’a aucun propriétaire implicite.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Isolation dans un bac à sable du rôle d’opérateur`},help:{"v1-11bb0ps-6a":`Isolation de l’exécution pour les sessions nouvellement créées : "inherit" (valeur par défaut) utilise la politique de l’agent ; "required" impose en permanence un bac à sable, même lorsque le mode bac à sable de l’agent est désactivé, et bloque l’exécution si le backend est indisponible.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Limites des portées du rôle d’opérateur`},help:{"v1-1selr2i-4s":`Liste fermée des portées d’opérateur accordées comme autorisations maximales de connexion pour ce rôle. Les portées demandées, appairées, accordées par l’identité et étendues sont limitées à leur intersection avec cette liste.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Accès aux sessions du rôle d’opérateur`},help:{"v1-hsoiop-45":`Autorisations de partage des sessions accordées à ce rôle pour les sessions créées par d’autres personnes authentifiées ; les sessions d’une personne restent accessibles à leur propriétaire.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Accès du rôle d’opérateur aux autres sessions`},help:{"v1-1pmaa4o-al":`Accès aux sessions d’autres personnes : "none" les masque même en cas d’appartenance explicite à la session, "view" autorise la lecture, "suggest" autorise le processus de suggestion et "write" autorise la participation sans appartenance à la session. L’appartenance explicite à une session peut étendre les droits d’accès "view" ou "suggest" pour cette session. Les créateurs de sessions et les connexions disposant de operator.admin conservent leur accès aux sessions.`}},"gateway%2Eroles%2Edefinitions%2E*%2EworkerProfiles":{label:{"v1-o0hlzf-t":`Profils de workers du rôle d’opérateur`},help:{"v1-v6xpap-5r":`Profils de workers cloud vers lesquels ce rôle peut explicitement envoyer ses propres sessions. Si ce paramètre est omis ou vide, l’envoi vers le cloud est interdit ; les administrateurs conservent leur accès. La configuration et les transferts vers des profils cloud restent réservés aux administrateurs.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale du Gateway`},help:{"v1-6ar9o-4x":`Paramètres d’intégration Tailscale pour l’exposition via Serve/Funnel et la gestion du cycle de vie au démarrage et à l’arrêt du Gateway. Laissez cette option désactivée, sauf si votre déploiement utilise délibérément Tailscale pour les connexions entrantes.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Mode Tailscale du Gateway`},help:{"v1-6l2099-5a":`Mode de publication Tailscale : "off", "serve" ou "funnel" pour une exposition privée ou publique. Utilisez "serve" pour un accès limité au tailnet et "funnel" uniquement lorsqu’un accès depuis l’Internet public est nécessaire.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Protection de migration du Funnel externe Tailscale du Gateway`},help:{"v1-1mntkor-7q":`Protection de migration obsolète pour mode='serve'. Si un Funnel externe cible encore le point d’écoute habituel du Gateway, OpenClaw laisse l’exposition inchangée et avertit que seuls les webhooks authentifiés par un plugin restent utilisables tant que l’authentification par mot de passe n’est pas configurée et que le mode n’a pas été migré vers 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Terminal opérateur`},help:{"v1-1qtq5dc-88":`Terminal opérateur accessible aux clients web et mobiles : un shell reposant sur un PTY sur l’hôte de la passerelle, réservé aux sessions opérateur disposant de droits d’administration. Il démarre dans l’espace de travail de l’agent cible et son accès est refusé aux agents entièrement isolés en bac à sable (sandbox.mode 'all'), plutôt que de leur fournir un shell non isolé sur l’hôte.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Délai d’expiration des sessions détachées du terminal opérateur`},help:{"v1-k6qbgr-9e":`Durée en secondes pendant laquelle une session de terminal reste active après la perte de sa connexion (mise en veille de l’ordinateur portable, rechargement de la page). Elle peut être rattachée via terminal.attach, avec restitution de ses sorties récentes. Définissez cette valeur sur 0 pour arrêter les sessions dès la perte de connexion. Valeur par défaut : 300 (5 minutes). Les sessions détachées continuent d’exécuter leurs commandes ; réduisez donc cette durée sur les hôtes partagés ou exposés.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Terminal opérateur activé`},help:{"v1-1nez06v-7p":`Active le terminal opérateur pour les clients disposant d’autorisations d’administration (valeur par défaut : true). Cela donne accès à un shell depuis un navigateur ou un appareil mobile, avec l’environnement du processus Gateway ; définissez la valeur sur false pour le désactiver dans les déploiements où les opérateurs administrateurs ne doivent pas accéder à un shell sur l’hôte. Les modifications s’appliquent sans redémarrer le Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Shell du terminal opérateur`},help:{"v1-19mfe6t-5i":`Exécutable du shell lancé par le terminal opérateur. Laissez ce paramètre non défini pour utiliser le shell de connexion de l’hôte ($SHELL sous Unix, %ComSpec% sous Windows), ou spécifiez un interpréteur pour garantir un environnement opérateur cohérent.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS de Gateway`},help:{"v1-1dx77dq-4z":`Paramètres du certificat et de la clé TLS permettant de terminer les connexions HTTPS directement dans le processus Gateway. Utilisez des certificats explicitement configurés en production et évitez toute exposition en clair sur les réseaux non fiables.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Génération automatique du certificat TLS de Gateway`},help:{"v1-1ld6uiu-4w":`Génère automatiquement une paire certificat/clé TLS locale lorsqu’aucun fichier n’est explicitement configuré. À utiliser uniquement pour les environnements locaux ou de développement ; remplacez-la par de véritables certificats pour le trafic de production.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Chemin du bundle d’autorités de certification TLS du Gateway`},help:{"v1-andqlu-52":`Chemin facultatif du bundle d’autorités de certification pour la vérification des clients ou les exigences de chaîne de confiance personnalisée à la périphérie du Gateway. À utiliser lorsque le déploiement intègre une PKI privée ou des chaînes de certificats personnalisées.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Chemin du certificat TLS du Gateway`},help:{"v1-1wznaof-4q":`Chemin dans le système de fichiers vers le fichier de certificat TLS utilisé par le Gateway lorsque TLS est activé. Utilisez des chemins de certificats gérés et assurez-vous que le renouvellement automatisé utilise cet emplacement.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS du Gateway activé`},help:{"v1-ykhwp0-4o":`Active la terminaison TLS au niveau du point d’écoute du Gateway afin que les clients se connectent directement via HTTPS/WSS. Gardez cette option activée en cas d’exposition directe à Internet ou à la frontière d’un réseau non fiable.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Chemin de la clé TLS du Gateway`},help:{"v1-15knri0-4i":`Chemin dans le système de fichiers vers le fichier de clé privée TLS utilisé par le Gateway lorsque TLS est activé. Limitez les autorisations d’accès à ce fichier et renouvelez la clé conformément à votre politique de sécurité.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Politique d’exposition des outils du Gateway`},help:{"v1-1ffol26-5a":`Politique d’autorisation et de refus d’exposition des outils au niveau du Gateway, permettant de restreindre leur disponibilité à l’exécution indépendamment des profils d’agents ou d’outils. À utiliser pour des contrôles d’urgence globaux et le renforcement de la sécurité en production.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Liste des outils autorisés du Gateway`},help:{"v1-163khb1-4y":`Liste explicite des outils autorisés au niveau du Gateway pour limiter les outils disponibles à l’exécution. À utiliser dans les environnements verrouillés où le périmètre des outils doit être strictement contrôlé.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Liste des outils interdits du Gateway`},help:{"v1-1lhssnf-4o":`Liste explicite d’outils interdits au niveau du Gateway pour bloquer les outils à risque, même si les politiques de niveau inférieur les autorisent. Utilisez des règles de refus pour les interventions d’urgence et le renforcement de la défense en profondeur.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR des proxys de confiance du Gateway`},help:{"v1-n5zcvf-4f":`Liste des CIDR/IP des proxys en amont autorisés à fournir des en-têtes d’identité client transférés. Limitez strictement cette liste pour empêcher les intermédiaires non fiables d’usurper l’identité des utilisateurs.`}},"gateway%2Euploads":{label:{"v1-pn01yp-m":`Téléversements de fichiers et d’images`},help:{"v1-ger7hh-3a":`Politique d’envoi de fichiers et d’images par les clients pour Gateway et l’application web. Les téléchargements et les médias générés par les agents restent disponibles.`}},"gateway%2Euploads%2Eenabled":{label:{"v1-1m4q5zw-f":`Téléversements activés`},help:{"v1-1tqoi1v-93":`Autorise les téléversements de fichiers et d’images par les clients (valeur par défaut : true). Définissez la valeur sur false pour refuser les pièces jointes, les téléversements depuis l’espace de travail ou le terminal, les téléversements d’avatars et les importations d’archives au niveau de Gateway, y compris via des requêtes API directes. Les modifications s’appliquent sans redémarrage. Il ne s’agit ni d’un bac à sable ni d’une restriction concernant les médias des canaux, les outils des agents ou l’accès de l’opérateur au shell.`}},hooks:{label:{"v1-j9ywl7-5":`Points d’accroche`},help:{"v1-1mzh0ry-5v":`Interface d’automatisation par webhooks entrants permettant de convertir les événements externes en actions de réveil ou d’agent dans OpenClaw. Sécurisez-la avec des contrôles explicites des jetons, des sessions et des agents avant de l’exposer au-delà des réseaux de confiance.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Identifiants d’agents autorisés pour les hooks`},help:{"v1-1imjux7-79":`Liste des identifiants d’agents effectifs que les requêtes et les règles de correspondance des hooks sont autorisées à cibler, y compris le routage vers l’agent par défaut lorsque agentId est omis. Utilisez cette liste pour limiter les événements d’automatisation à des agents de service dédiés et réduire les dommages en cas d’exposition d’un jeton de hook.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Préfixes de clés de session autorisés pour les hooks`},help:{"v1-b346oh-4r":`Liste des préfixes de clés de session acceptés pour les requêtes de hooks entrantes lorsque les clés fournies par l’appelant sont activées. Utilisez des préfixes strictement définis pour empêcher l’injection de clés de session arbitraires.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Autoriser une clé de session dans les requêtes de hooks`},help:{"v1-11n9ps-52":`Autorise les appelants à fournir une clé de session dans les requêtes de hooks lorsque la valeur est true, ce qui leur permet de contrôler le routage. Conservez la valeur false, sauf si des intégrateurs de confiance ont explicitement besoin d’un regroupement personnalisé des échanges par session.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Clé de session par défaut des hooks`},help:{"v1-bzdgkn-57":`Clé de session de secours utilisée pour la transmission des hooks lorsqu’une requête n’en fournit pas via les canaux autorisés. Utilisez une clé stable, mais de portée limitée, pour éviter de mélanger des conversations d’automatisation sans rapport entre elles.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hooks activés`},help:{"v1-1mixmjf-4n":`Active le point de terminaison des hooks et le pipeline d’exécution des mappages pour les requêtes webhook entrantes. Laissez cette option désactivée sauf si vous acheminez activement des événements externes vers la passerelle.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Hook Gmail`},help:{"v1-4cibmt-4r":`Paramètres d’intégration des notifications push Gmail utilisés pour les notifications Pub/Sub et la prise en charge facultative des rappels en local. Dans la mesure du possible, limitez cette intégration aux comptes Gmail dédiés à l’automatisation.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Compte du hook Gmail`},help:{"v1-12l1h96-4v":`Identifiant du compte Google utilisé pour les opérations de surveillance et d’abonnement Gmail dans cette intégration de hook. Utilisez un compte de messagerie dédié à l’automatisation pour isoler les autorisations opérationnelles.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Hook Gmail : autoriser le contenu externe non sécurisé`},help:{"v1-1w3gdvs-55":`Lorsque cette option est activée, elle autorise le traitement de contenu Gmail externe ayant subi un filtrage de sécurité moins strict. Laissez-la désactivée pour conserver des paramètres par défaut plus sûrs et ne l’activez que pour des flux de messages fiables avec des transformations contrôlées.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`URL de rappel du hook Gmail`},help:{"v1-19fhn6q-4z":`URL de rappel publique que Gmail ou des intermédiaires appellent pour transmettre des notifications à ce pipeline de hooks. Protégez cette URL par une validation des jetons et une exposition réseau restreinte.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Hook Gmail : inclure le corps du message`},help:{"v1-14cf1c3-52":`Lorsque la valeur est true, récupère et inclut le contenu du corps des e-mails pour le mappage ou le traitement par l’agent en aval. Conservez false sauf si le texte du corps est nécessaire, car cela augmente la taille et la sensibilité des données transmises.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Libellé du hook Gmail`},help:{"v1-9zpdg8-4g":`Filtre facultatif par libellé Gmail limitant les messages étiquetés qui déclenchent des événements de hook. Utilisez des filtres ciblés pour éviter de submerger les automatisations avec des messages sans rapport.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Taille maximale du corps du hook Gmail (octets)`},help:{"v1-2aaxx1-4b":`Nombre maximal d’octets de données Gmail traités par événement lorsque includeBody est activé. Fixez des limites prudentes pour réduire le coût et les risques liés au traitement de messages trop volumineux.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Modèle de remplacement du hook Gmail`},help:{"v1-1var65t-59":`Modèle de remplacement facultatif pour les exécutions déclenchées par Gmail lorsque les automatisations de la boîte aux lettres nécessitent un comportement de modèle dédié. Laissez ce paramètre non défini pour hériter des valeurs par défaut de l’agent, sauf si les tâches de messagerie nécessitent une spécialisation.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Jeton de notification push du hook Gmail`},help:{"v1-h1vx01-4o":`Jeton secret partagé requis lors des rappels du hook de notification push Gmail avant le traitement des notifications. Utilisez la substitution par variable d’environnement et renouvelez le jeton si les points de terminaison de rappel sont exposés à l’extérieur.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Intervalle de renouvellement du hook Gmail (min)`},help:{"v1-pr1z9-49":`Fréquence de renouvellement, en minutes, des abonnements de surveillance Gmail pour éviter leur expiration. Définissez un intervalle inférieur aux délais d’expiration du fournisseur et surveillez les échecs de renouvellement dans les journaux.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Serveur local du hook Gmail`},help:{"v1-hom4wq-54":`Bloc de paramètres du serveur local de rappel permettant de recevoir directement les notifications Gmail sans couche d’entrée distincte. À activer uniquement si ce processus doit lui-même prendre en charge le trafic des webhooks.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Adresse d’écoute du serveur de hooks Gmail`},help:{"v1-55bieu-4d":`Adresse d’écoute du serveur HTTP local de rappel Gmail utilisé pour gérer directement les hooks. Limitez l’écoute à l’interface de bouclage, sauf si un accès entrant externe est explicitement requis.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Chemin du serveur de hooks Gmail`},help:{"v1-1jqhcw4-4h":`Chemin HTTP du serveur local de rappel Gmail sur lequel les notifications push sont acceptées. Veillez à ce qu’il corresponde à la configuration de l’abonnement pour éviter la perte d’événements.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Port du serveur de hooks Gmail`},help:{"v1-1yku7dz-43":`Port du serveur HTTP local de rappel Gmail lorsque le mode serveur est activé. Utilisez un port dédié pour éviter les conflits avec les interfaces de passerelle ou de contrôle.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Abonnement aux hooks Gmail`},help:{"v1-127h8vg-5b":`Abonnement Pub/Sub utilisé par la passerelle pour recevoir les notifications de modification Gmail provenant du topic configuré. Définissez clairement quel consommateur est responsable de l’abonnement afin d’éviter toute concurrence imprévue entre plusieurs consommateurs.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale pour les hooks Gmail`},help:{"v1-7jzidp-4l":`Bloc de configuration de l’exposition via Tailscale permettant de publier les points de rappel Gmail au moyen de routes Serve/Funnel. Privilégiez les modes de tailnet privés avant d’activer un chemin d’accès entrant public.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Mode Tailscale des hooks Gmail`},help:{"v1-vhm395-4u":`Mode d’exposition Tailscale pour les rappels Gmail : "off", "serve" ou "funnel". Utilisez "serve" pour une transmission privée via le tailnet et "funnel" uniquement lorsqu’un accès entrant depuis l’Internet public est nécessaire.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Chemin Tailscale du hook Gmail`},help:{"v1-fr8qi-4m":`Chemin publié par Tailscale Serve/Funnel pour transférer les rappels Gmail lorsque cette fonctionnalité est activée. Veillez à ce qu’il corresponde à la configuration du webhook Gmail afin que les requêtes parviennent au gestionnaire attendu.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Cible Tailscale du hook Gmail`},help:{"v1-1twwxge-47":`Service local cible vers lequel Tailscale Serve/Funnel transfère les requêtes (par exemple http://127.0.0.1:8787). Utilisez des cibles de bouclage explicites pour éviter toute ambiguïté de routage.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Remplacement du niveau de réflexion du hook Gmail`},help:{"v1-17owk9q-4z":`Remplacement du niveau d’effort de réflexion pour les exécutions de l’agent déclenchées par Gmail : "off", "minimal", "low", "medium" ou "high". Conservez des valeurs par défaut modérées pour les automatisations courantes de la boîte de réception afin de maîtriser les coûts et la latence.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Sujet Pub/Sub du hook Gmail`},help:{"v1-fdm0kn-4t":`Nom du sujet Google Pub/Sub utilisé par la surveillance Gmail pour publier les notifications de modification de ce compte. Vérifiez que les autorisations IAM du sujet accordent à Gmail le droit de publier avant d’activer la surveillance.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Hooks internes`},help:{"v1-piq9k-4v":`Paramètres d’exécution des hooks internes pour les gestionnaires d’événements intégrés ou personnalisés chargés depuis des chemins de modules. Utilisez-les pour des automatisations de confiance exécutées dans le même processus et limitez strictement la portée du chargement des gestionnaires.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Hooks internes activés`},help:{"v1-1wv0289-4c":`Active le traitement des hooks internes et des entrées configurées dans leur environnement d’exécution. Laissez cette option désactivée sauf si des hooks internes sont délibérément configurés.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Entrées des hooks internes`},help:{"v1-1ovi38l-4o":`Entrées de hooks internes configurées servant à enregistrer des gestionnaires d’exécution concrets et des métadonnées. Gardez les entrées explicites et versionnées afin que le comportement en production puisse être audité.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Chargeur de hooks internes`},help:{"v1-11re5ph-4p":`Paramètres du chargeur de hooks internes définissant où les modules de gestionnaires sont recherchés au démarrage. Limitez les répertoires racines de chargement pour réduire les risques de conflits entre modules ou de masquage accidentel.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Répertoires supplémentaires des hooks internes`},help:{"v1-1xfdqxg-4c":`Répertoires supplémentaires dans lesquels rechercher les modules de hooks internes, en plus des chemins de chargement par défaut. Limitez cette liste au strict nécessaire et contrôlez-la pour réduire le risque qu’un module en masque accidentellement un autre.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Règles de correspondance des hooks`},help:{"v1-frhp3v-5i":`Règles de correspondance ordonnées qui identifient les requêtes de hook entrantes et choisissent des actions de réveil ou d’agent, avec un routage de livraison facultatif. Placez les règles spécifiques en premier pour éviter que des motifs trop larges ne capturent tout.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Action de la règle de correspondance du hook`},help:{"v1-i2kbzp-4h":`Type d’action du mappage : "wake" met une notification en file d’attente pour la session propriétaire, tandis que "agent" démarre un tour d’agent indépendant. Les notifications de session n’interrompent pas le travail en cours.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`Identifiant de l’agent de la règle de correspondance du hook`},help:{"v1-l0uioz-4y":`Identifiant de l’agent cible pour l’exécution de la règle de correspondance lorsque le routage des actions ne doit pas utiliser les valeurs par défaut. Utilisez des agents d’automatisation dédiés pour isoler le comportement des webhooks des sessions interactives des opérateurs.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Autoriser le contenu externe non sécurisé dans la règle de correspondance du hook`},help:{"v1-1np9426-57":`Si la valeur est true, le contenu de la règle de correspondance peut inclure des données de charge utile externes moins assainies dans les messages générés. Conservez false par défaut et n’activez cette option que pour les sources de confiance dont la logique de transformation a été vérifiée.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Canal de diffusion de la règle de correspondance du hook`},help:{"v1-oz7pu5-5s":`Remplacement du canal de diffusion pour les sorties de la règle de correspondance (par exemple "last", "telegram", "discord", "slack", "signal", "imessage" ou "msteams"). Définissez explicitement les remplacements de canal pour éviter les envois accidentels vers d’autres canaux.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Diffuser la réponse de la règle de correspondance du hook`},help:{"v1-12tbbam-5o":`Détermine si les résultats de l’exécution de la règle de correspondance sont envoyés à une destination sur un canal ou traités silencieusement. Désactivez la diffusion pour les automatisations en arrière-plan qui ne doivent pas publier de contenu visible par les utilisateurs.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Clé de répartition de la règle de correspondance du hook`},help:{"v1-1d593op-7e":`Clé du tableau de premier niveau de la charge utile sur lequel la règle de correspondance répartit les actions : chaque élément déclenche sa propre action, et les modèles ou transformations reçoivent une charge utile dont le tableau ne contient que l’élément courant. Le préréglage Gmail utilise forEach: messages afin que les envois groupés déclenchent une exécution par e-mail.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`Identifiant de la règle de correspondance du hook`},help:{"v1-q1t4zw-57":`Identifiant stable facultatif d’une entrée de mappage de hook, utilisé pour l’audit, le dépannage et les mises à jour ciblées. Utilisez des identifiants uniques pour que les journaux et les différences de configuration puissent référencer les mappages sans ambiguïté.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Critères de correspondance du mappage de hook`},help:{"v1-6u73k2-5a":`Objet regroupant les critères de correspondance du mappage, tels que le chemin et la source, avant l’application du routage des actions. Définissez des critères précis pour éviter que du trafic webhook sans rapport ne déclenche des automatisations.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Chemin de correspondance du mappage de hook`},help:{"v1-1d7dc5j-4k":`Condition de correspondance de chemin pour un mappage de hook, généralement comparée au chemin de la requête entrante. Utilisez-la pour différencier le comportement des automatisations selon les familles de chemins des points de terminaison webhook.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Source de correspondance du mappage de hook`},help:{"v1-1nw7um7-4v":`Condition de correspondance de la source pour une règle de hook, généralement définie par des métadonnées fiables en amont ou par la logique de l’adaptateur. Utilisez des identifiants de source stables pour que le routage reste identique lors des nouvelles tentatives.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Modèle de message du mappage de hook`},help:{"v1-m0lqv5-5t":`Modèle permettant de convertir les données d’entrée structurées d’une règle de correspondance en contenu final du message envoyé au chemin de l’action cible. Veillez à ce que les mêmes données d’entrée produisent le même message afin que l’analyse et le comportement en aval restent stables.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Remplacement du modèle pour le mappage de hook`},help:{"v1-10qyo4j-5e":`Remplacement facultatif du modèle pour les exécutions déclenchées par une règle de correspondance lorsque l’automatisation doit utiliser un modèle différent de celui défini par défaut pour l’agent. Utilisez cette option avec parcimonie afin que le comportement reste prévisible d’une exécution à l’autre.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Nom de la règle de correspondance du hook`},help:{"v1-zrd9tn-4v":`Nom d’affichage lisible de la règle de correspondance, utilisé dans les diagnostics et les interfaces de configuration destinées aux opérateurs. Choisissez des noms concis et descriptifs afin que l’objectif du routage soit évident lors de l’analyse des incidents.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Clé de session de la règle de correspondance du hook`},help:{"v1-lfnt1n-58":`Remplacement explicite de la clé de session pour les messages transmis par une règle de correspondance, afin de contrôler la continuité du fil de discussion. Utilisez des clés stables à portée limitée pour regrouper les événements répétés sans déborder sur des conversations sans rapport.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Mode de session de la règle de correspondance du hook`},help:{"v1-1ggtdze-5k":`Contrôle la continuité de la session de la règle de correspondance : "isolated" démarre une nouvelle session d’exécution, tandis que "persistent" réutilise la clé sessionKey résolue. Conservez le mode "isolated", sauf si l’intégration nécessite délibérément un contexte durable.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Modèle de texte de la règle de correspondance du hook`},help:{"v1-1rg732b-4y":`Modèle de repli en texte seul, utilisé lorsque le rendu enrichi des données n’est pas souhaité ou n’est pas pris en charge. Utilisez-le pour fournir un résumé concis et cohérent destiné aux interfaces de messagerie.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Remplacement du paramètre de réflexion de la règle de correspondance du hook`},help:{"v1-17hq8me-57":`Remplacement facultatif du niveau d’effort de réflexion pour les exécutions déclenchées par une règle de correspondance, afin d’ajuster le compromis entre latence et profondeur de raisonnement. Privilégiez un niveau faible ou minimal pour les hooks à fort volume, sauf si un raisonnement plus approfondi est clairement nécessaire.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Délai d’expiration de la règle de correspondance du hook (s)`},help:{"v1-1r44ox2-4i":`Durée maximale autorisée pour l’exécution de l’action de la règle de correspondance avant l’application du traitement d’expiration. Utilisez des limites plus strictes pour les sources de webhooks à fort volume afin d’éviter l’accumulation dans la file d’attente.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Destination d’envoi de la règle de correspondance du hook`},help:{"v1-1p7928e-55":`Identifiant de destination dans le canal sélectionné lorsque les réponses de la règle de correspondance doivent être acheminées vers une cible fixe. Vérifiez les formats de destination propres au fournisseur avant d’activer les règles de correspondance en production.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformation de la règle de correspondance du hook`},help:{"v1-118nw83-5j":`Bloc de configuration de transformation définissant le prétraitement par module/export avant le traitement de l’action de correspondance. Utilisez uniquement des transformations issues de chemins de code vérifiés et maintenez un comportement reproductible pour garantir une automatisation reproductible.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Export de transformation du hook`},help:{"v1-atn8v-4b":`Export nommé à appeler depuis le module de transformation ; si ce champ est omis, l’export par défaut du module est utilisé. Renseignez ce champ lorsqu’un fichier contient plusieurs gestionnaires de transformation.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Module de transformation du hook`},help:{"v1-56futq-4v":`Chemin relatif du module de transformation chargé depuis hooks.transformsDir pour réécrire les charges utiles entrantes avant leur transmission. Utilisez des modules locaux, vérifiés et exempts de motifs de traversée de répertoires.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Mode de réveil de la règle de hook`},help:{"v1-1vp6cpn-6m":`Mode de planification du réveil : "now" met immédiatement un tour de session en file d’attente, tandis que "next-heartbeat" affecte la notification à la prochaine automatisation planifiée admissible pour cette session. Les réveils différés nécessitent une automatisation activée capable de recevoir la notification.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Chemin du point de terminaison des hooks`},help:{"v1-1l9ijzv-4u":"Chemin HTTP utilisé par le point de terminaison des hooks (par exemple `/hooks`) sur le serveur de contrôle de la Gateway. Utilisez un chemin difficile à deviner et associez-le à une validation par jeton pour une défense en profondeur."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Préréglages des hooks`},help:{"v1-dp8m0l-4v":`Ensembles nommés de préréglages de hooks appliqués au chargement pour initialiser les règles standard et les comportements par défaut. Utilisez les préréglages de manière explicite afin que les opérateurs puissent vérifier quelles automatisations sont actives.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Jeton d’authentification des hooks`},help:{"v1-1ihf6mv-82":`Jeton porteur partagé vérifié à l’entrée des hooks pour authentifier les requêtes avant l’exécution des règles. Considérez ses détenteurs comme des appelants de pleine confiance pour l’interface d’entrée des hooks, et non comme un rôle distinct de non-propriétaire. Utilisez la substitution par variables d’environnement et renouvelez régulièrement le jeton lorsque les points de terminaison des webhooks sont accessibles depuis Internet.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Répertoire des transformations des hooks`},help:{"v1-1ayj9p0-4t":`Répertoire de base des modules de transformation des hooks référencés par les chemins transform.module des règles. Utilisez un répertoire de dépôt contrôlé pour que les importations dynamiques restent vérifiables et prévisibles.`}},logging:{label:{"v1-rq08xq-7":`Journalisation`},help:{"v1-11an9pb-5e":`Paramètres de journalisation pour la gravité, les destinations de sortie, le formatage et le masquage des données sensibles. Maintenez des niveaux et un masquage suffisamment stricts pour la production tout en conservant des diagnostics utiles.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Registre d’audit`},help:{"v1-1lauvy2-6w":`Historique d’audit limité aux métadonnées, de taille limitée, destiné à la consultation par les opérateurs. Les enregistrements des exécutions et des outils sont activés par défaut ; les métadonnées du cycle de vie des messages nécessitent une activation distincte, sensible du point de vue de la confidentialité. L’écriture en arrière-plan est assurée au mieux, sans constituer une archive de conformité garantie sans perte.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Registre d’audit activé`},help:{"v1-snknxb-4v":`Enregistre les nouveaux événements d’audit liés aux exécutions, aux outils et aux messages pour lesquels l’audit est activé. Valeur par défaut : true. Les modifications s’appliquent immédiatement ; les écritures acceptées se terminent et les lignes conservées restent consultables jusqu’à leur expiration.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Audit de l’identité d’exécution`},help:{"v1-1ucirwv-5b":`Conserve des données d’attribution limitées sur l’identité d’exécution pour l’inspection d’une exécution précise. Valeur par défaut : false. Nécessite logging.audit.enabled et s’applique aux exécutions nouvellement admises ; les contextes existants restent inchangés.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Périmètre d’audit des messages`},help:{"v1-1yg4lc3-76":`Contrôle les enregistrements du cycle de vie des messages, sans leur contenu : "off" (par défaut), "direct" pour les conversations directes connues uniquement, ou "all" pour les conversations directes, de groupe, de canal et de type inconnu. Nécessite logging.audit.enabled. Les modifications s’appliquent aux événements ultérieurs du cycle de vie.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Niveau de journalisation de la console`},help:{"v1-16badbd-5u":`Seuil de journalisation propre à la console : "silent", "fatal", "error", "warn", "info", "debug" ou "trace" pour contrôler la sortie du terminal. Utilisez ce paramètre pour limiter les messages dans la console locale tout en conservant, si nécessaire, une journalisation plus détaillée dans les fichiers.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Style des journaux de la console`},help:{"v1-d7u0iq-3q":`Format de sortie de la console : "pretty" ou "json". Utilisez json pour les pipelines d’analyse automatique et pretty pour une utilisation du terminal privilégiant la lisibilité.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Chemin du fichier journal`},help:{"v1-16gaitv-4w":`Chemin facultatif du fichier où enregistrer les journaux, en complément ou en remplacement de la journalisation dans la console. Utilisez un chemin géré accessible en écriture et adaptez la conservation et la rotation à votre politique d’exploitation.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Niveau de journalisation`},help:{"v1-1r5yku0-5o":`Seuil principal de journalisation à l’exécution : "silent", "fatal", "error", "warn", "info", "debug" ou "trace". Conservez "info" ou "warn" en production et utilisez debug/trace uniquement lors des investigations.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Motifs de masquage personnalisés`},help:{"v1-11x24rh-8c":`Les chaînes d’expressions régulières personnalisées remplacent la liste de chaînes par défaut pour les journaux et les diagnostics. Les protections intégrées pour les corps de formulaire, les données d’authentification structurées et les clés AWS brutes restent toujours actives. Les arguments des outils, les résultats et l’historique des conversations ne sont pas masqués. Utilisez ce paramètre pour masquer les jetons et identifiants propres au déploiement dans les sorties de diagnostic.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Définitions globales des serveurs MCP gérées par OpenClaw. OpenClaw intégré et les autres adaptateurs d’exécution peuvent utiliser ces serveurs sans les stocker dans les paramètres de projet propres à l’environnement d’exécution.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`Applications MCP`},help:{"v1-amyd91-38":`Prise en charge de l’interface MCP Apps. Lorsque cette option est activée, les serveurs MCP configurés peuvent fournir des vues HTML interactives pour les résultats de leurs outils.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps activé`},help:{"v1-ghqy98-3w":`Activation facultative du rendu MCP Apps et de la passerelle entre applications et serveurs. Laissez cette option désactivée sauf si vous faites confiance aux serveurs MCP configurés qui fournissent les ressources d’interface des applications.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Origine du bac à sable MCP Apps`},help:{"v1-5lqj7v-6s":`Origine HTTP(S) publique dédiée facultative pour MCP Apps. Utilisez-la derrière un proxy inverse ou un terminateur TLS et redirigez son trafic uniquement vers le port configuré du bac à sable MCP Apps. Elle doit être différente de l’origine de l’application web et ne doit pas servir de contenu nécessitant une authentification.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Port du bac à sable MCP Apps`},help:{"v1-1b8n71l-4p":`Port d’écoute dédié au bac à sable MCP Apps. Par défaut, il correspond au port de Gateway plus un. Définissez un port inutilisé si un autre service local ou un profil Gateway utilise déjà ce port.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`Serveurs MCP`},help:{"v1-157ozoz-42":`Définitions nommées des serveurs MCP. OpenClaw les stocke dans sa propre configuration et les adaptateurs d’exécution déterminent les transports pris en charge au moment de l’exécution.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Authentification du serveur MCP`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Certificat client MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Clé client MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Certificat client MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Clé client MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Projection MCP de Codex`},help:{"v1-slcmq1-6x":`Métadonnées de projection OpenClaw réservées aux fils de discussion Codex app-server. Elles n’affectent ni les sessions ACP ni la configuration générique du harnais Codex. Omettez ce bloc pour que le serveur reste accessible à tous les agents Codex app-server avec le comportement d’approbation MCP par défaut de Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Agents MCP de Codex`},help:{"v1-1i6v0fm-6a":`Identifiants facultatifs et non vides des agents OpenClaw qui doivent recevoir ce serveur MCP dans la configuration des fils de discussion de Codex app-server. Les listes ne contenant aucun identifiant d’agent valide n’accordent aucun accès ; si cette option est omise, le serveur est mis à disposition de tous les agents Codex app-server.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Approbation des outils MCP de Codex`},help:{"v1-1xql0qr-3d":`Nom natif de Codex pour le même mode d’approbation des outils MCP par serveur. Préférez defaultToolsApprovalMode dans la configuration OpenClaw.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Approbation des outils MCP de Codex`},help:{"v1-y5vsqq-3s":`Mode facultatif d’approbation des outils MCP de Codex pour ce serveur : "auto", "prompt" ou "approve". À utiliser uniquement pour les serveurs MCP auxquels vous faites délibérément confiance.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Délai d’expiration de la connexion MCP (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Serveur MCP activé`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Profil d’authentification OAuth MCP`},help:{"v1-fcrb4u-5z":`Identifiant du profil d’authentification prenant en charge le renouvellement, utilisé pour injecter le jeton Bearer actuel dans ce serveur MCP distant. Lorsque ce champ est défini, OpenClaw résout et renouvelle le profil à l’exécution sans transmettre les données de renouvellement en aval.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL des métadonnées du client OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Identité OAuth MCP`},help:{"v1-1ie6ys7-59":`Titulaire des identifiants OAuth pour ce serveur. Omettez ce champ ou utilisez "shared" pour des identifiants gérés par l’opérateur ; utilisez "per-requester" pour permettre à chaque expéditeur authentifié de connecter son propre compte.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`URL de redirection OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Portée OAuth MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Délai d’expiration des requêtes MCP (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Vérification TLS MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Vérification TLS MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Appels parallèles d’outils MCP`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Appels parallèles d’outils MCP`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Sélection des outils MCP`},help:{"v1-10poyzb-4v":`Sélection des outils MCP par serveur. Utilisez include pour exposer uniquement les outils MCP dont les noms sont sélectionnés, ou exclude pour les masquer. Les entrées acceptent les noms exacts et les motifs simples avec le caractère générique '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Outils MCP exclus`},help:{"v1-ijrc5y-1u":`Noms exacts des outils MCP ou motifs simples avec '*' à masquer pour ce serveur.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Outils MCP inclus`},help:{"v1-89fdfq-3o":`Noms exacts des outils MCP ou motifs simples avec '*' à exposer pour ce serveur. Si ce paramètre est omis, tous les outils du serveur restent admissibles, sauf ceux explicitement exclus.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL d’inactivité des sessions MCP (ms)`},help:{"v1-j9si74-87":`Délai facultatif d’éviction pour inactivité des environnements d’exécution MCP des sessions OpenClaw, en millisecondes. Une valeur non définie ou égale à 0 les maintient actifs jusqu’au nettoyage de la session ou à l’arrêt de Gateway. Les valeurs positives sont arrondies à l’entier inférieur ; les baux actifs et les acquisitions en attente empêchent l’éviction. Les environnements rattachés à une exécution ponctuelle sont toutefois arrêtés à la fin de celle-ci.`}},memory:{label:{"v1-oopaku-6":`Mémoire`},help:{"v1-1wlx40m-13":`Configuration de la mémoire intégrée (globale).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Mode des citations de la mémoire`},help:{"v1-1q6dxr5-4u":`Contrôle la visibilité des citations dans les réponses : "auto" les affiche lorsqu’elles sont utiles, "on" les affiche toujours et "off" les masque. Conservez "auto" pour un bon équilibre par défaut entre informations utiles et bruit.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Recherche dans la mémoire`},help:{"v1-1ukbud1-25":`Recherche vectorielle dans MEMORY.md et memory/*.md (personnalisation par agent prise en charge).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Cache des représentations vectorielles pour la recherche dans la mémoire`},help:{"v1-d8h2e4-5b":`Met en cache dans SQLite les représentations vectorielles calculées pour les fragments afin d’accélérer la réindexation et les mises à jour incrémentales (par défaut : true). Gardez cette option activée, sauf pour vérifier l’exactitude du cache ou réduire l’utilisation du disque.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Type d’entrée des documents pour la recherche dans la mémoire`},help:{"v1-1ui33sv-5f":"Valeur `input_type` facultative propre au fournisseur pour les plongements vectoriels des documents et de l’indexation de la mémoire. Utilisez-la avec les points de terminaison de plongement vectoriel asymétrique compatibles avec OpenAI qui exigent une étiquette de passage ou de document."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Activer la recherche en mémoire`},help:{"v1-14f11b9-4t":`Interrupteur principal de l’indexation et de la récupération pour la recherche en mémoire sur ce profil d’agent. Laissez-le activé pour le rappel sémantique et désactivez-le pour obtenir des réponses entièrement sans état.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Index des sessions pour la recherche en mémoire (expérimental)`},help:{"v1-1y8ykw2-3b":`Indexe l’historique des conversations pour la recherche en mémoire. Conservez ce paramètre de remplacement avancé lorsque l’héritage des paramètres de rappel diffère entre la racine et les agents.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Chemins de mémoire supplémentaires`},help:{"v1-ojqokq-7i":`Ajoute des répertoires ou des fichiers .md supplémentaires à l’index de mémoire, en plus des fichiers de mémoire par défaut. Les entrées peuvent être des chaînes de chemin ou des objets contenant un motif glob relatif à la racine. Lorsque la mémoire multimodale est activée, les fichiers image et audio correspondants situés dans ces chemins peuvent également être indexés.`}},"memory%2Esearch%2EextraPaths%2E*%2Eevergreen":{label:{"v1-1pdtd1w-r":`Chemin de mémoire supplémentaire sans vieillissement`},help:{"v1-5y3z66-5f":`Exclut les fichiers de référence correspondants des chemins supplémentaires de la dépréciation temporelle fondée sur la date de modification du système de fichiers. Cela modifie uniquement le classement par récence ; cela ne rend pas le contenu fiable, ne le met pas en avant et ne modifie pas sa provenance.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Chemin de mémoire supplémentaire`},help:{"v1-b9mbq8-3m":`Définit le répertoire ou le fichier de mémoire supplémentaire. Les chemins relatifs sont résolus à partir de l’espace de travail de l’agent ; les fichiers indiqués directement sont indexés tels quels.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Motif du chemin de mémoire supplémentaire`},help:{"v1-j8br1v-4e":`Limite une entrée de répertoire aux fichiers pris en charge correspondant à ce motif glob relatif à la racine, par exemple "runbooks/**/*.md". Omettez-le pour parcourir récursivement tous les fichiers pris en charge.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Solution de secours pour la recherche en mémoire`},help:{"v1-1r6368w-6p":`Fournisseur de secours utilisé lorsque la génération des plongements par le fournisseur principal échoue : "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" ou "none". Configurez une véritable solution de secours pour garantir la fiabilité en production ; utilisez "none" uniquement si vous préférez des échecs explicites.`}},"memory%2Esearch%2EinputFormat":{label:{"v1-1qisc0t-q":`Format d’entrée de la recherche en mémoire`},help:{"v1-xus8vr-b2":`Paire facultative de préfixes textuels littéraux pour les plongements vectoriels des requêtes et des documents, par exemple { query: "query: ", document: "passage: " }. Remplace la mise en forme automatique du modèle, y compris pour les alias de modèles. Les deux chaînes sont requises ; les espaces et les sauts de ligne sont conservés, et les chaînes vides sélectionnent le texte brut. Une valeur queryInstruction non vide est prioritaire pour les requêtes. Toute modification du préfixe des documents nécessite une réindexation.`}},"memory%2Esearch%2EinputFormat%2Edocument":{label:{"v1-ml4fv9-t":`Préfixe des documents pour la recherche en mémoire`},help:{"v1-m9hsjw-4q":`Préfixe littéral pour les plongements vectoriels des documents. Une chaîne vide sélectionne le texte brut des documents. Toute modification de ce préfixe modifie l’identité de l’index et du cache des plongements vectoriels et nécessite une réindexation.`}},"memory%2Esearch%2EinputFormat%2Equery":{label:{"v1-16lu8lu-q":`Préfixe des requêtes pour la recherche en mémoire`},help:{"v1-hxaub1-3u":`Préfixe littéral pour les plongements vectoriels des requêtes. Utilisé sauf si une valeur queryInstruction non vide est définie ; une chaîne vide désactive la mise en forme automatique des requêtes.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Type d’entrée pour la recherche en mémoire`},help:{"v1-26vbwe-5u":"Utilisez cette valeur facultative `input_type`, propre au fournisseur, uniquement lorsque la même étiquette doit s’appliquer aux demandes de plongements des requêtes et des documents. Pour les fournisseurs asymétriques, privilégiez queryInputType et documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Chemin du modèle local de plongement`},help:{"v1-13ymbnt-5q":"Spécifie la source du modèle local de plongement pour la recherche locale en mémoire, par exemple un chemin de fichier GGUF ou un URI `hf:`. Utilisez ce paramètre uniquement lorsque provider vaut `local`, et vérifiez la compatibilité du modèle avant toute reconstruction d’index volumineux."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Modèle de recherche en mémoire`},help:{"v1-11pohrl-59":`Modèle de plongement utilisé à la place du modèle par défaut par le fournisseur de mémoire sélectionné, lorsqu’un autre modèle est nécessaire. Définissez ce paramètre uniquement si vous devez ajuster explicitement la qualité du rappel ou le coût au-delà des réglages par défaut du fournisseur.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Recherche multimodale en mémoire`},help:{"v1-1jn02s-9e":'Paramètres facultatifs de mémoire multimodale pour indexer les fichiers image et audio situés dans les chemins supplémentaires configurés. Laissez cette option désactivée, sauf si votre modèle de plongement prend explicitement en charge les plongements intermodaux, et définissez `memory.search.fallback` sur "none" lorsqu’elle est activée. Les fichiers correspondants sont téléversés vers le fournisseur distant de plongements configuré lors de l’indexation.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Activer la recherche multimodale en mémoire`},help:{"v1-1dk5d7o-7e":`Active l’indexation en mémoire des images et des fichiers audio provenant de extraPaths. Cette fonctionnalité nécessite actuellement Gemini embedding-2, limite les répertoires racines de mémoire par défaut aux fichiers Markdown, désactive les fournisseurs de repli pour la recherche en mémoire et téléverse le contenu binaire correspondant vers le fournisseur distant d’embeddings configuré.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Taille maximale des fichiers multimodaux pour la recherche en mémoire, en octets`},help:{"v1-1mmdrvk-5d":`Définit la taille maximale autorisée en octets par fichier multimodal, au-delà de laquelle le fichier est ignoré lors de l’indexation en mémoire. Utilisez ce paramètre pour limiter le coût des téléversements et la latence de l’indexation, ou augmentez-le pour de courts extraits audio de haute qualité.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modalités multimodales de la recherche en mémoire`},help:{"v1-alp4vh-4l":`Sélectionne les types de fichiers multimodaux à indexer depuis extraPaths : "image", "audio" ou "all". Limitez cette sélection pour éviter d’indexer involontairement de vastes corpus binaires.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Nombre de dimensions en sortie pour la recherche en mémoire`},help:{"v1-jx51wj-dm":"Remplacement de la taille des vecteurs de sortie propre au fournisseur pour les plongements vectoriels de mémoire. Les modèles Gemini prennent en charge de 128 à 3072 dimensions et recommandent 768, 1536 ou 3072 ; les familles Bedrock telles que Titan V2, Cohere V4 et Nova proposent leurs propres tailles autorisées. Les points de terminaison compatibles avec OpenAI reçoivent cette valeur via `dimensions` et doivent renvoyer des vecteurs ayant exactement cette taille. Les plongements vectoriels GGUF locaux gérés sont tronqués et normalisés localement. Prévoyez une réindexation complète lorsque vous modifiez cette valeur, car les dimensions des vecteurs stockés doivent rester cohérentes."}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Fournisseur de recherche en mémoire`},help:{"v1-5evseb-71":`Sélectionne le backend de vectorisation utilisé pour créer et interroger les vecteurs de mémoire. La valeur par défaut est "openai" ; choisissez "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" ou "local" pour utiliser un autre backend.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Nombre maximal de résultats de recherche en mémoire`},help:{"v1-13ekath-4x":`Nombre maximal de résultats de recherche en mémoire renvoyés avant leur reclassement et leur insertion dans le prompt. Augmentez cette valeur pour récupérer davantage de contexte, ou réduisez-la pour des prompts plus ciblés et des réponses plus rapides.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Score minimal de recherche en mémoire`},help:{"v1-1ww231l-4v":`Seuil minimal de pertinence requis pour inclure les résultats de mémoire dans le contexte final récupéré. Augmentez-le pour réduire les correspondances faibles ou parasites, ou abaissez-le pour une récupération plus permissive.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Type d’entrée des requêtes de recherche en mémoire`},help:{"v1-831yrv-4q":"Valeur `input_type` facultative, propre au fournisseur, pour la vectorisation des requêtes de recherche en mémoire. À utiliser avec les points de terminaison de vectorisation asymétrique compatibles avec OpenAI qui nécessitent une étiquette de requête."}},"memory%2Esearch%2EqueryInstruction":{label:{"v1-izdliq-v":`Instruction de requête pour la recherche en mémoire`},help:{"v1-19u8npy-b1":`Préfixe littéral facultatif pour les plongements vectoriels des requêtes, par exemple "search_query: ". Incluez les espaces ou sauts de ligne nécessaires. Les valeurs non vides remplacent inputFormat.query et la mise en forme automatique des requêtes ; les valeurs non définies ou vides utilisent inputFormat.query si ce paramètre est défini, sinon les valeurs par défaut du fournisseur. Les documents et l’identité de l’index restent inchangés ; aucune réindexation n’est donc nécessaire. Une valeur de remplacement vide définie pour un agent efface l’instruction héritée.`}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Mémoriser d’une conversation à l’autre`},help:{"v1-1r9xto0-7s":`Utilise le contexte pertinent des autres conversations privées de cet agent grâce au rappel protégé des conversations. Activé par défaut uniquement lorsque le paramètre global session.dmScope n’est pas défini ou vaut "main" et qu’aucune liaison ne remplace la portée des messages privés ; toute isolation configurée des messages privés le désactive par défaut. Une valeur explicite true ou false est toujours prioritaire.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Clé API de vectorisation à distance`},help:{"v1-nfuuu-62":`Fournit une clé API dédiée aux appels distants de vectorisation utilisés pour l’indexation de la mémoire et la vectorisation des requêtes. Utilisez cette option si la vectorisation de la mémoire doit utiliser des identifiants différents de ceux définis par défaut au niveau global ou dans les variables d’environnement.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`URL de base de la vectorisation distante`},help:{"v1-1ugvqgt-5p":`Remplace le point de terminaison de l’API de vectorisation, par exemple par un proxy compatible avec OpenAI ou une URL de base Gemini personnalisée. Utilisez cette option uniquement pour acheminer les requêtes via votre propre passerelle ou un point de terminaison du fournisseur ; sinon, conservez les paramètres par défaut du fournisseur.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Vectorisation distante par lots activée`},help:{"v1-1fehqi-5x":`Active les API de traitement par lots des fournisseurs pour les tâches de vectorisation lorsqu’elles sont prises en charge (OpenAI/Gemini), ce qui améliore le débit lors des indexations volumineuses. Laissez cette option activée, sauf pour déboguer des échecs de traitement par lots du fournisseur ou exécuter de très faibles charges de travail.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`En-têtes de vectorisation distante`},help:{"v1-1uic0kd-5i":`Ajoute des en-têtes HTTP personnalisés aux requêtes de vectorisation distante, en les fusionnant avec les en-têtes par défaut du fournisseur. Utilisez cette option pour les en-têtes d’authentification auprès du proxy et de routage par locataire, et limitez les valeurs au strict nécessaire pour éviter toute fuite de métadonnées sensibles.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Sources de recherche en mémoire`},help:{"v1-1xxndig-4q":`Détermine les sources à indexer : "memory" lit MEMORY.md et les fichiers de mémoire, tandis que "sessions" inclut l’historique des conversations. Conservez ["memory"] sauf si vous avez besoin de rappeler le contexte de conversations précédentes.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Index vectoriel de recherche en mémoire`},help:{"v1-fbybkj-37":`Contrôle l’index sémantique sqlite-vec. Conservez ce paramètre de remplacement avancé lorsque les politiques vectorielles à la racine et par agent diffèrent.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Chemin de l’extension vectorielle de recherche en mémoire`},help:{"v1-1hysv5q-58":"Remplace le chemin détecté automatiquement vers la bibliothèque d’extension sqlite-vec (`.dylib`, `.so` ou `.dll`). Utilisez ce paramètre lorsque votre environnement d’exécution ne trouve pas sqlite-vec automatiquement ou lorsque vous imposez une version dont le bon fonctionnement est avéré."}},messages:{label:{"v1-1wwzqad-8":`Messages`},help:{"v1-i5k0iw-5k":`Infrastructure de messagerie et paramètres par défaut communs aux agents. Les sections de même niveau à la racine gèrent l’infrastructure et les paramètres par défaut communs aux agents ; agents.defaults gère le comportement de la boucle d’agent ; les entrées propres à chaque agent peuvent remplacer les uns comme les autres lorsque cela est pris en charge.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji de réaction d’accusé de réception`},help:{"v1-1iip0zs-1x":`Réaction emoji utilisée pour accuser réception des messages entrants (une valeur vide la désactive).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Portée des réactions d’accusé de réception`},help:{"v1-1jvdg5n-7s":`Définit quand envoyer des réactions d’accusé de réception ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" accuse réception des messages de groupe qui mentionnent l’agent, que le groupe exige ou non des mentions ; "group-all" accuse réception de chaque message de groupe. "off"/"none" désactive entièrement les réactions d’accusé de réception.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Règles des discussions de groupe`},help:{"v1-chqsvh-4l":`Paramètres de traitement des messages de groupe, notamment les déclencheurs de mention et la taille de la fenêtre d’historique. Utilisez des motifs de mention précis pour éviter que chaque message dans les canaux de groupe ne déclenche l’agent.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Limite de l’historique de groupe`},help:{"v1-1mkbpw-9k":`Nombre maximal de messages de groupe précédents chargés comme contexte à chaque tour pour les sessions de groupe. Utilisez des valeurs plus élevées pour une meilleure continuité, ou plus faibles pour des réponses plus rapides et moins coûteuses. L’historique automatique du prompt est limité à 200 messages. La valeur entière maximale de JSON sélectionne la fenêtre par défaut du canal (50 pour l’historique de groupe partagé), et non une fenêtre illimitée.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Motifs de mention dans les groupes`},help:{"v1-i7h7qc-6f":`Motifs d’expressions régulières sûrs et insensibles à la casse, utilisés pour détecter les mentions explicites et les phrases déclencheuses dans les discussions de groupe. Utilisez des motifs précis pour réduire les faux positifs dans les canaux à fort volume ; les motifs invalides ou comportant des répétitions imbriquées non sûres sont ignorés.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Messages entrants sans mention dans les groupes`},help:{"v1-17wef8h-5f":`Contrôle la manière dont les discussions de groupe sans mention sont soumises lorsque l’écoute est permanente. "user_request" les traite comme une requête utilisateur ; "room_event" les soumet comme contexte discret, où toute sortie visible nécessite l’outil de messagerie.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Réponses visibles dans les groupes`},help:{"v1-qa4z1s-aa":`Remplace le comportement des réponses sources rédigées par le modèle pour les conversations de groupe ou de canal. La valeur par défaut est "automatic" lorsqu’aucune politique globale de réponse visible n’est définie. "message_tool" exige message(action=send) pour les sorties normales de l’assistant et les médias génériques des outils ; les sorties d’exécution explicitement gérées par l’hôte restent transmissibles, sauf pour les événements ambiants du salon. "automatic" publie les réponses normales comme auparavant.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Temporisation des messages entrants`},help:{"v1-ebyu5x-4a":`Paramètres de temporisation des messages entrants directs, appliqués avant le début du traitement de la file d’attente ou du tour. Configurez-les pour gérer les rafales de messages d’un même expéditeur propres à chaque fournisseur.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Temporisation des messages entrants par canal (ms)`},help:{"v1-wbz54j-4g":`Délais de regroupement des messages entrants propres à chaque canal, en millisecondes, indexés par identifiant de fournisseur. Utilisez ce réglage lorsque certains fournisseurs envoient des fragments de messages à une cadence plus élevée que d’autres.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Délai de regroupement des messages entrants (ms)`},help:{"v1-1616yo2-7w":`Délai d’inactivité (ms) permettant de regrouper les messages entrants rapprochés d’un même expéditeur. Telegram utilise par défaut 300 ms lorsqu’aucune valeur de remplacement n’est définie globalement ou pour le canal ; les autres canaux utilisent 0 par défaut. Une valeur de zéro désactive le regroupement habituel des messages en rafale, mais Telegram réassemble toujours les fragments de messages longs dont la taille approche la limite.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`File d’attente des messages entrants`},help:{"v1-hm2o31-48":`Stratégie de mise en file d’attente des messages entrants reçus pendant l’exécution d’une session. Utilisez ce réglage pour ajuster la réorientation, les suivis différés, le regroupement ou l’interruption.`}},"messages%2Equeue%2EallowCollaborativeSteering":{label:{"v1-95t3u6-s":`Autoriser le pilotage collaboratif`},help:{"v1-1pyzwb-ip":`Autorise les interventions humaines admises dans la même conversation à réorienter le tour actif en conservant son identité et ses autorisations préparées, même si leur auteur dispose de moins d’autorisations (par défaut : true). Les interventions via la WebUI avec des identifiants partagés et via les canaux peuvent également poursuivre exactement la même session active. Lorsque la valeur est false, cette exception exige les droits actuels d’administrateur de la WebUI et de propriétaire du canal ; la continuité personnelle vérifiée reste également possible. Sinon, collaborativeSteeringFallback choisit entre un tour mis en file d’attente sans notification et appartenant au demandeur (queue) et un refus strict (reject). Les droits d’accès actuels, les droits d’exécution en temps réel, les vérifications des paramètres d’exécution, les modes de mise en file d’attente et l’autorisation de réorientation entre sessions continuent de s’appliquer.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Mode de file d’attente par canal`},help:{"v1-1vbyy4u-5q":`Remplacements du mode de mise en file d’attente par canal, indexés par identifiant de canal, y compris les canaux de plugins (par exemple discord, telegram, x). Utilisez ce paramètre lorsque le profil de trafic d’un canal nécessite un comportement différent des valeurs globales par défaut.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Capacité de la file d’attente`},help:{"v1-16ql8c7-4j":`Nombre maximal d’éléments entrants conservés dans la file d’attente avant l’application de la politique de suppression. La valeur par défaut est 20 ; maintenez une limite raisonnable sur les canaux très actifs afin que l’utilisation de la mémoire reste prévisible.`}},"messages%2Equeue%2EcollaborativeSteeringFallback":{label:{"v1-3k0wft-v":`Solution de repli pour l’orientation collaborative`},help:{"v1-peu9fu-8i":`Comportement lorsqu’une autre personne ne peut pas orienter le tour parce que l’orientation collaborative est désactivée : "queue" (par défaut) traite sa contribution dans un tour distinct sans notification d’état ; "reject" maintient un refus strict et exige une nouvelle demande /followup. N’active pas l’orientation collaborative et ne contourne pas les contrôles d’accès.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Délai de regroupement de repli de la file d’attente par canal (ms)`},help:{"v1-1w7gk9b-54":`Remplacements du délai de temporisation de la file d’attente par canal, indexés par identifiant de canal, y compris les canaux de plugins. Utilisez ce paramètre pour ajuster indépendamment le traitement des rafales de messages sur les interfaces de discussion dont les rythmes diffèrent.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Stratégie de suppression de la file d’attente`},help:{"v1-ydb2rw-6m":`Stratégie de suppression lorsque la capacité maximale de la file d’attente est dépassée. "summarize" supprime les entrées les plus anciennes mais conserve des résumés compacts ; "old" supprime les plus anciennes sans résumé ; "new" rejette l’élément le plus récent. Utilisez "summarize" pour les conversations de longue durée où le contexte est important.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Mode de file d’attente`},help:{"v1-19k7gy1-67":`Mode de file d’attente pour les exécutions en cours. Utilisez "steer" pour injecter des prompts dans l’exécution en cours, "followup" pour les exécuter plus tard, "collect" pour traiter ultérieurement les messages compatibles par lots, ou "interrupt" pour interrompre l’exécution en cours avant de lancer le prompt le plus récent.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Préfixe des réponses sortantes`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Mode par défaut du pied de page d’utilisation`},help:{"v1-l3shsx-dv":`Mode par défaut du pied de page d’utilisation pour chaque réponse ("off"|"tokens"|"full"), appliqué aux sessions qui n’en ont pas choisi via /usage. Accepte également "on" comme ancien alias de "tokens". Accepte un mode seul ou une table de correspondance par canal avec une valeur de repli "default". Ordre de priorité : valeur de la session -> entrée du canal -> default -> off ; un choix explicite via /usage (y compris off) est conservé et remplace la valeur par défaut. Utilisez /usage reset (alias : inherit, clear, default) pour supprimer la dérogation d’une session et rétablir l’héritage de cette valeur par défaut configurée.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Réactions de statut`},help:{"v1-193764l-3s":`Réactions de statut du cycle de vie qui mettent à jour l’emoji sur le message déclencheur à mesure que l’agent progresse (en attente → réflexion → outil → terminé/erreur).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Activer les réactions de statut`},help:{"v1-1qnmmnc-7x":`Active les réactions d’état du cycle de vie sur les canaux compatibles. Discord considère une valeur non définie comme activée lorsque les réactions d’accusé de réception sont actives ; Slack, Signal, Telegram et WhatsApp exigent que cette valeur soit true pour utiliser les réactions du cycle de vie. Par défaut, Slack utilise l’état natif des fils de discussion de l’assistant pour indiquer la progression.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Modèle de pied de page d’utilisation`},help:{"v1-1xibc23-47":`Modèle personnalisé de pied de page pour /usage full, sous forme d’objet intégré ou de chemin vers un fichier JSON. Si le modèle est invalide ou indisponible, la ligne d’utilisation intégrée est utilisée.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Réponses visibles`},help:{"v1-7yfwc2-8t":`Contrôle les réponses sources rédigées par le modèle dans les conversations directes, de groupe et de canal. "message_tool" exige message(action=send) pour les sorties normales de l’assistant et les médias génériques des outils ; les sorties d’exécution explicitement gérées par l’hôte peuvent toujours être transmises, sauf pour les événements ambiants du salon. "automatic" publie les réponses normales comme auparavant.`}},meta:{label:{"v1-1xpfxac-m":`Métadonnées de compatibilité`},help:{"v1-1owqhgn-2w":`Métadonnées de compatibilité lisibles par les versions antérieures, conservées pour permettre aux anciens binaires de refuser les rétrogradations de configuration non sûres.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Dernière version ayant modifié la configuration`},help:{"v1-qykpv1-1i":`Version d’OpenClaw ayant écrit cette configuration en dernier.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Marqueurs de migration de configuration`},help:{"v1-burt8q-1q":`Marqueurs de compatibilité en nombre limité pour les migrations de configuration terminées.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migration de la liste d’autorisation de la politique des modèles`},help:{"v1-5psop1-1z":`Indique que les anciennes restrictions de correspondance des modèles ont été conservées ou évaluées.`}},"meta%2Emigrations%2EskillLibraryToolSplit":{label:{"v1-1x6n7ed-y":`Migration de séparation de l’outil de bibliothèque de compétences`},help:{"v1-jph48r-3s":`Indique que les politiques d’utilisation des outils couvrant skill_workshop ont été étendues à skill_library lorsque la création de contenu dans la bibliothèque personnelle a été transférée vers un outil dédié.`}},"meta%2Emigrations%2EskillWorkshopPlugin":{label:{"v1-1703542-v":`Migration du plugin Skill Workshop`},help:{"v1-1y4ur5t-2i":`Consigne la suppression de la politique du plugin Skill Workshop définie lorsque Workshop était intégré.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migration de séparation des modèles utilitaires`},help:{"v1-vzdfqx-2t":`Indique que les anciens modèles principaux implicites ont été conservés avant la séparation de la sélection des modèles utilitaires.`}},models:{label:{"v1-hzmwb-6":`Modèles`},help:{"v1-1h1niol-5q":`Racine du catalogue de modèles pour les définitions de fournisseurs, le comportement de fusion ou de remplacement et l’intégration facultative de la découverte Bedrock. Gardez les définitions de fournisseurs explicites et validez-les avant de vous appuyer sur les mécanismes de basculement en production.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Actualisation du catalogue de modèles`},help:{"v1-1hess4t-40":`Contrôle les mises à jour en arrière-plan du catalogue de modèles intégré. Les entrées distantes peuvent mettre à jour les métadonnées des modèles, mais ne peuvent pas modifier les points de terminaison ni les en-têtes des fournisseurs.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Actualisation du catalogue de modèles activée`},help:{"v1-1fogpjj-3j":`Récupère les mises à jour du catalogue de modèles hébergé en arrière-plan (par défaut : true). Définissez cette option sur false pour désactiver tout trafic distant lié au catalogue de modèles.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL d’actualisation du catalogue de modèles`},help:{"v1-ai1thy-6o":`Remplacez l’URL du catalogue de modèles hébergé par celle d’un miroir HTTPS auto-hébergé (HTTP sur localhost est autorisé pour les tests). Un Gateway en cours d’exécution cesse d’utiliser le catalogue de la source précédente et adopte celui du miroir lors de sa prochaine vérification du catalogue, sans redémarrage.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Mode du catalogue de modèles`},help:{"v1-1ofrnsp-es":`Contrôle le comportement du catalogue de fournisseurs : "merge" conserve les fournisseurs intégrés et y superpose vos fournisseurs personnalisés, tandis que "replace" utilise uniquement les fournisseurs que vous avez configurés. En mode "merge", les identifiants de fournisseurs correspondants conservent les valeurs baseUrl non vides du fichier models.json de l’agent, tandis que les valeurs apiKey ne sont conservées que si le fournisseur n’est pas géré par SecretRef dans le contexte actuel de configuration et de profil d’authentification ; les fournisseurs gérés par SecretRef actualisent apiKey à partir des marqueurs de source actuels, et les valeurs contextWindow/maxTokens des modèles correspondants utilisent la valeur la plus élevée entre les entrées explicites et implicites.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Fournisseurs de modèles`},help:{"v1-7b5l2y-fo":`Configurations des points de terminaison de modèles, indexées par identifiant de fournisseur. Choisissez un nouvel identifiant, comme gpu-a ou my-lab, pour un point de terminaison personnalisé indépendant. Les identifiants et alias intégrés ou appartenant à des extensions conservent leur sémantique d’intégration ; en configurer un modifie la configuration de cette intégration. L’identifiant ne détermine pas le protocole de communication : c’est api qui le fait. Plusieurs identifiants personnalisés peuvent utiliser le même adaptateur avec des URL de base, des identifiants d’authentification et des modèles différents. Utilisez un identifiant distinct pour un serveur indépendant plutôt que de réaffecter openai simplement parce qu’il est compatible avec OpenAI. Les entrées personnalisées doivent inclure baseUrl et models.`}},"models%2Eproviders%2E*":{help:{"v1-1sjqhly-54":`Configuration d’un fournisseur nommé. Remplacez * par l’identifiant de votre choix ou par l’identifiant d’une intégration existante dont vous souhaitez délibérément remplacer la configuration. La recherche dans le schéma fonctionne même avant qu’un identifiant personnalisé soit configuré.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Environnement d’exécution du fournisseur de modèles`},help:{"v1-1luy4fb-5o":`Politique facultative de bas niveau pour l’environnement d’exécution de l’agent associé à ce fournisseur. Utilisez une politique d’exécution au niveau du fournisseur ou du modèle plutôt qu’un environnement d’exécution imposé à l’ensemble de l’agent ; si ce paramètre est omis ou laissé par défaut, OpenClaw choisit l’environnement d’exécution pour le fournisseur sélectionné.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Identifiant de l’environnement d’exécution du fournisseur de modèles`},help:{"v1-1gusd9s-69":`Identifiant de l’environnement d’exécution de l’agent associé au fournisseur : "openclaw", "auto", un identifiant de harnais de plugin enregistré tel que "codex", ou un alias de backend CLI pris en charge tel que "claude-cli". Pour OpenAI sur le point de terminaison officiel, le harnais Codex est utilisé par défaut si ce paramètre est omis.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Adaptateur d’API du fournisseur de modèles`},help:{"v1-jpi8x4-6e":`Adaptateur de protocole de communication, indépendant de l’identifiant du fournisseur. Chat Completions: openai-completions; Responses: openai-responses; Messages: anthropic-messages. Choisissez d’autres adaptateurs parmi les valeurs autorisées pour correspondre au protocole de votre service en amont.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Clé d’API du fournisseur de modèles`},help:{"v1-1p84k96-54":`Identifiant du fournisseur utilisé pour l’authentification par clé d’API lorsque le fournisseur exige une authentification directe par clé. Utilisez la substitution par des secrets ou des variables d’environnement et évitez de stocker de véritables clés dans les fichiers de configuration versionnés.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Mode d’authentification du fournisseur de modèles`},help:{"v1-1g4jg7x-et":`Sélectionne le mode d’authentification du fournisseur : "api-key" pour l’authentification par clé API, "token" pour l’authentification par jeton porteur, "oauth" pour les identifiants OAuth, "aws-sdk" pour la résolution des identifiants AWS et "none" pour les points de terminaison openai-completions personnalisés qui n’imposent pas d’authentification. La valeur explicite "none" ignore les identifiants et n’envoie aucun en-tête Authorization ; les autres adaptateurs effectifs sont rejetés. "native-command" délègue la gestion des identifiants à un environnement d’exécution Codex explicitement configuré pour un fournisseur Responses HTTPS personnalisé ; ce mode ne peut pas être combiné avec des clés API, des profils ou des paramètres de requête de remplacement.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`En-tête Authorization du fournisseur de modèles`},help:{"v1-1gn3lt3-59":`Si la valeur est true, les identifiants sont envoyés via l’en-tête HTTP Authorization, même si une autre méthode d’authentification est possible. Utilisez cette option uniquement si votre fournisseur ou votre proxy exige explicitement la transmission de l’en-tête Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`URL de base du fournisseur de modèles`},help:{"v1-1ku88v8-53":`URL de base du point de terminaison du fournisseur utilisé pour traiter les requêtes de modèles associées à cette entrée. Utilisez des points de terminaison HTTPS et, si nécessaire, des modèles de configuration pour adapter les URL à chaque environnement.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`En-têtes du fournisseur de modèles`},help:{"v1-chg59u-4x":`En-têtes HTTP statiques ajoutés aux requêtes du fournisseur pour le routage par locataire, l’authentification du proxy ou les exigences d’une passerelle personnalisée. Utilisez cette option avec parcimonie et stockez les valeurs d’en-tête sensibles dans des secrets.`}},"models%2Eproviders%2E*%2Eicon":{label:{"v1-1cwoqcc-j":`Icône du fournisseur de modèles`},help:{"v1-opei4i-9m":`Visuel facultatif du fournisseur : fichier local, URL HTTPS publique d’une image ou icône intégrée. Les sources PNG, JPEG, WebP et GIF sont limitées à 2 Mio et à 4096 pixels par côté, et sont diffusées sous forme de PNG statique assaini. Les chemins de fichiers relatifs sont résolus à partir du répertoire du fichier de configuration actif. Si le visuel n’est pas valide, le logo du fournisseur ou l’initiale de son nom d’affichage est utilisé.`}},"models%2Eproviders%2E*%2Eicon%2Ename":{label:{"v1-btu3z4-r":`Icône intégrée du fournisseur de modèles`},help:{"v1-14mjg6a-3j":`Nom d’une icône intégrée à l’application web, comme server. Si le nom est inconnu, l’icône de marque intégrée du fournisseur ou l’initiale de son nom d’affichage est utilisée.`}},"models%2Eproviders%2E*%2Eicon%2Epath":{label:{"v1-1pddy1u-o":`Fichier d’icône du fournisseur de modèles`},help:{"v1-1fgtl8e-73":`Chemin local à Gateway vers un fichier PNG, JPEG, WebP ou GIF. Les chemins relatifs sont résolus à partir du répertoire contenant le fichier de configuration actif ; ~/ correspond au répertoire personnel de l’utilisateur de Gateway. Seule cette image configurée est exposée via la route d’accès aux ressources propre au fournisseur.`}},"models%2Eproviders%2E*%2Eicon%2Esource":{label:{"v1-13ahm5t-q":`Source de l’icône du fournisseur de modèles`},help:{"v1-173lyjy-3i":`Source de l’illustration : file pour une image locale sur Gateway, url pour une image HTTPS publique, ou builtin pour une icône fournie avec l’application web.`}},"models%2Eproviders%2E*%2Eicon%2Eurl":{label:{"v1-1euf5yl-n":`URL de l’icône du fournisseur de modèles`},help:{"v1-147pn2x-65":`URL HTTPS publique d’une image PNG, JPEG, WebP ou GIF, sans identifiants intégrés ni fragment. Gateway récupère et assainit l’image avec des protections contre l’accès aux réseaux privés et les redirections ; le navigateur ne contacte jamais directement cette URL.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Injection de num_ctx pour le fournisseur de modèles (compatibilité OpenAI)`},help:{"v1-53rmcr-6n":"Détermine si OpenClaw injecte `options.num_ctx` pour les fournisseurs Ollama configurés avec l’adaptateur compatible OpenAI (`openai-completions`). La valeur par défaut est true. Définissez cette option sur false uniquement si votre proxy ou service en amont rejette les champs inconnus dans `options` au sein des données envoyées."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Service local du fournisseur de modèles`},help:{"v1-9r1lm6-4y":`Processus facultatif de serveur de modèles local, lancé à la demande pour ce fournisseur. OpenClaw vérifie healthUrl, lance la commande si nécessaire, attend que le serveur soit prêt, puis envoie la requête au modèle.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Arguments du service local du fournisseur de modèles`},help:{"v1-t12wib-27":`Liste des arguments transmis à la commande du serveur de modèles local sans expansion par le shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Commande du service local du fournisseur de modèles`},help:{"v1-64k3ef-4h":`Chemin absolu de l’exécutable du processus du serveur de modèles local. Définissez ce chemin explicitement afin que le démarrage du fournisseur soit prévisible et ne dépende pas d’une recherche dans le PATH du shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Répertoire de travail du service local du fournisseur de modèles`},help:{"v1-fi3xlx-1h":`Répertoire de travail du processus de serveur de modèles local.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Environnement du service local du fournisseur de modèles`},help:{"v1-1lwb9k1-3k":`Variables d’environnement supplémentaires pour le processus de serveur de modèles local. Les valeurs qui semblent secrètes sont masquées dans les instantanés de configuration.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL de vérification de l’état du service local du fournisseur de modèles`},help:{"v1-12nvqxl-36":`URL utilisée pour vérifier que le serveur est prêt avant les requêtes au modèle. Si elle n’est pas renseignée, OpenClaw utilise baseUrl du fournisseur en y ajoutant /models.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Arrêt en cas d’inactivité du service local du fournisseur de modèles`},help:{"v1-1efg054-3z":`Durée en millisecondes pendant laquelle maintenir actif un serveur de modèles local lancé par OpenClaw après la fin de la dernière requête. Définissez la valeur sur 0 pour le maintenir actif jusqu’à la fermeture d’OpenClaw.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Délai d’attente de disponibilité du service local du fournisseur de modèles`},help:{"v1-bwmfqa-2r":`Délai d’attente maximal, en millisecondes, pour vérifier que le serveur de modèles local est prêt après le démarrage du processus.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Nombre maximal de tokens du fournisseur de modèles`},help:{"v1-fnj50y-38":`Budget maximal de tokens de sortie appliqué par défaut aux modèles de ce fournisseur lorsqu’une entrée de modèle ne définit pas maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Liste des modèles du fournisseur`},help:{"v1-1vbm0gt-63":`Liste des modèles déclarés pour un fournisseur, comprenant les identifiants, les métadonnées, les paramètres propres au fournisseur et des indications facultatives de compatibilité et de coût. Conservez des identifiants strictement identiques aux valeurs du catalogue du fournisseur pour que la sélection et le recours aux modèles de secours fonctionnent correctement.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Environnement d’exécution du modèle`},help:{"v1-1k70g2n-3g":`Politique facultative de bas niveau de l’environnement d’exécution de l’agent pour ce modèle précis. La politique d’exécution du modèle prévaut sur celle du fournisseur.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`Identifiant de l’environnement d’exécution du modèle`},help:{"v1-1llzv33-42":`Identifiant de l’environnement d’exécution de l’agent du modèle : "openclaw", "auto", un identifiant de harnais de plugin enregistré tel que "codex", ou un alias de backend CLI pris en charge tel que "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Entrée multimédia du modèle`},help:{"v1-wxtj8e-2x":`Métadonnées facultatives sur les capacités multimédias du modèle, utilisées par les outils pour choisir des paramètres de compression d’image prudents par défaut.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Entrée image du modèle`},help:{"v1-1nviirq-3c":`Limites facultatives des images en entrée pour ce modèle, telles que la longueur maximale d’un côté, le nombre maximal de pixels et la longueur de côté privilégiée pour la compression.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Taille maximale des images du modèle en octets`},help:{"v1-c2469j-23":`Taille maximale des données d’image encodées acceptée par le fournisseur pour ce modèle.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Nombre maximal de pixels des images du modèle`},help:{"v1-9d6yqp-1u":`Nombre maximal de pixels par image accepté par le fournisseur pour ce modèle.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Longueur maximale d’un côté des images du modèle`},help:{"v1-1gbci08-1y":`Largeur ou hauteur maximale des images acceptée par le fournisseur pour ce modèle.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Longueur de côté privilégiée pour les images du modèle`},help:{"v1-1u1mpcg-2x":`Longueur de côté privilégiée pour le redimensionnement des images afin d’obtenir une compression équilibrée. Laissez ce paramètre non défini pour utiliser la valeur prudente par défaut d’OpenClaw.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Mode de comptabilisation des tokens d’image du modèle`},help:{"v1-1oy6z7v-1z":`Mode de comptabilisation des tokens d’image du fournisseur : "tile", "detail" ou "provider".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EresponseModelEquivalent":{help:{"v1-1hociw2-d7":`Définissez cette valeur sur true dans une entrée de fournisseur personnalisé créée par l’utilisateur lorsqu’un routeur ou un intermédiaire résout lui-même cet identifiant de modèle. Tout identifiant de réponse renvoyé par le point de terminaison est alors considéré comme équivalent, y compris en cas de substitutions internes au point de terminaison. L’identifiant effectivement utilisé et les données d’utilisation restent enregistrés ; les notifications de repli et de remplacement d’OpenClaw sont conservées. La politique intégrée ou officielle ne peut pas être remplacée. Les entrées de plugin ou de catalogue, les entrées du fichier models.json de l’agent et les entrées models-add ne peuvent pas accorder cette équivalence. Si cette valeur est omise ou définie sur false, la détection normale des routes est conservée.`}},"models%2Eproviders%2E*%2Ename":{label:{"v1-ioaceo-r":`Nom d’affichage du fournisseur de modèles`},help:{"v1-jio82-3z":`Nom d’affichage facultatif utilisé dans les paramètres du fournisseur et les sélecteurs de modèles. Ne modifie pas l’identifiant du fournisseur, les références des modèles, les informations d’authentification ni le routage.`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Paramètres d’exécution du fournisseur de modèles`},help:{"v1-464sgu-4t":`Paramètres d’exécution propres au fournisseur, interprétés par ses plugins. Conservez les clés documentées par le fournisseur et privilégiez sa documentation explicite plutôt que des hypothèses communes formulées au cas par cas.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Région du fournisseur de modèles`},help:{"v1-yq7rxk-5h":`Région facultative de déploiement ou d’API du fournisseur, interprétée par les fournisseurs qui proposent des points de terminaison régionaux. Consultez la documentation du fournisseur pour connaître les valeurs prises en charge ; les valeurs de remplacement de baseUrl sont généralement prioritaires lorsque les deux sont définis.`}},"models%2Eproviders%2E*%2Eremote":{label:{"v1-ih3vfx-11":`Délais de surveillance du fournisseur de modèles hébergé`},help:{"v1-bsr5s-9g":`Remplacement des délais par ceux des services hébergés, uniquement pour les mécanismes de surveillance, lorsque des relais locaux se trouvent devant des API hébergées. Lorsque la valeur est true, les mécanismes de surveillance de l’inactivité du LLM et du premier événement utilisent les délais des services hébergés, même en présence d’un baseUrl local, d’un identifiant de fournisseur local, de localService ou d’un marqueur d’authentification locale. Une valeur absente ou false conserve la détection du caractère local. Les valeurs explicites de timeoutSeconds et les budgets d’exécution ou d’agent restent prioritaires.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Paramètres de remplacement des requêtes au fournisseur de modèles`},help:{"v1-1lkxryk-87":`Paramètres de remplacement facultatifs pour les requêtes au fournisseur de modèles, notamment des en-têtes supplémentaires, des paramètres d’authentification de remplacement, le routage par proxy, les paramètres du client TLS et l’option allowPrivateNetwork pour les points de terminaison auto-hébergés de confiance. Utilisez-les uniquement lorsque votre service en amont ou le chemin réseau de votre entreprise nécessite une personnalisation du transport.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Autoriser le réseau privé pour les requêtes au fournisseur de modèles`},help:{"v1-1nbtcjk-fo":`Si la valeur est true, autorise les requêtes HTTP du fournisseur de modèles vers des plages privées, CGNAT ou similaires via le mécanisme de protection des requêtes HTTP du fournisseur (fetchWithSsrFGuard). Les URL de base des fournisseurs personnalisés ou locaux font déjà confiance à l’origine exacte configurée, à l’exception des origines de métadonnées, de liaison locale et NAT64 à usage local (64:ff9b:1::/48) ; définissez cette valeur sur false pour désactiver cette confiance. OpenAI Responses WebSocket réutilise request pour les en-têtes et TLS, mais n’utilise pas ce mécanisme de protection SSRF des requêtes. Utilisez true uniquement pour les points de terminaison auto-hébergés contrôlés par l’opérateur qui doivent accéder à des origines privées autres que l’origine baseUrl configurée.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Remplacement de l’authentification des requêtes du fournisseur de modèles`},help:{"v1-ucdgnf-1w":`Remplace le comportement d’authentification des requêtes pour ce fournisseur.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Nom de l’en-tête d’authentification des requêtes du fournisseur de modèles`},help:{"v1-1881nqr-1i":`Nom de l’en-tête d’authentification personnalisé utilisé lorsque le mode d’authentification est header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Mode d’authentification des requêtes du fournisseur de modèles`},help:{"v1-1lhv8hs-24":`Mode de remplacement de l’authentification : "provider-default", "authorization-bearer" ou "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Préfixe de l’en-tête d’authentification des requêtes du fournisseur de modèles`},help:{"v1-1rbm9lz-21":`Préfixe facultatif ajouté devant request.auth.value lorsque le mode d’authentification est header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Jeton Bearer des requêtes du fournisseur de modèles`},help:{"v1-6rcasw-1l":`Jeton Bearer utilisé lorsque le mode d’authentification est authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Valeur de l’en-tête d’authentification des requêtes au fournisseur de modèles`},help:{"v1-1v69ej-1j":`Valeur personnalisée de l’en-tête d’authentification utilisée lorsque le mode d’authentification est header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`En-têtes des requêtes au fournisseur de modèles`},help:{"v1-zj3orj-2i":`En-têtes supplémentaires ajoutés aux requêtes au fournisseur après l’attribution par défaut et la résolution de l’authentification.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proxy des requêtes au fournisseur de modèles`},help:{"v1-md5uj8-4j":`Configuration de proxy facultative pour les requêtes au fournisseur de modèles. Utilisez "env-proxy" pour respecter les paramètres de proxy de l’environnement ou "explicit-proxy" pour passer par une URL de proxy spécifique.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Mode de proxy des requêtes au fournisseur de modèles`},help:{"v1-1dx0ozg-29":`Mode de remplacement du proxy pour les requêtes au fournisseur de modèles : "env-proxy" ou "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS du proxy des requêtes au fournisseur de modèles`},help:{"v1-rdx62w-1v":`Paramètres TLS facultatifs utilisés lors de la connexion au proxy configuré.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`Autorités de certification TLS du proxy des requêtes au fournisseur de modèles`},help:{"v1-11pg2fd-1s":`Ensemble personnalisé de certificats d’autorités de certification utilisé pour vérifier la chaîne de certificats TLS du proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Certificat TLS du proxy des requêtes au fournisseur de modèles`},help:{"v1-x8nk2q-22":`Certificat TLS client présenté au proxy lorsque l’authentification TLS mutuelle est requise.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Désactivation de la vérification TLS du proxy des requêtes au fournisseur de modèles`},help:{"v1-12vjdm9-2j":`Désactive la vérification du certificat TLS du proxy. À utiliser uniquement dans des environnements de développement contrôlés.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Clé TLS du proxy des requêtes au fournisseur de modèles`},help:{"v1-1skyr56-1w":`Clé privée associée à request.proxy.tls.cert pour l’authentification TLS mutuelle avec le proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Phrase secrète TLS du proxy des requêtes au fournisseur de modèles`},help:{"v1-wjvoxd-1m":`Phrase secrète facultative utilisée pour déchiffrer request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Nom du serveur TLS du proxy des requêtes au fournisseur de modèles`},help:{"v1-b4oabu-22":`Valeur facultative remplaçant le SNI/nom du serveur lors de l’établissement de la connexion TLS au proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`URL du proxy des requêtes au fournisseur de modèles`},help:{"v1-kvbgou-48":`URL de proxy explicite utilisée lorsque request.proxy.mode est défini sur explicit-proxy. Les identifiants intégrés à l’URL sont considérés comme sensibles et masqués dans les instantanés.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS des requêtes au fournisseur de modèles`},help:{"v1-16u7v7h-2b":`Paramètres TLS facultatifs utilisés lors de la connexion directe au point de terminaison du modèle en amont.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`Autorité de certification TLS des requêtes au fournisseur de modèles`},help:{"v1-ny8y3e-1v":`Ensemble personnalisé de certificats d’autorités de certification utilisé pour vérifier la chaîne de certificats TLS en amont.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Certificat TLS des requêtes au fournisseur de modèles`},help:{"v1-1lltmhw-2e":`Certificat TLS client présenté au point de terminaison en amont lorsqu’une authentification TLS mutuelle est requise.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Ignorer la vérification TLS des requêtes au fournisseur de modèles`},help:{"v1-1006cuy-2m":`Ignore la vérification du certificat TLS en amont. À utiliser uniquement dans des environnements de développement contrôlés.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Clé TLS des requêtes au fournisseur de modèles`},help:{"v1-w2agir-1t":`Clé privée associée à request.tls.cert pour l’authentification TLS mutuelle en amont.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Phrase secrète TLS des requêtes au fournisseur de modèles`},help:{"v1-10ds42f-1g":`Phrase secrète facultative utilisée pour déchiffrer request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Nom du serveur TLS des requêtes au fournisseur de modèles`},help:{"v1-18yt7x9-1y":`Valeur facultative remplaçant le SNI/nom du serveur lors de l’établissement de la connexion TLS en amont.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Délai d’expiration des requêtes au fournisseur de modèles`},help:{"v1-t3yn8l-ih":`Délai d’expiration facultatif, en secondes, des requêtes de modèle pour chaque fournisseur. Les paramètres de requête définis au niveau du fournisseur s’appliquent aux entrées de modèles explicitement associées à ce fournisseur ; ils ne créent pas de modèles implicites. Pour les fournisseurs personnalisés, définissez ce paramètre avec les paramètres baseUrl et models du fournisseur. Il s’applique aux requêtes HTTP du fournisseur, notamment à la connexion, aux en-têtes, au corps et à la gestion de l’interruption de la requête complète. Il relève également, pour ce fournisseur, le seuil du mécanisme de surveillance de l’inactivité et du streaming du LLM au-delà de la valeur implicite par défaut d’environ 120 secondes. Utilisez ce paramètre pour les serveurs de modèles locaux ou auto-hébergés lents, ou pour les fournisseurs cloud qui mettent en mémoire tampon les jetons de raisonnement sans rien transmettre sur le réseau (Gemini en préversion, Claude/Opus avec des charges utiles d’outils volumineuses), plutôt que de modifier les délais d’expiration globaux des agents.`}},"models%2Eusage":{label:{"v1-1frhz6j-e":`Utilisation du fournisseur`},help:{"v1-hn2n9r-18":`Paramètres du cache des données d’utilisation du forfait communiquées par le fournisseur.`}},"models%2Eusage%2EcacheTtlMs":{label:{"v1-1g6hvog-t":`Durée de vie du cache d’utilisation du fournisseur (ms)`},help:{"v1-jltn3b-4j":`Réutilise les instantanés d’utilisation du fournisseur pendant ce nombre de millisecondes (par défaut : 60000). S’applique aux lectures ordinaires et à celles effectuées après une exécution ; 0 désactive la réutilisation. N’active pas l’interrogation périodique en période d’inactivité.`}},nodeHost:{label:{"v1-nb8lk1-9":`Hôte de nœud`},help:{"v1-8recuz-4z":`Paramètres de l’hôte de nœud pour les fonctionnalités exposées par ce nœud de passerelle aux autres nœuds ou clients. Conservez les valeurs par défaut, sauf si vous souhaitez délibérément relayer des fonctionnalités locales à travers votre réseau de nœuds.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Exécutions d’agent sur le nœud`},help:{"v1-4uz5ur-2k":`Activez les tours d’agent natifs soumis à approbation sur cet hôte de nœud sans interface graphique. Désactivé par défaut.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Exécutions d’agent Claude sur le nœud`},help:{"v1-g8az5y-2l":`Détermine si cet hôte de nœud sans interface graphique peut annoncer à la passerelle la disponibilité de tours d’agent via la CLI Claude.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Exécutions d’agent Claude sur le nœud activées`},help:{"v1-1ke804l-44":`Annonce la possibilité de poursuivre une session Claude sur un nœud appairé lorsque le binaire local claude est disponible (valeur par défaut : false). Les exécutions nécessitent toujours une approbation d’exécution sur le nœud.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Mises à jour automatiques des nœuds`},help:{"v1-16xjk4e-5n":`Contrôle les mises à jour automatiques de l’environnement d’exécution distinct pour les hôtes de nœuds sans interface graphique distribués sous forme de paquets. Vérifie toutes les heures et attend la fin de toutes les tâches des nœuds avant de redémarrer ; les redémarrages automatiques sont espacés d’au moins 12 heures.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Mises à jour automatiques des nœuds activées`},help:{"v1-1sa0yeg-7w":`Active les mises à jour automatiques stables ou bêta pour les nœuds sans interface graphique distribués sous forme de paquets et fonctionnant en continu (par défaut : true). Définissez la valeur sur false pour les désactiver. Elles sont également désactivées par update.checkOnStart=false ou OPENCLAW_NO_AUTO_UPDATE=1 ; les copies de travail du code source, les applications natives, les workers privés, dev et extended-stable n’appliquent pas automatiquement les mises à jour.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Proxy de navigateur du nœud`},help:{"v1-2xrew7-4f":`Regroupe les paramètres du proxy de navigateur permettant d’exposer le contrôle du navigateur local via le routage des nœuds. À activer uniquement lorsque les workflows des nœuds distants nécessitent vos profils de navigateur locaux.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Profils autorisés pour le proxy de navigateur du nœud`},help:{"v1-1ew5dkm-8b":`Liste facultative des noms de profils de navigateur autorisés à être exposés via le routage du proxy de nœud. Laissez ce champ vide pour conserver l’accès complet aux profils par défaut, y compris les routes de création et de suppression de profils. Lorsque cette liste est définie, OpenClaw applique le principe du moindre privilège à l’accès aux profils et bloque la création et la suppression de profils persistants via le proxy.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Proxy de navigateur du nœud activé`},help:{"v1-pa04pd-5b":`Expose le serveur de contrôle du navigateur local via le routage du proxy de nœud afin que les clients distants puissent utiliser les fonctionnalités du navigateur de cet hôte. Gardez cette option désactivée, sauf si une automatisation distante en dépend explicitement.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP de l’hôte de nœud`},help:{"v1-1mdhrwl-48":`Utilisez comme outils d’agent les serveurs MCP démarrés par l’hôte de nœud sans interface graphique et publiés sur sa passerelle appairée. Redémarrez l’hôte de nœud après avoir modifié cette section.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Serveurs MCP de l’hôte de nœud`},help:{"v1-19m002f-3x":`Définitions nommées des serveurs MCP locaux à ce nœud. Utilise la même structure de serveur que mcp.servers ; les serveurs OAuth ne sont pas pris en charge par l’hôte de nœud.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills de l’hôte de nœud`},help:{"v1-v8txza-41":`Utilisez cette section pour publier les compétences installées dans ~/.openclaw/skills depuis l’hôte de nœud sans interface graphique. Redémarrez l’hôte de nœud après avoir modifié les fichiers des compétences.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Skills de l’hôte de nœud activés`},help:{"v1-1ggpkqb-36":`Détecter et publier les compétences hébergées sur le nœud après la connexion (par défaut : true). Définissez sur false pour désactiver la publication des compétences du nœud.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Exécutions de workers sur le nœud`},help:{"v1-1w83rox-2p":`Activer l’hébergement complet de sessions de workers OpenClaw à partir de bundles gérés par Gateway. Désactivé par défaut.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Capacité d’exécution des workers sur le nœud`},help:{"v1-10nvk8f-3w":`Nombre maximal de sessions de workers simultanées hébergées par ce nœud (par défaut : le nombre de cœurs CPU disponibles). Doit être un entier compris entre 1 et 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Image de conteneur pour l’exécution des workers sur le nœud`},help:{"v1-1tmr1le-5y":`Image Node 24.22.1+ ou 26.12.1+ facultative pour les workers isolés dans des conteneurs (par défaut : "node:24.22.1-slim"). Si nécessaire, utilisez une image épinglée par son digest, provenant d’un registre privé ou préchargée ; les images manquantes sont téléchargées lors de la première utilisation.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Exécutions de workers sur le nœud activées`},help:{"v1-b3t0xp-2t":`Autoriser ce nœud appairé à héberger des sessions à partir des bundles exacts installés par son Gateway (par défaut : false).`}},"nodeHost%2EworkerRuns%2Efolders":{label:{"v1-1waimc-r":`Dossiers de session des workers du nœud`},help:{"v1-ald547-9v":`Répertoires racines facultatifs limitant les sessions sur place à ces répertoires et à leurs sous-répertoires. Si ce paramètre n’est pas défini, tout répertoire existant est autorisé, à l’exception des racines du système de fichiers et du stockage privé des workers ; [] désactive les sessions dans les dossiers de l’appareil. Utilisez des chemins absolus ou commençant par ~/. Les fichiers existants restent sur l’appareil ; la suppression d’une session ne supprime jamais ces dossiers. Nécessite workerRuns.enabled.`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Isolation des exécutions de workers sur le nœud`},help:{"v1-19i6swo-58":`Sélectionnez le périmètre d’isolation des processus des sessions de workers : "none" les exécute directement sur l’hôte du nœud (par défaut) ; "container" nécessite un moteur compatible Docker fonctionnel et ne bascule jamais vers une exécution sur l’hôte.`}},plugins:{label:{"v1-10renyj-7":`Extensions`},help:{"v1-1qbev2k-5c":`Commandes du système de plugins permettant d’activer les extensions, de limiter le périmètre de chargement, de configurer les entrées et de suivre les installations. Dans les environnements de production, définissez une politique explicite pour les plugins et appliquez le principe du moindre privilège.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Liste des plugins autorisés`},help:{"v1-1w1dsc3-ek":`Liste facultative d’ID de plugins autorisés ; une liste non vide restreint le chargement, sauf pour le plugin de mémoire sélectionné (y compris memory-core, sélectionné par défaut), les plugins context-engine de même ID et les canaux de discussion intégrés explicitement activés. Les plugins propriétaires de context-engine portant un nom différent doivent être activés ou autorisés indépendamment et figurer dans toute liste d’autorisation non vide. Les outils appartenant à des plugins hors de la liste d’autorisation restent indisponibles. Utilisez plugins.deny ou plugins.entries.<id>.enabled: false pour bloquer un plugin, quelle que soit la sélection d’emplacement.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Liste des plugins bloqués`},help:{"v1-4gyt4z-4i":`Liste facultative d’identifiants de plugins bloqués, même s’ils figurent dans des listes d’autorisation ou des chemins. Utilisez les règles de blocage pour les retours en arrière d’urgence et le blocage strict des plugins à risque.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Activer les plugins`},help:{"v1-pnygd7-50":`Active ou désactive globalement le chargement des plugins et des extensions au démarrage et lors du rechargement de la configuration (par défaut : true). Ne gardez cette option activée que si votre déploiement nécessite les fonctionnalités des extensions.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Entrées des plugins`},help:{"v1-cn74rf-54":`Paramètres propres à chaque plugin, indexés par identifiant de plugin, comprenant l’activation et les données de configuration d’exécution spécifiques au plugin. Utilisez ces paramètres pour ajuster individuellement les plugins sans modifier la politique globale de chargement.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Clé API du plugin`},help:{"v1-ctytg2-53":`Champ facultatif de clé API utilisé par les plugins qui acceptent la configuration directe d’une clé dans les paramètres de leur entrée. Utilisez la substitution par des secrets ou des variables d’environnement et évitez d’enregistrer de véritables identifiants dans les fichiers de configuration.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Configuration du plugin`},help:{"v1-1he672p-51":`Données de configuration définies par le plugin, interprétées selon son propre schéma et ses règles de validation. Utilisez uniquement les champs documentés par le plugin pour éviter les paramètres ignorés ou non valides.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Plugin activé`},help:{"v1-12soc0h-9a":`Dérogation d’activation pour un plugin spécifique, appliquée par-dessus la politique globale des plugins. Avec le mode de rechargement hybride par défaut, les modifications rechargent à chaud l’environnement d’exécution du plugin pour les nouveaux tours de l’agent, sans redémarrer le Gateway, sauf si le plugin exige un redémarrage pour ce chemin de configuration. Utilisez cette option pour déployer progressivement le plugin dans les différents environnements.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Variables d’environnement du plugin`},help:{"v1-p39pu4-52":`Table de variables d’environnement propre à chaque plugin, injectée uniquement dans son contexte d’exécution. Utilisez cette option pour limiter les identifiants du fournisseur à un seul plugin plutôt que de partager l’environnement global du processus.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Politique des hooks du plugin`},help:{"v1-1oslnrf-4c":`Paramètres de politique des hooks typés propres à chaque plugin pour les contrôles de sécurité imposés par le cœur du système. Utilisez cette option pour restreindre les catégories de hooks à fort impact sans désactiver le plugin entier.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Autoriser les hooks d’accès aux conversations`},help:{"v1-xqz31z-7e":"Détermine si ce plugin peut lire le contenu brut des conversations via des hooks typés tels que `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` et `agent_end`. Cette autorisation doit être explicitement activée pour les plugins non intégrés."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptModification":{label:{"v1-1ufndoc-e":`Modifier les prompts`},help:{"v1-10llywv-8b":`Permet à ce plugin d’ajouter ou de modifier le contexte et les instructions envoyés au modèle, ce qui peut influencer ses réponses. N’accordez cette autorisation qu’aux plugins auxquels vous faites confiance. Autorisé par défaut. Définissez la valeur sur false pour bloquer les hooks qui modifient les prompts, les consignes de prompt des outils, les ajouts au prompt du tour suivant et les interventions qui orientent l’exécution en cours.`}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Délai d’expiration des hooks du plugin (ms)`},help:{"v1-4ra6b7-74":`Délai d’expiration par défaut en millisecondes pour les hooks typés de ce plugin, plafonné à 600000. Si cette valeur n’est pas définie, chaque hook utilise le délai déclaré par le plugin ou la politique du Gateway propre à ce hook ; il n’existe pas de valeur par défaut fixe unique. Les valeurs par hook dans hooks.timeouts sont prioritaires.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Dérogations aux délais d’expiration des hooks du plugin`},help:{"v1-yphl9b-5s":`Dérogations aux délais d’expiration par hook, en millisecondes, indexées par nom de hook typé et plafonnées à 600000. Utilisez des dérogations ciblées pour les hooks connus pour leur lenteur, tels que before_prompt_build ou agent_end, plutôt que d’augmenter le délai d’expiration de tous les hooks.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Politique LLM du plugin`},help:{"v1-dlca6c-4j":`Contrôles api.runtime.llm.complete par plugin définissant les autorisations de remplacement du modèle et de l’agent. Laissez ce paramètre non défini, sauf si un plugin doit explicitement orienter les appels de complétion gérés par l’hôte.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Autoriser le remplacement de l’agent LLM par le plugin`},help:{"v1-k8c08b-4n":`Autorise explicitement ce plugin à appeler api.runtime.llm.complete avec un identifiant d’agent autre que celui par défaut. Conservez la valeur false, sauf si le plugin est considéré comme fiable pour accéder aux modèles d’autres agents.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Autoriser le remplacement du profil d’authentification LLM par le plugin`},help:{"v1-9ityw9-4x":`Autorise ce plugin à sélectionner un profil d’authentification autre que celui par défaut pour les complétions dans un environnement d’exécution d’agent isolé. Conservez la valeur false, sauf si le plugin est considéré comme fiable pour le routage explicite d’identifiants isolés.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Modèles de complétion LLM autorisés pour le plugin`},help:{"v1-1kgxs8j-55":`Cibles autorisées pour chaque complétion LLM du plugin, sous forme de références complètes "provider/model", y compris les valeurs par défaut et les substitutions résolues par l’hôte. Utilisez "*" uniquement si vous souhaitez autoriser n’importe quel modèle.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Modèles LLM autorisés pour le plugin`},help:{"v1-h9m5ew-48":`Cibles de substitution autorisées pour les appels LLM des plugins de confiance, sous forme de références complètes "provider/model". Utilisez "*" uniquement si vous souhaitez autoriser n’importe quelle substitution de modèle.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Autoriser le remplacement du modèle LLM par le plugin`},help:{"v1-uw4jmc-47":`Autorise explicitement ce plugin à demander des remplacements de modèle dans api.runtime.llm.complete. Conservez false, sauf si le plugin est jugé digne de confiance pour orienter la sélection du modèle.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Politique des sous-agents du plugin`},help:{"v1-wbf4m1-4d":`Paramètres d’exécution des sous-agents propres à chaque plugin, définissant les autorisations de remplacement de modèle et les listes de modèles autorisés. Laissez ce paramètre non défini, sauf si un plugin doit explicitement orienter la sélection du modèle des sous-agents.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Modèles autorisés pour les sous-agents du plugin`},help:{"v1-hdzz51-43":`Cibles de substitution autorisées pour les exécutions de sous-agents des plugins de confiance, sous forme de références complètes "provider/model". Utilisez "*" uniquement si vous souhaitez autoriser n’importe quel modèle.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Autoriser le remplacement du modèle des sous-agents par le plugin`},help:{"v1-1r5tzm1-4g":`Autorise explicitement ce plugin à demander le remplacement du fournisseur ou du modèle lors des exécutions de sous-agents en arrière-plan. Conservez la valeur false, sauf si le plugin est jugé fiable pour orienter la sélection du modèle.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Chargeur de plugins`},help:{"v1-1myjwbi-52":`Groupe de configuration du chargeur de plugins permettant de spécifier les chemins du système de fichiers où les plugins sont recherchés. Définissez explicitement les chemins de chargement et vérifiez-les pour éviter le chargement accidentel d’extensions non fiables.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Chemins de chargement des plugins`},help:{"v1-o689p1-4z":`Fichiers ou répertoires de plugins supplémentaires analysés par le chargeur en plus des emplacements intégrés par défaut. Utilisez des répertoires dédiés aux extensions et évitez les chemins trop larges contenant des exécutables sans rapport.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Emplacements des plugins`},help:{"v1-zx6crl-5f":`Sélectionne les plugins auxquels sont attribués des emplacements d’exécution exclusifs, comme la mémoire, afin qu’un seul plugin fournisse cette fonctionnalité. Attribuez explicitement les emplacements pour éviter que plusieurs fournisseurs se chevauchent avec des comportements contradictoires.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-tp8do7-h":`Identifiant du moteur de contexte`},help:{"v1-1ww2hr0-4h":`Sélectionne l’identifiant du moteur de contexte enregistré. Les plugins dont l’identifiant diffère de celui de leur moteur déclarent contextEngineIds dans leur manifeste afin qu’OpenClaw puisse charger le plugin correspondant.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Plugin de mémoire`},help:{"v1-6kb575-6d":`Sélectionnez le plugin de mémoire actif par son ID (par défaut : memory-core), ou "none" pour désactiver les plugins de mémoire. Le plugin sélectionné peut se charger même s’il ne figure pas dans plugins.allow ; plugins.deny et la désactivation explicite de chaque plugin restent prioritaires.`}},presence:{label:{"v1-10fdwo4-8":`Présence`}},proxy:{label:{"v1-ji57pa-d":`Proxy géré`},help:{"v1-vui6bx-58":`Routage via un proxy sortant géré par l’opérateur pour les connexions HTTP, HTTPS, WebSocket et les flux sortants bruts pris en charge lors de l’exécution d’OpenClaw. Utilisez cette option lorsque le contrôle centralisé du trafic sortant fait partie du périmètre de déploiement.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Proxy géré activé`},help:{"v1-1456xdw-49":`Remplacement explicite du paramètre d’activation du proxy géré. La présence d’une URL active le routage par défaut ; définissez la valeur sur false pour ignorer les URL de proxy configurées ou issues de l’environnement sans les supprimer.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Mode de bouclage du proxy géré`},help:{"v1-1kaiuh0-3c":`Contrôle le routage du plan de contrôle de Gateway via l’interface de bouclage lorsque le mode proxy géré est actif : "gateway-only", "proxy" ou "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL du proxy géré`},help:{"v1-p36b5l-3v":`URL du proxy de sortie géré. Utilisez http:// pour un proxy CONNECT non chiffré ou https:// lorsque la connexion au point de terminaison du proxy lui-même doit utiliser TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS du proxy géré`},help:{"v1-6i0vu-3q":`Paramètres TLS utilisés lors de la connexion au point de terminaison du proxy géré. Ces paramètres s’appliquent au TLS du proxy, et non au TLS de la destination après CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Fichier d’autorités de certification TLS du proxy géré`},help:{"v1-1ntzjia-2p":`Chemin dans le système de fichiers vers un ensemble personnalisé de certificats d’autorités de certification utilisé pour vérifier le certificat d’un point de terminaison HTTPS de proxy géré.`}},repositoryBranchPrefix:{label:{"v1-1sxh9u9-o":`Préfixe des branches du dépôt`},help:{"v1-10w2bot-41":`Préfixe des nouvelles branches de session du dépôt distant. La valeur par défaut est openclaw ; les branches utilisent <prefix>/<workspace GUID>. Les branches existantes restent inchangées.`}},secrets:{label:{"v1-1sihgpy-7":`Secrets`},help:{"v1-jgn0o9-2l":`Fournisseurs de références de secrets, comportement du stockage partagé et protection facultative du trafic sortant des sous-processus.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Proxy de sortie des secrets`},help:{"v1-1qfgid-4n":`Proxy sur l’interface de bouclage appartenant à Gateway, qui remplace les marqueurs de secrets du stockage partagé uniquement au moment de l’envoi des requêtes sortantes. Redémarrez Gateway après avoir modifié cette section, prise en compte au démarrage.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Hôtes autorisés du proxy de sortie des secrets`},help:{"v1-9ypodl-6t":`Liste d’autorisation facultative du trafic pour les requêtes et les tunnels CONNECT. Lorsqu’elle est définie, les destinations doivent figurer dans cette liste, dans une liaison d’hôte propre à un secret ou dans bypassHosts. Une liste vide n’autorise que les hôtes liés à un secret ou exemptés. Redémarrez le Gateway après toute modification.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Hôtes exemptés du proxy de sortie des secrets`},help:{"v1-1oiiomv-57":`Noms d’hôtes exacts utilisant des tunnels CONNECT aveugles authentifiés pour les clients avec épinglage de certificat. Les sentinelles restent chiffrées et entraînent un échec de l’authentification auprès du fournisseur au lieu d’exposer du texte en clair.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Proxy de sortie des secrets activé`},help:{"v1-u99b1i-2h":`Active la substitution des secrets en sortie pour les sous-processus d’agent hébergés par le Gateway. Valeur par défaut : false.`}},"security%2Eaudit":{label:{"v1-16w033o-e":`Audit de sécurité`}},"security%2Eaudit%2Esuppressions":{label:{"v1-1l4qjwk-i":`Exclusions de l’audit`},help:{"v1-1deyl5p-4f":`Constats d’audit de sécurité acceptés à exclure du résumé actif et de la liste des constats. Les constats correspondants restent disponibles sous suppressedFindings dans la sortie JSON.`}},"security%2Eaudit%2Esuppressions%2E*%2EcheckId":{label:{"v1-pfzkxp-e":`Identifiant du contrôle d’audit`}},"security%2Eaudit%2Esuppressions%2E*%2EdetailIncludes":{label:{"v1-ykrpzg-n":`Le détail du constat contient`}},"security%2Eaudit%2Esuppressions%2E*%2Ereason":{label:{"v1-1581z0k-i":`Motif de l’exclusion`}},"security%2Eaudit%2Esuppressions%2E*%2EtitleIncludes":{label:{"v1-18y11at-m":`Le titre du constat contient`}},"security%2EinstallPolicy":{label:{"v1-1dbuvhm-e":`Politique d’installation`}},"security%2EinstallPolicy%2Eenabled":{label:{"v1-bfdyp9-l":`Activer la politique d’installation`},help:{"v1-67yonn-4i":`Activer une commande locale de confiance définissant la politique d’installation et de mise à jour des compétences et des plugins. Si cette option est activée sans commande configurée, les cibles d’installation prises en charge sont bloquées.`}},"security%2EinstallPolicy%2Eexec":{label:{"v1-433033-m":`Commande de politique d’installation`},help:{"v1-1hyg77m-46":`Commande locale de confiance qui renvoie une décision d’installation "allow", "warn" ou "block". Indiquez un chemin absolu vers l’exécutable ; OpenClaw l’exécute sans shell.`}},"security%2EinstallPolicy%2Eexec%2Eargs":{label:{"v1-17c9br2-o":`Arguments de la commande de politique`}},"security%2EinstallPolicy%2Eexec%2Ecommand":{label:{"v1-l86c0l-h":`Exécutable de politique`}},"security%2EinstallPolicy%2Eexec%2Eenv":{label:{"v1-f7gtc3-s":`Variables d’environnement de la politique`}},"security%2EinstallPolicy%2Eexec%2EmaxOutputBytes":{label:{"v1-1jz3qk1-r":`Limite de sortie de la politique (octets)`}},"security%2EinstallPolicy%2Eexec%2EnoOutputTimeoutMs":{label:{"v1-bu8clf-o":`Délai d’inactivité de la politique (ms)`}},"security%2EinstallPolicy%2Eexec%2EpassEnv":{label:{"v1-uzu2wx-12":`Variables d’environnement héritées par la politique`}},"security%2EinstallPolicy%2Eexec%2Esource":{label:{"v1-wv29f-l":`Source de la commande de la politique`}},"security%2EinstallPolicy%2Eexec%2EtimeoutMs":{label:{"v1-i9ag7r-j":`Délai d’expiration de la politique (ms)`}},"security%2EinstallPolicy%2Eexec%2EtrustedDirs":{label:{"v1-1kkqbtr-q":`Répertoires de confiance de la politique`}},"security%2EinstallPolicy%2Etargets":{label:{"v1-ss3w1g-m":`Cibles de la politique d’installation`},help:{"v1-1ar6u6h-2v":`Appliquez la politique d’installation à "skill", à "plugin" ou aux deux. Omettez cette liste pour couvrir toutes les cibles prises en charge.`}},session:{label:{"v1-8yh9jr-7":`Session`},help:{"v1-j86s32-5d":`Paramètres globaux de routage, de réinitialisation, de politique de distribution et de maintenance des sessions régissant le comportement de l’historique des conversations. Conservez les valeurs par défaut, sauf si vous avez besoin de contraintes plus strictes en matière d’isolation, de conservation ou de distribution.`}},"session%2Ecommunication":{label:{"v1-133tjjf-u":`Paramètres par défaut de communication entre sessions`},help:{"v1-1y4eege-63":`Valeurs par défaut pour les nouveaux messages entre sessions. Chaque direction accepte always, ask ou never et utilise always par défaut. Les sessions héritent de ces valeurs jusqu’à ce qu’une personne choisisse de les remplacer ; les restrictions d’accès existantes restent applicables.`}},"session%2Ecommunication%2Ereceive":{label:{"v1-efg2gh-10":`Recevoir des messages d’autres sessions`},help:{"v1-t6w901-5q":`Valeur par défaut pour l’acceptation de nouveaux messages provenant d’autres sessions : always autorise les messages, ask exige une approbation humaine avant leur transmission au modèle ou le lancement de nouvelles tâches, et never les bloque. Cela ne modifie ni la visibilité de l’historique ni l’accès humain.`}},"session%2Ecommunication%2Esend":{label:{"v1-1chq2bl-v":`Envoyer des messages à d’autres sessions`},help:{"v1-92cfz7-65":`Valeur par défaut pour l’envoi de messages à d’autres sessions de sa propre initiative : always autorise les messages, ask exige une approbation humaine avant l’envoi, et never les bloque. Les réponses demandées et les communications autorisées dans le cadre de tâches déléguées conservent leurs autorisations existantes.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Portée des sessions de messages privés`},help:{"v1-ql362c-5l":`Portée des sessions de messages privés : "main" préserve la continuité, tandis que "per-peer", "per-channel-peer" et "per-account-channel-peer" renforcent l’isolation. Utilisez les modes isolés pour les boîtes de réception partagées ou les déploiements multicomptes.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Portée des sessions de groupe`},help:{"v1-1fdezx2-6i":`Portée des sessions de groupe/canal : "per-group" maintient les salons séparés tandis que la session principale de l’agent les surveille en arrière-plan, indépendamment de dmScope ; "main" fusionne le contexte des salons dans main et ne nécessite aucune surveillance. Utilisez "main" uniquement pour les salons de confiance.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Liens d’identité des sessions`},help:{"v1-4mwmyr-5k":`Associe les identités partagées à des identifiants de correspondants préfixés par le fournisseur afin que les utilisateurs équivalents soient regroupés dans un même fil de messages privés (exemple : telegram:123456). Utilisez ce paramètre lorsqu’une même personne apparaît sur plusieurs canaux ou comptes.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Clé de session principale`},help:{"v1-18p638h-3q":`Accepté mais ignoré : le suffixe de la session principale de chaque agent est toujours "main". Omettez ce champ ; la portée globale des sessions utilise "global" à la place.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Maintenance des sessions`},help:{"v1-hdyrb-68":`Paramètres de maintenance automatique du stockage des sessions : archivage des sessions de l’application, délai de suppression, nombre maximal d’entrées, conservation des archives de réinitialisation et nettoyage selon le budget disque. Commencez en mode warn pour observer les effets, puis passez à enforce une fois les seuils ajustés.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Délai avant archivage des sessions inactives du tableau de bord`},help:{"v1-1krn130-60":"Archive les sessions inactives démarrées dans l’application OpenClaw après cette durée (par exemple `7d`) afin qu’elles restent accessibles sans encombrer la liste des sessions actives. Définissez la valeur sur `false` ou `0` pour désactiver cet archivage automatique."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-ogfwwy-h":`Stockage à froid des conversations`},help:{"v1-kqjx1d-5m":`Déplace les conversations inactives vers des archives JSONL compressées tout en conservant les métadonnées de session. Les fichiers d’archive deviennent indispensables à l’historique et doivent être inclus dans les sauvegardes. Les modifications s’appliquent sans redémarrer Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Nombre de jours d’inactivité avant archivage`},help:{"v1-1f9pk9f-55":`Archive les conversations après ce nombre de jours d’inactivité (entier positif, 30 par défaut). Le travail en cours est protégé ; toute modification du seuil prend effet au prochain passage du processus d’arrière-plan, sans redémarrage de Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-17fys4q-v":`Archiver automatiquement les anciennes conversations`},help:{"v1-1sdhnti-5s":`Active l’archivage des conversations en arrière-plan (true par défaut). Définissez la valeur sur false pour désactiver les extractions futures. Un processus vérifie chaque minute si des conversations sont admissibles à l’archivage. Cette politique d’archivage est distincte de la suppression et du nettoyage lié au quota d’espace disque.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Seuil haut cible d’occupation disque des sessions`},help:{"v1-143vh09-7z":`Taille cible après le nettoyage lié au quota disque (seuil haut). La valeur par défaut est de 80 % de maxDiskBytes ; définissez-la explicitement pour mieux contrôler la récupération d’espace sur les disques à capacité limitée. Une valeur évaluée à zéro rétablit la valeur par défaut ; les valeurs négatives ne sont pas valides. Pour désactiver le quota, utilisez plutôt maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Quota disque maximal des sessions`},help:{"v1-ocx4rx-cl":'Budget d’espace disque physique par agent couvrant les fichiers SQLite principaux/WAL et les artefacts comptabilisés du répertoire des sessions (par exemple `500mb`). La valeur par défaut est `10gb` ; les données protégées peuvent maintenir l’utilisation au-dessus de la cible. En cas de dépassement, le mode warn signale la pression sur l’espace disque et le mode enforce supprime les anciens artefacts de réinitialisation/suppression, l’historique non référencé, puis les archives créées en raison du plafond d’entrées. Les archives manuelles, celles liées à la durée de conservation, aux sessions de l’application ou à la récupération, ainsi que les archives héritées restent protégées. Définissez la valeur sur `false`, `0` ou `"0"` pour désactiver cette limite.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Nombre maximal d’entrées de session`},help:{"v1-1w2egrh-7u":`Limite le nombre d’entrées de session non archivées (5000 par défaut). Les conversations persistantes admissibles dépassant cette limite sont archivées avec leur historique ; les entrées d’automatisation jetables sont supprimées. Les archives existantes ne sont pas comptabilisées dans ce plafond. Les entrées actives protégées restent comptabilisées et peuvent maintenir le stockage au-dessus de la limite.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Mode de maintenance des sessions`},help:{"v1-qhc707-7c":`Détermine si les politiques de purge et de quota d’espace disque font uniquement l’objet de signalements ("warn") ou sont effectivement appliquées ("enforce"). Conservez "warn" pendant le déploiement et passez à "enforce" après avoir validé des seuils sûrs. Le stockage à froid est activé par défaut et dispose de son propre paramètre de désactivation.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Conserver les sessions récentes`},help:{"v1-138q5wx-89":"Protège les sessions interactives actives au cours de cette période (par exemple `7d`) contre la suppression automatique de leur historique liée à l’âge, au nombre d’entrées ou au budget d’espace disque. Si ce paramètre n’est pas défini ou vaut `false`, la politique normale donnant la priorité aux éléments les plus anciens est conservée. Les lignes synthétiques d’exécution de modèle, de cron, de hook, de heartbeat, d’ACP et de sous-agent restent admissibles à un nettoyage limité."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Délai avant purge des sessions`},help:{"v1-1xn50w7-76":"Archive les conversations persistantes admissibles et supprime les entrées d’automatisation temporaires plus anciennes que cette durée (par défaut `30d` ; par exemple `12h`). Les conversations archivées conservent leur historique et peuvent être restaurées ; les conversations protégées ou routables restent actives."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Conservation des archives de réinitialisation de session`},help:{"v1-3rw301-7l":"Conservation des conversations archivées selon leur ancienneté (`*.reset.<timestamp>` et `*.deleted.<timestamp>`). Par défaut, les archives sont conservées jusqu’à ce que la limite d’espace disque impose leur suppression, en commençant par les plus anciennes ; définissez une durée (par exemple `30d`) pour activer la suppression selon le temps écoulé, ou `false` pour la désactiver explicitement."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Notifier Home lors de la création d’une session`},help:{"v1-14mr1ov-8m":`Mettre en file d’attente une notification système dans la session d’accueil de l’agent propriétaire lors de la création d’une session (par défaut : true). Les notifications incluent le titre et les métadonnées du créateur disponibles, et sont lues lors du prochain tour de la session d’accueil ou d’une automatisation planifiée. Définir sur false pour désactiver ; les brouillons, les sessions incognito et internes, ainsi que les exécutions cron planifiées sont exclus.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Politique de réinitialisation des sessions`},help:{"v1-1hmt7n3-6r":`Définit l’objet de politique de réinitialisation par défaut utilisé lorsqu’aucune dérogation propre à un type ou à un canal ne s’applique. Par défaut, les sessions ne se réinitialisent pas automatiquement ; configurez une réinitialisation quotidienne ou après inactivité pour l’activer. /new et /reset restent disponibles à tout moment.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Heure de réinitialisation quotidienne des sessions`},help:{"v1-wry8cv-59":`Définit l’heure locale (0-23) de réinitialisation en mode quotidien, afin que les sessions se renouvellent à des heures prévisibles. À utiliser avec mode=daily et à régler selon le fuseau horaire attendu par l’opérateur pour un comportement facile à comprendre.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Délai d’inactivité avant réinitialisation des sessions, en minutes`},help:{"v1-1kzj0id-5e":`Définit la période d’inactivité avant réinitialisation en mode inactivité et peut également servir de garde-fou supplémentaire en mode quotidien. Utilisez des valeurs plus élevées pour préserver la continuité, ou plus faibles pour des fils de discussion plus récents et de courte durée.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Mode de réinitialisation des sessions`},help:{"v1-e5ie4w-5b":`Sélectionne la stratégie de réinitialisation : "none" désactive la réinitialisation automatique (par défaut), "daily" réinitialise à une heure configurée et "idle" réinitialise après une période d’inactivité. /new et /reset restent disponibles dans tous les modes.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Réinitialisation des sessions par canal`},help:{"v1-1uxsulx-5h":`Définit des règles de réinitialisation propres à chaque canal, indexées par identifiant de fournisseur/canal, pour un contrôle précis du comportement. À utiliser uniquement lorsqu’un canal nécessite un comportement de réinitialisation particulier, au-delà des règles définies par type.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Réinitialisation des sessions par type de discussion`},help:{"v1-ypdr7u-52":`Remplace le comportement de réinitialisation selon le type de discussion (directe, de groupe, en fil) lorsque les paramètres par défaut ne suffisent pas. À utiliser lorsque l’activité des groupes ou des fils nécessite une fréquence de réinitialisation différente de celle des messages directs.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Réinitialisation des sessions (discussion directe)`},help:{"v1-22e702-54":`Définit la politique de réinitialisation des conversations directes et remplace la configuration de base session.reset pour ce type. Utilisez ce paramètre comme réglage prioritaire actuel pour les messages directs, plutôt que l’ancien alias dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Réinitialisation des sessions (groupe)`},help:{"v1-hl1200-4u":`Définit la règle de réinitialisation des sessions de discussion de groupe, dont la continuité et le volume de messages parasites diffèrent de ceux des messages directs. Utilisez des délais d’inactivité plus courts pour les groupes actifs si la dérive du contexte devient problématique.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Réinitialisation des sessions (fil)`},help:{"v1-1hgpeke-4w":`Définit la règle de réinitialisation des sessions limitées à un fil, y compris pour les flux de travail centrés sur un fil de canal. À utiliser lorsque les sessions de fil doivent expirer plus vite ou plus lentement que les autres types de discussion.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Déclencheurs de réinitialisation de session`},help:{"v1-rcabsw-5a":`Répertorie les déclencheurs qui imposent une réinitialisation de session lorsqu’ils sont détectés dans les messages entrants. Utilisez-les avec parcimonie pour des expressions de réinitialisation explicites, afin de ne pas perdre le contexte de manière inattendue au cours d’une conversation normale.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Portée des sessions`},help:{"v1-axt4ds-5z":`Définit la stratégie de base de regroupement des sessions : "per-sender" isole les sessions par expéditeur et "global" partage une session par contexte de canal. Conservez "per-sender" pour un fonctionnement multi-utilisateur plus sûr, sauf si un contexte partagé est expressément requis.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Politique d’envoi des sessions`},help:{"v1-17zdvww-61":`Contrôle la distribution des messages de session à l’aide de règles allow/deny évaluées selon le canal, chatType et les préfixes de clés. Ce mécanisme est distinct de l’admission des messages entrants et sortants entre sessions ; utilisez session.communication pour définir ces valeurs par défaut.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Action par défaut de la politique d’envoi des sessions`},help:{"v1-15plhut-53":`Définit l’action de repli lorsqu’aucune règle sendPolicy ne correspond : "allow" ou "deny". Conservez "allow" pour les configurations simples, ou choisissez "deny" si vous exigez des règles d’autorisation explicites pour chaque destination.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Règles de la politique d’envoi des sessions`},help:{"v1-o217za-5h":'Règles ordonnées d’autorisation ou de refus évaluées avant l’action par défaut, par exemple `{ action: "deny", match: { channel: "discord" } }`. Placez les règles les plus spécifiques en premier afin que les règles générales ne masquent pas les exceptions.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Action de la règle d’envoi des sessions`},help:{"v1-178vm80-54":`Définit la décision de la règle sur "allow" ou "deny" lorsque les critères de correspondance associés sont satisfaits. Placez les règles de refus en premier pour imposer des limites strictes avec des exceptions d’autorisation explicites.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Critères de correspondance de la règle d’envoi de session`},help:{"v1-18qh5qg-5d":`Définit des conditions de correspondance facultatives pour la règle, pouvant combiner des contraintes de channel, de chatType et de préfixe de clé. Utilisez des critères précis pour que l’intention de la politique reste lisible et que le débogage reste simple.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Canal de la règle d’envoi de session`},help:{"v1-u5erwx-50":`Applique la règle à un identifiant de canal ou de fournisseur spécifique (par exemple discord, telegram, slack). Utilisez ce critère lorsqu’un canal doit autoriser ou refuser la remise indépendamment des autres.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Type de conversation de la règle d’envoi de session`},help:{"v1-7cv4f9-4z":`Applique la règle selon le type de conversation (direct, group, thread) afin d’adapter le comportement à la forme de la conversation. Utilisez ce critère lorsque les messages privés et les groupes nécessitent des limites de sécurité différentes.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Préfixe de clé de la règle d’envoi de session`},help:{"v1-ac4dee-5n":`Vérifie la correspondance avec un préfixe de clé de session normalisé après les étapes internes de normalisation des clés dans les composants qui utilisent la politique. Utilisez ce critère pour les contrôles généraux par préfixe et privilégiez rawKeyPrefix lorsqu’une correspondance exacte avec la clé complète est requise.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Préfixe de clé brute de la règle d’envoi de session`},help:{"v1-1g9w044-5e":`Correspond au préfixe brut, non normalisé, de la clé de session pour cibler précisément les clés complètes dans les politiques. Utilisez cette option lorsque le keyPrefix normalisé est trop large et que vous avez besoin d’un ciblage précis par préfixe d’agent ou par transport.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Modes de partage des sessions`},help:{"v1-xbh52d-5a":`Détermine les modes de collaboration que les propriétaires de sessions et les administrateurs peuvent sélectionner. Les booléens omis sont activés par défaut ; définissez un mode sur false pour le retirer du sélecteur et empêcher toute nouvelle sélection.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Autoriser les sessions en brouillon`},help:{"v1-1lzap27-2p":`Autorise la visibilité en mode brouillon, qui masque les sessions aux opérateurs qui ne sont ni propriétaires ni administrateurs. Valeur par défaut : true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Autoriser les sessions en lecture seule`},help:{"v1-upl3nu-21":`Permet de rendre les sessions accessibles en lecture seule aux non-participants. Valeur par défaut : true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Autoriser les sessions en mode suggestion`},help:{"v1-4i8owu-4g":`Autorise la visibilité en mode suggestion. À ce stade, ce mode applique la même politique d’accès que la lecture seule ; les files de suggestions seront configurées par une fonctionnalité ultérieure. Valeur par défaut : true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Chemin de stockage des sessions`},help:{"v1-hreznz-56":`Définit le chemin du fichier de stockage des sessions utilisé pour conserver les enregistrements de session entre les redémarrages. N’utilisez un chemin explicite que si vous avez besoin d’une organisation personnalisée du disque, d’un routage des sauvegardes ou d’un stockage sur un volume monté.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Associations des fils de discussion aux sessions`},help:{"v1-zbzihu-4s":`Paramètres par défaut communs pour la création et le routage des sessions liées à un fil sur les canaux pris en charge. Configurez ici les paramètres globaux par défaut et ne les remplacez pour un canal que si son comportement diffère.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Contexte de création dans un fil`},help:{"v1-gnhqsg-46":`Contexte natif par défaut des sous-agents créés dans un fil de discussion. Utilisez "fork" pour partir de la conversation du demandeur ou "isolated" pour créer un sous-agent avec un contexte vierge. Valeur par défaut : "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Liaison aux fils activée`},help:{"v1-foomtc-3f":`Interrupteur général pour la création, le routage et la distribution des sessions liées à un fil. Désactivez-le pour désactiver globalement la liaison aux fils.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Délai d’inactivité de la liaison aux fils (heures)`},help:{"v1-gffnx3-3h":`Délai d’inactivité par défaut, en heures, des sessions liées à un fil pour tous les fournisseurs et canaux (0 désactive l’expiration pour inactivité). Par défaut : 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Durée maximale de la liaison aux fils (heures)`},help:{"v1-1xfcyhw-39":`Durée de vie maximale absolue facultative, en heures, des sessions liées à un fil pour tous les fournisseurs et canaux (0 désactive cette limite). Par défaut : 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Création de sessions liées à un fil`},help:{"v1-1lqwbdl-46":`Autorisation globale par défaut de créer des sessions de travail liées à un fil via sessions_spawn et les créations de fils ACP. Par défaut : true lorsque les liaisons aux fils sont activées.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Cibles autorisées des liens symboliques de compétences`},help:{"v1-xzybiq-4t":`Racines cibles réelles de confiance vers lesquelles les liens symboliques des compétences peuvent pointer lorsqu’elles se trouvent hors de leur racine source configurée. Limitez cette liste, par exemple à un répertoire de compétences dans un dépôt voisin.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Répertoires de compétences supplémentaires`},help:{"v1-11o7opu-53":`Racines de compétences partagées supplémentaires à analyser avec la priorité la plus basse. Utilisez cette option pour les dépôts voisins ou les packs de compétences partagés qui doivent être disponibles sans être copiés dans l’espace de travail OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Surveiller les Skills`},help:{"v1-1g8a3b0-8g":`Active la découverte des compétences déclenchée par le système de fichiers, avec une nouvelle analyse de sécurité toutes les 30 minutes pour détecter les événements manqués. Si ce paramètre est désactivé, les modifications explicites des compétences OpenClaw, les changements de configuration pertinents et le démarrage de Gateway continuent d’actualiser immédiatement les compétences. Les sessions existantes utilisent les instantanés modifiés au prochain tour de l’agent.`}},storage:{label:{"v1-eop0jq-7":`Stockage`},help:{"v1-j0mwbg-4w":`Emplacements de stockage réutilisables pour les artefacts OpenClaw. Le cœur du système de stockage gère l’identité des emplacements, le chiffrement et leur état de fonctionnement ; les fournisseurs transportent les objets et les consommateurs décident de ce qu’il faut conserver.`}},"storage%2Elocations":{label:{"v1-uok3ae-h":`Emplacements de stockage`},help:{"v1-1ipmwky-5k":`Destinations de stockage nommées. Les noms contiennent de 1 à 63 lettres minuscules, chiffres ou traits d’union et commencent par une lettre ou un chiffre. Chaque destination conserve un marqueur d’initialisation que les opérations d’écriture à l’exécution ne créent jamais.`}},"storage%2Elocations%2E*":{label:{"v1-1pbn8xd-g":`Emplacement de stockage`},help:{"v1-7yhxyl-4n":`Une destination de stockage nommée avec les paramètres du fournisseur et un choix explicite de chiffrement. Initialisez une nouvelle destination avec openclaw storage init avant d’y écrire des objets.`}},"storage%2Elocations%2E*%2Eencryption":{label:{"v1-1qp46kf-i":`Chiffrement du stockage`},help:{"v1-19oj6cx-6d":`Choix de chiffrement obligatoire : un objet contenant une phrase secrète chiffre les objets avant leur envoi ; "none" désactive explicitement le chiffrement. Les sauvegardes peuvent contenir des identifiants, utilisez donc "none" uniquement lorsque la destination offre déjà une protection adaptée.`}},"storage%2Elocations%2E*%2Eencryption%2Epassphrase":{label:{"v1-1x3jq0t-t":`Phrase secrète de chiffrement du stockage`},help:{"v1-1o63v7d-4o":`Phrase secrète utilisée pour chiffrer cet emplacement. Privilégiez une SecretRef et conservez une copie récupérable : la perte ou la modification de la phrase secrète rend les objets chiffrés existants illisibles.`}},"storage%2Elocations%2E*%2Eprovider":{label:{"v1-1dujppr-g":`Fournisseur de stockage`},help:{"v1-16srbor-3w":`Identifiant du fournisseur de stockage, par exemple « filesystem ». Référencer un fournisseur intégré active automatiquement son plugin, sauf si la politique des plugins le désactive.`}},"storage%2Elocations%2E*%2Esettings":{label:{"v1-268wio-p":`Paramètres du fournisseur de stockage`},help:{"v1-drbso5-5t":`Paramètres JSON de portée limitée, gérés par le fournisseur. Les valeurs contenant des secrets doivent utiliser des objets SecretRef, que le fournisseur ne résout qu’en cas de besoin. Le fournisseur filesystem nécessite un chemin absolu vers un répertoire existant.`}},surfaces:{label:{"v1-exl2ye-g":`Politiques des surfaces`},help:{"v1-vgtjbs-50":`Remplacements de la politique de messages par surface, indexés par l’identifiant résolu de la surface de distribution. À utiliser uniquement lorsqu’une surface déployée nécessite une gestion des réponses silencieuses plus stricte que celle définie par défaut pour l’agent.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Politique de réponse silencieuse de la surface`},help:{"v1-1un880p-4z":`Remplace la politique de réponse silencieuse des groupes pour une surface de diffusion résolue donnée. Les champs non définis héritent de agents.defaults.silentReply. Les conversations directes et les sessions internes nécessitent toujours une réponse.`}},talk:{label:{"v1-15ukbjj-4":`Conversation`},help:{"v1-1gx10xa-5g":`Paramètres de synthèse vocale du mode Talk : identité vocale, sélection du modèle, format de sortie et comportement d’interruption. Utilisez cette section pour ajuster l’expérience vocale des utilisateurs tout en maîtrisant la latence et les coûts.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Agent Talk`},help:{"v1-iee5l9-2b":`Agent auquel appartiennent les sessions Talk créées sans clé de session explicitement liée à un agent.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Mode rapide des consultations Talk`},help:{"v1-syf3xk-2o":`Permet de définir le mode rapide sur true ou false pour l’exécution standard de l’agent qui sous-tend les consultations en temps réel de Talk.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Niveau de réflexion des consultations Talk`},help:{"v1-1ft5njw-2o":`Permet de remplacer le niveau de réflexion pour l’exécution standard de l’agent qui sous-tend les consultations en temps réel de Talk.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Interruption à la prise de parole dans Talk`},help:{"v1-8n9q4o-3l":`Si la valeur est true (par défaut), interrompt la parole de l’assistant lorsque l’utilisateur commence à parler en mode Talk. Laissez cette option activée pour permettre l’alternance des tours de parole.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Fournisseur actif de Talk`},help:{"v1-wgnxhg-1g":`Identifiant du fournisseur actif de Talk (par exemple "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Paramètres des fournisseurs de Talk`},help:{"v1-oh0yuv-30":`Paramètres Talk propres à chaque fournisseur, indexés par identifiant de fournisseur. Lors de la migration, privilégiez ces paramètres plutôt que les anciennes clés talk.*.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Configuration du fournisseur de Talk`},help:{"v1-36pblg-1r":`Champs de configuration Talk gérés par le fournisseur correspondant à cet identifiant.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Clé API du fournisseur de Talk`},help:{"v1-1a1p9wp-v":`Clé API du fournisseur pour le mode Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk en temps réel`},help:{"v1-c2re7j-3z":`Fournisseur, modèle, voix, mode, transport et stratégie de raisonnement de Talk en temps réel. Conservez la configuration du fournisseur de parole et de synthèse vocale dans talk.provider et talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Raisonnement de Talk en temps réel`},help:{"v1-opsatw-37":`Stratégie de raisonnement de Talk : agent-consult pour l’aide d’un agent via Gateway, direct-tools pour les appels d’outils locaux, ou none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Routage des consultations de Talk en temps réel`},help:{"v1-10qjcvk-5f":`Relais de secours via Gateway pour les transcriptions finales de l’utilisateur lorsque le fournisseur temps réel n’appelle pas openclaw_agent_consult. provider-direct conserve les réponses du fournisseur ; force-agent-consult passe par OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Instructions de Talk en temps réel`},help:{"v1-1jaaj84-5p":`Instructions système supplémentaires ajoutées au prompt intégré d’OpenClaw pour Talk en temps réel. Utilisez-les pour définir le style de voix, le ton et les autres comportements en temps réel du fournisseur, tout en conservant les consignes agent-consult.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Mode de Talk en temps réel`},help:{"v1-1u2xui1-1l":`Mode d’exécution de Talk : realtime, stt-tts ou transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Modèle de Talk en temps réel`},help:{"v1-amou5a-27":`Remplacement de l’identifiant du modèle du fournisseur temps réel pour les sessions Talk dans le navigateur ou gérées par Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Marge audio initiale de Talk en temps réel (ms)`},help:{"v1-1cwg07n-22":`Durée en millisecondes de l’audio conservé avant la détection d’une activité vocale en temps réel.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Fournisseur de Talk en temps réel`},help:{"v1-wwsmpt-1o":`Identifiant du fournisseur vocal en temps réel actif, comme openai ou google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Paramètres des fournisseurs Talk en temps réel`},help:{"v1-ruagcu-1r":`Paramètres vocaux en temps réel propres à chaque fournisseur, indexés par identifiant de fournisseur.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Configuration du fournisseur Talk en temps réel`},help:{"v1-edfpxm-1u":`Configuration vocale en temps réel propre au fournisseur correspondant à cet identifiant.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Clé API du fournisseur Talk en temps réel`},help:{"v1-1fbmgpx-z":`Clé API du fournisseur pour Talk en temps réel.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Effort de raisonnement de Talk en temps réel`},help:{"v1-157xd3e-2t":`Effort de raisonnement propre au fournisseur pour les sessions Talk en temps réel, comme minimal, low, medium ou high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Durée de silence de Talk en temps réel (ms)`},help:{"v1-1grnu06-1y":`Nombre de millisecondes de silence avant la validation d’un tour de parole de l’utilisateur dans Talk en temps réel.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Voix du locuteur de Talk en temps réel`},help:{"v1-1kgb166-2h":`Nom de voix du locuteur remplaçant celui du fournisseur en temps réel pour les sessions Talk gérées par le navigateur ou le Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Identifiant de voix du locuteur de Talk en temps réel`},help:{"v1-1k8w6vk-2f":`Identifiant de voix du locuteur remplaçant celui du fournisseur en temps réel pour les sessions Talk gérées par le navigateur ou le Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Transport de Talk en temps réel`},help:{"v1-2otjgn-2g":`Transport des octets/sessions de Talk : webrtc, provider-websocket, gateway-relay ou managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Seuil VAD en temps réel de Talk`},help:{"v1-nf5l2t-2j":`Seuil de détection de l’activité vocale en temps réel, de 0 (sensibilité maximale) à 1 (sensibilité minimale).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Délai de silence de Talk (ms)`},help:{"v1-1kim32f-59":`Durée du silence de l’utilisateur, en millisecondes, avant que le mode Talk ne finalise et n’envoie la transcription en cours. Laissez ce champ non défini pour conserver la durée de pause par défaut de la plateforme (700 ms sur macOS et Android, 900 ms sur iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Paramètre régional de reconnaissance vocale de Talk`},help:{"v1-1un3x4l-4c":`Identifiant de paramètre régional BCP 47 pour la reconnaissance vocale de Talk sur les nœuds d’appareils et le recours à la voix système d’iOS, par exemple "ru-RU". Laissez ce champ non défini pour utiliser la valeur par défaut de chaque appareil.`}},telemetry:{label:{"v1-sqprmo-9":`Télémétrie`},help:{"v1-1o5tru3-55":`Consentement explicite à l’envoi de statistiques anonymes sur les fonctionnalités lors de la vérification quotidienne des mises à jour. Ces statistiques sont désactivées par défaut et ne contiennent jamais de messages, d’informations d’authentification ni d’identifiants.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Horodatage du consentement aux statistiques sur les fonctionnalités`},help:{"v1-1t051az-3t":`Horodatage ISO indiquant quand l’opérateur a accepté ou refusé les statistiques anonymes sur les fonctionnalités. Évite que l’assistant de configuration ne pose à nouveau la question.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Statistiques anonymes sur les fonctionnalités`},help:{"v1-1ptrwuq-4r":`Partage les noms des canaux et des fournisseurs activés, le nombre de plugins et le nombre de sessions récentes lors de la vérification quotidienne des mises à jour. Désactivé par défaut et toujours désactivé lorsque DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Outils`},help:{"v1-1el54kl-5h":`Infrastructure des outils et paramètres par défaut inter-agents. Les sections de même niveau à la racine gèrent l’infrastructure et les paramètres par défaut inter-agents ; agents.defaults gère le comportement de la boucle des agents ; les entrées des agents peuvent remplacer les uns comme les autres lorsque cela est pris en charge.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Accès aux outils entre agents`},help:{"v1-1ynpa5f-cf":`Politique des appels d’outils de session inter-agents : envois, liste, historique, recherche et lecture des états (activés par défaut). Utilisez allow pour restreindre les paires d’agents ; enabled=false bloque l’accès inter-agents ordinaire. Les sessions de sous-agents natifs et les sessions enfants ACP appartenant au demandeur restent accessibles avec la visibilité tree ou all. Pour une séparation stricte, définissez tools.sessions.visibility sur agent ou self (tree autorise toujours les enfants natifs/ACP appartenant au demandeur), ou utilisez des passerelles distinctes.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Liste des cibles autorisées pour les appels inter-agents`},help:{"v1-1jt2ari-76":`Identifiants d’agents ou motifs avec * pouvant participer aux appels inter-agents ; l’agent demandeur et l’agent cible doivent tous deux correspondre. L’accès inter-agents est activé par défaut, et une valeur allow omise ou vide autorise toutes les paires. Définissez une liste explicite pour restreindre l’accès ; les entrées vides refusent l’accès.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Activer l’outil inter-agents`},help:{"v1-w950oq-ba":`Active l’accès aux outils de session inter-agents (par défaut : true) ; une valeur allow omise ou vide autorise toutes les paires d’agents. Définissez la valeur sur false pour bloquer l’accès inter-agents ordinaire ; les sessions de sous-agents natifs et les sessions enfants ACP appartenant au demandeur restent accessibles avec la visibilité tree ou all. Pour une séparation stricte, définissez tools.sessions.visibility sur agent ou self (tree autorise toujours les enfants natifs/ACP appartenant au demandeur), ou utilisez des passerelles distinctes.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Liste des outils autorisés`},help:{"v1-1is3eaq-4v":`Liste absolue d’outils autorisés qui remplace les valeurs par défaut issues du profil dans les environnements stricts. À utiliser uniquement si vous souhaitez limiter les fonctionnalités des outils à un sous-ensemble soigneusement sélectionné.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Ajouts à la liste d’outils autorisés`},help:{"v1-1xw9zp8-57":`Entrées supplémentaires de la liste d’outils autorisés, ajoutées au profil d’outils sélectionné et à la politique par défaut. Gardez cette liste courte et explicite pour que les audits puissent rapidement identifier les exceptions intentionnelles à la politique.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Politique des outils par fournisseur`},help:{"v1-c1lj2f-bh":`Règles d’autorisation et de refus des outils propres à chaque fournisseur, indexées par ID de canal/fournisseur, pour adapter les fonctionnalités à chaque interface. Utilisez-les lorsqu’un fournisseur nécessite des contrôles plus stricts que la politique globale relative aux outils. exec.mode définit un plafond d’exécution sur l’hôte qui ne peut que renforcer les restrictions pour les tours de conversation sur ce fournisseur ou cette combinaison fournisseur/modèle (il ne supprime jamais les approbations obligatoires et n’assouplit jamais un mode plus strict). Ainsi, le mode "auto" soumet uniquement les exécutions de ce modèle non couvertes par les autorisations à l’évaluateur d’exécution.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Mode Code`},help:{"v1-1ecc39k-6k":'Mode code générique d’OpenClaw. En l’absence de configuration globale, la valeur par défaut est `"auto"` ; un objet explicitement défini sans `enabled` reste désactivé. Les exécutions d’agent pour lesquelles ce mode est activé exposent uniquement `exec` et `wait` au modèle et accèdent aux outils habituels via la passerelle du catalogue.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Activer le mode code`},help:{"v1-c7oqjw-ah":'Activation globale d’OpenClaw Code Mode. Si le paramètre global est totalement absent, la valeur par défaut est `"auto"` ; un objet défini sans `enabled` reste désactivé. `"auto"` active le mode pour les modèles privilégiés du catalogue, tandis que `true` l’active pour les exécutions prenant en charge les outils. Les réglages d’activation propres à l’agent et au modèle sont prioritaires. Une exécution pour laquelle le mode est activé est bloquée si l’environnement d’exécution est indisponible, au lieu d’exposer la liste complète des outils.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Exécuteur du mode code`},help:{"v1-4tbmdg-7h":`Exécuteur JavaScript : "node" (par défaut) utilise Node vm pour le code de confiance et ne constitue pas un bac à sable de sécurité ; "quickjs" utilise le plugin QuickJS WASM intégré pour une exécution renforcée du code invité. Les autorisations des outils s’appliquent aux deux. Code Mode ne peut pas fonctionner si l’exécuteur sélectionné est indisponible.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Limite de sortie du mode code`},help:{"v1-1hmij9q-1n":`Nombre maximal d’octets sérialisés renvoyés par la sortie du mode code.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Limite d’appels d’outils en attente en mode code`},help:{"v1-3b5tyd-2i":`Nombre maximal d’appels d’outils imbriqués simultanés qu’une machine virtuelle en mode code peut lancer avant de devoir reprendre son exécution ultérieurement.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Nombre maximal de résultats de recherche en mode code`},help:{"v1-1gpue5r-28":`Nombre maximal de résultats de recherche dans le catalogue masqué qu’un programme en mode code peut demander.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Limite de taille des instantanés en mode code`},help:{"v1-1mmgkqy-1x":`Nombre maximal d’octets sérialisés conservés pour un instantané QuickJS suspendu.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Limite de mémoire en mode code`},help:{"v1-xetora-6n":`Limite du tas de l’environnement invité QuickJS ou budget du tas V8 du worker Node appliqué dans la mesure du possible, en octets. La surcharge de l’environnement d’exécution Node et les allocations minimales du moteur influent sur le budget effectif ; les tampons externes et la mémoire résidente (RSS) du processus sont exclus. Cela ne constitue pas une garantie de sécurité.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Interface du mode code`},help:{"v1-dsp2b9-2x":'Interface accessible au modèle. Seule la valeur "only" est prise en charge : expose `exec` et `wait` du mode code et masque les outils habituels.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Nombre de résultats de recherche par défaut du mode code`},help:{"v1-1io42lu-2m":"Nombre par défaut de résultats de recherche dans le catalogue masqué renvoyés par `catalog.search` en mode code."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`Durée de validité des instantanés du mode code`},help:{"v1-1nxfczz-28":"Durée pendant laquelle les exécutions suspendues de Code Mode peuvent être reprises avec `wait` avant leur expiration."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Délai d’expiration du mode code`},help:{"v1-8csycm-1p":"Durée maximale en millisecondes pour un appel `exec` ou `wait` en mode code."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Liste des outils interdits`},help:{"v1-wilr1b-4p":`Liste globale des outils interdits, qui bloque les outils répertoriés même lorsque les règles du profil ou du fournisseur les autoriseraient. Utilisez des règles d’interdiction pour les blocages d’urgence et la défense en profondeur à long terme.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Accès privilégié aux outils`},help:{"v1-ehcm0r-5a":`Contrôles d’accès privilégié aux outils pour les interfaces de commande privilégiées, qui ne doivent être accessibles qu’aux expéditeurs de confiance. Laissez cet accès désactivé, sauf si les procédures de l’opérateur nécessitent explicitement des actions privilégiées.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Règles d’autorisation des outils privilégiés`},help:{"v1-1u9bhih-54":`Règles d’autorisation des expéditeurs pour les outils privilégiés, généralement indexées selon les formats d’identité du canal ou du fournisseur. Utilisez des identités précises et explicites afin que les commandes privilégiées ne puissent pas être déclenchées par des utilisateurs non prévus.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Activer l’accès privilégié aux outils`},help:{"v1-1n8oyal-4l":`Active le mode d’exécution privilégiée des outils lorsque les vérifications de l’expéditeur et des politiques sont satisfaites. Laissez cette option désactivée dans les canaux publics ou partagés et activez-la uniquement dans des contextes de confiance gérés par le propriétaire.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Outil exec`},help:{"v1-p5piic-56":`Ensemble des politiques de l’outil exec concernant l’hôte d’exécution shell, le mode de sécurité, le comportement d’approbation et les liaisons d’exécution. Conservez des valeurs par défaut prudentes en production et renforcez les restrictions sur les modes d’exécution privilégiée.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Liste des modèles autorisés pour apply_patch`},help:{"v1-4q5ovf-1x":`Liste facultative d’identifiants de modèles autorisés (par exemple "gpt-5.4" ou "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Activer apply_patch`},help:{"v1-1erkir4-31":`Activer ou désactiver apply_patch pour les modèles OpenAI et OpenAI Codex lorsque la politique d’utilisation des outils l’autorise (valeur par défaut : true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch limité à l’espace de travail`},help:{"v1-1m4u5cn-4l":`Limiter les chemins utilisés par apply_patch sur l’hôte au répertoire de l’espace de travail (par défaut : false). Définissez cette option sur true pour limiter l’accès à l’espace de travail ; les répertoires racines requis et les restrictions de session continuent de s’appliquer.`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Délai de notification d’exécution après approbation d’exec (ms)`},help:{"v1-1gwwann-4z":`Délai en millisecondes avant d’afficher une notification d’exécution en cours après l’approbation d’exec. Augmentez-le pour réduire le clignotement lors des commandes rapides, ou diminuez-le pour informer plus rapidement l’opérateur.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Demande d’approbation d’exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Mise en évidence des commandes exec`},help:{"v1-kyxd4o-4n":`Afficher la mise en évidence des commandes issue de l’analyseur dans les demandes d’approbation d’exec (valeur par défaut : false). Activez cette option pour mettre en évidence le texte des commandes sans modifier la politique d’approbation d’exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Expiration des autorisations permanentes (jours)`},help:{"v1-5uxe2j-6r":`Durée de validité par défaut, en jours (1-3650), des autorisations permanentes créées par allow-always lors des approbations d’automatisations. Si cette valeur n’est pas définie, les autorisations restent valides jusqu’à leur révocation ou à la modification de l’automatisation à laquelle elles appartiennent. Les conditions sont figées à la création : toute modification de cette valeur ne concerne donc que les autorisations futures.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Cible d’exec`},help:{"v1-rno1mf-5q":`Sélectionne la stratégie de ciblage de l’exécution des commandes shell. Utilisez "auto" pour un comportement adapté à l’environnement d’exécution (sandbox si disponible, sinon gateway), ou définissez explicitement sandbox/gateway/node si vous avez besoin d’un environnement fixe.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Mode d’exécution`},help:{"v1-1qscgnt-5q":`Sélecteur normalisé de politique d’exécution. Utilisez "auto" pour faire examiner par un classificateur les demandes sans approbation correspondante, "ask" pour les faire examiner par une personne, "allowlist" pour les commandes approuvées par des règles fixes, ou "full" pour un fonctionnement local de confiance.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Liaison au nœud d’exécution`},help:{"v1-rfnz54-4s":`Configuration de la liaison aux nœuds pour les outils d’exécution lorsque l’exécution des commandes est déléguée à des nœuds connectés. N’utilisez une liaison explicite à un nœud que si un routage multinœud est nécessaire.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Notification à la fin de l’exécution`},help:{"v1-eyedrx-3r":`Si la valeur est true (par défaut), la fin des sessions exec en arrière-plan et les événements du cycle de vie exec des nœuds mettent en file d’attente un suivi pour la session d’origine.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Notification en cas de réussite sans sortie`},help:{"v1-l4v70o-6g":`Lorsque cette option est définie sur true (valeur par défaut), les exécutions exec en arrière-plan qui se terminent avec succès sans produire de sortie réveillent tout de même la session d’origine, afin qu’une tâche en attente silencieuse signale sa fin. Définissez cette option sur false pour ne pas signaler les réussites silencieuses ; l’agent les récupère alors avec process poll.`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Ajout en tête du PATH d’exécution`},help:{"v1-s1aimc-1r":`Répertoires à ajouter en tête de PATH pour les exécutions (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Responsable de l’examen des exécutions`},help:{"v1-12y548k-4x":`Évaluateur d’exécution basé sur un modèle, utilisé en mode automatique avant de recourir à une approbation humaine. Configurez ici un modèle de remplacement dédié si vous souhaitez isoler l’évaluation des exécutions du modèle de l’agent principal.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Mode rapide de l’évaluateur d’exécution`},help:{"v1-175bx14-8u":`Mode rapide facultatif pour l’examen des demandes d’approbation dans OpenClaw : true demande un traitement prioritaire sur les routes OpenAI Responses et ChatGPT/OAuth compatibles ; false demande un traitement standard. Omettez ce paramètre pour conserver les valeurs par défaut du fournisseur. Le mode rapide peut coûter plus cher et dépend de la disponibilité du fournisseur. Ne configure pas Codex Guardian natif.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Modèle de l’évaluateur d’exécution`},help:{"v1-1lltiy5-3i":`Remplacement facultatif du fournisseur/modèle pour l’agent d’évaluation des exécutions. Laissez ce champ vide pour réutiliser le modèle principal configuré pour l’agent cible.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Réflexion de l’évaluateur d’exécution`},help:{"v1-yg2gby-6u":`Effort de raisonnement facultatif pour l’examen des demandes d’approbation par un modèle dans OpenClaw : minimal, low, medium, high, xhigh ou max. Omettez ce paramètre pour conserver les valeurs par défaut du fournisseur. Les niveaux pris en charge sont normalisés pour le modèle sélectionné. Ne configure pas Codex Guardian natif.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Délai d’expiration de l’évaluateur d’exécution (ms)`},help:{"v1-1o30chi-3w":`Délai d’expiration par étape de l’évaluateur d’exécution, en millisecondes, pour la préparation du modèle et la génération de sa réponse avant de recourir à une approbation humaine (par défaut : 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Profils des exécutables sûrs`},help:{"v1-4cdcwe-29":`Profils de sécurité facultatifs par exécutable (limites des arguments positionnels + options autorisées/interdites).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Exécutables sûrs`},help:{"v1-1of1m2s-21":`Autoriser l’exécution de binaires sûrs utilisant uniquement stdin sans entrée explicite dans la liste d’autorisation.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Répertoires de confiance des exécutables sûrs`},help:{"v1-zljbcn-2v":`Répertoires supplémentaires explicitement déclarés comme fiables pour la vérification des chemins des exécutables sûrs (les entrées de PATH ne sont jamais automatiquement considérées comme fiables).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Sécurité d’exécution`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Exiger une approbation pour l’évaluation de code en ligne`},help:{"v1-jkmgo7-5z":"Exiger une approbation explicite pour les formes d’évaluation de code en ligne des interpréteurs telles que `python -c`, `node -e`, `ruby -e` ou `osascript -e`. Empêche la réutilisation silencieuse de la liste d’autorisation et remplace l’autorisation permanente par une demande à chaque fois pour ces formes."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Délai d’expiration d’exécution (secondes)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Outils de système de fichiers limités à l’espace de travail`},help:{"v1-1mhuvka-2s":`Restreindre les outils de système de fichiers (read/write/edit/apply_patch) au répertoire de l’espace de travail (par défaut : false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Identité GitHub CLI et auteur Git`},help:{"v1-1fl77im-5s":`Profil local géré pour GitHub CLI et auteur Git facultatif pour les outils de l’agent. Omettez cet objet pour conserver le compte et l’auteur natifs de l’utilisateur sous lequel s’exécute Gateway ; les identifiants d’accès aux dépôts distants ne sont jamais remplacés.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Adresse e-mail de l’auteur Git`},help:{"v1-kol5g6-1i":`Adresse e-mail facultative de l’auteur et du validateur Git, propre au processus.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Nom de l’auteur Git`},help:{"v1-z5bl1f-1h":`Nom facultatif de l’auteur et du validateur Git, propre au processus.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Type d’identifiant GitHub`},help:{"v1-qi3qun-3q":`Désigne un profil OAuth géré dont l’identifiant de renouvellement rotatif est détenu par Gateway. Les profils pour lesquels ce champ est omis utilisent un jeton d’accès personnel.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Version du profil GitHub`},help:{"v1-4lzl0-27":`Version de profil générée et opaque, utilisée pour changer les identifiants gérés de manière atomique.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Activer la compréhension des liens`},help:{"v1-23t2io-59":`Activer le prétraitement automatique de compréhension des liens afin que le contenu des URL puisse être résumé avant le raisonnement de l’agent. Laissez cette option activée pour enrichir le contexte, et désactivez-la lorsqu’un traitement strictement minimal est requis.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Nombre maximal de liens à analyser`},help:{"v1-ksxmcv-52":`Nombre maximal de liens dont le contenu est récupéré par tour lors de l’analyse des liens. Utilisez des valeurs faibles pour limiter la latence et les coûts dans les fils de discussion très actifs, et des valeurs plus élevées lorsque le contexte fourni par plusieurs liens est essentiel.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Modèles d’analyse des liens`},help:{"v1-6j3mnw-5a":`Liste des modèles privilégiés pour les tâches d’analyse des liens, évalués dans l’ordre comme solutions de repli lorsque cette fonctionnalité est prise en charge. Utilisez d’abord des modèles légers pour les résumés courants, et des modèles plus lourds uniquement si nécessaire.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Périmètre d’analyse des liens`},help:{"v1-183cwpa-55":`Détermine quand l’analyse des liens s’exécute en fonction du contexte de la conversation et du type de message. Limitez ce périmètre pour éviter les récupérations inutiles dans les messages où les liens ne sont pas exploitables.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Délai d’expiration de l’analyse des liens (s)`},help:{"v1-61v30o-4p":`Délai maximal d’analyse par lien, en secondes, avant que les liens non résolus soient ignorés. Limitez ce délai pour éviter de longues attentes lorsque les sites externes sont lents ou inaccessibles.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-108r5c7-h":`Protection contre les appels d’outil répétés`},help:{"v1-wrvlew-5k":`Contrôle la protection contre les appels d’outil répétés. Cette protection ajoute une note de réorientation au troisième appel d’outil consécutif identique et met fin au tour au vingtième. Omettez ce paramètre ou définissez-le sur true pour laisser la protection activée ; définissez-le sur false pour la désactiver.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Politique de traitement des pièces jointes pour l’analyse audio`},help:{"v1-1s3t9s5-3o":`Choisissez les pièces jointes audio correspondantes à traiter. Ne traitez que la première, sauf si vous souhaitez explicitement transcrire plusieurs pièces jointes.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Format de restitution de la transcription`},help:{"v1-glpdzh-3i":`Mettez en forme la transcription renvoyée avec un espace réservé {transcript}. Conservez cet espace réservé intact pour que le message envoyé inclue la transcription.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Renvoyer la transcription dans la conversation`},help:{"v1-1dedp8c-3r":`Renvoyez la transcription audio dans la conversation d’origine avant son traitement par l’agent. Activez cette option lorsque les utilisateurs doivent vérifier ce que le système a entendu.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Activer la compréhension audio`},help:{"v1-1v0x7te-2m":`Activez la compréhension audio pour permettre la transcription des notes vocales ou des extraits audio afin d’alimenter le contexte de l’agent.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Langue de compréhension audio`},help:{"v1-1ruqt97-3z":`Indication de langue par défaut pour les fournisseurs de transcription audio. Définissez-la lorsque la langue principalement parlée est connue et que la détection du fournisseur n’est pas fiable.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Taille maximale en octets pour la compréhension audio`},help:{"v1-1mcckc8-43":`Limite de taille par défaut des données audio en entrée pour les modèles configurés et détectés automatiquement. Définissez cette valeur sur la taille du plus grand enregistrement que vos fournisseurs et votre réseau doivent accepter.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Nombre maximal de caractères pour la compréhension audio`},help:{"v1-eo1dp-43":`Longueur maximale par défaut des transcriptions pour les modèles configurés et détectés automatiquement. Utilisez une valeur plus faible pour éviter que les longues notes vocales n’augmentent le volume du contexte de l’agent.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Modèle privilégié pour la compréhension audio`},help:{"v1-1n5zya1-3c":`Privilégiez une entrée tools.media.models dotée d’une étiquette de capacité pour la transcription audio avant les autres solutions de repli compatibles.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Consigne de compréhension audio`},help:{"v1-1v5jtay-4b":`Consigne de transcription audio par défaut lorsqu’aucune consigne propre au modèle ne la remplace. Gardez cette instruction stable lorsque les flux de travail en aval dépendent du style de transcription.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Périmètre de compréhension audio`},help:{"v1-1pptfg0-3w":`Limitez la compréhension audio par canal, type de conversation ou clé source. Gardez ce périmètre restreint lorsque la transcription automatique est sensible ou coûteuse.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Délai d’expiration de la compréhension audio (s)`},help:{"v1-n8wc6c-3b":`Délai d’expiration par défaut des requêtes de compréhension audio. Augmentez-le pour les enregistrements longs ou les modèles de transcription locaux plus lents.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Parallélisme de la compréhension des médias`},help:{"v1-13kr9np-58":`Nombre maximal d’opérations simultanées de compréhension des médias par tour, toutes tâches d’image, d’audio et de vidéo confondues. Réduisez cette valeur dans les déploiements aux ressources limitées pour éviter la saturation du processeur ou du réseau.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Politique de traitement des pièces jointes pour la compréhension d’images`},help:{"v1-11hofbw-3e":`Choisissez les pièces jointes d’image correspondantes à traiter. Ne traitez que la première, sauf si vous souhaitez analyser plusieurs images.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Activer la compréhension d’images`},help:{"v1-1b2zw34-50":`Activez la compréhension des images pour que les images jointes ou référencées puissent être interprétées sous forme de contexte textuel. Désactivez-la si vous avez besoin d’un fonctionnement en mode texte uniquement ou souhaitez éviter les coûts de traitement des images.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Nombre maximal d’octets pour la compréhension des images`},help:{"v1-jwwpd1-3v":`Taille limite par défaut des images en entrée pour les modèles configurés et détectés automatiquement. Définissez cette valeur en fonction des limites de charge utile du fournisseur et de la bande passante du déploiement.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Nombre maximal de caractères pour la compréhension des images`},help:{"v1-ebnxhk-3q":`Longueur maximale par défaut des descriptions d’images. Utilisez une valeur plus faible pour un contexte compact ou une valeur plus élevée pour une reconnaissance optique de caractères et une analyse de scène détaillées.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Modèle préféré pour la compréhension des images`},help:{"v1-1o2uwo6-3c":`Privilégiez une entrée tools.media.models étiquetée par capacité pour la compréhension des images avant les autres solutions de repli compatibles.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Prompt de compréhension des images`},help:{"v1-3a7piy-3p":`Prompt de compréhension d’image par défaut lorsqu’une entrée ne le remplace pas. Utilisez un prompt fixe lorsque les systèmes qui l’exploitent dépendent de descriptions stables.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Périmètre de compréhension des images`},help:{"v1-tievo1-3s":`Limitez la compréhension des images selon le canal, le type de conversation ou la clé source. Maintenez un périmètre restreint dans les canaux très actifs ou non fiables pour maîtriser le traitement.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Délai d’expiration de la compréhension des images (s)`},help:{"v1-1wcm84x-31":`Délai d’expiration par défaut des requêtes de compréhension d’images. Augmentez-le pour les images volumineuses ou les modèles de vision locaux plus lents.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Modèles partagés de compréhension des médias`},help:{"v1-1bbsp4f-3x":`Liste des modèles de compréhension des médias. Utilisez des étiquettes de capacité image, audio ou vidéo sur chaque entrée afin que chaque pipeline ne sélectionne que des modèles de repli compatibles.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Politique de traitement des pièces jointes pour la compréhension vidéo`},help:{"v1-1qm1qrc-3e":`Choisissez les pièces jointes vidéo correspondantes à traiter. Ne traitez que la première, sauf si vous souhaitez analyser plusieurs vidéos.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Activer la compréhension vidéo`},help:{"v1-1ltx5gl-58":`Activez la compréhension vidéo pour résumer les clips sous forme de texte destiné au raisonnement et aux réponses en aval. Désactivez-la si le traitement vidéo n’est pas autorisé par votre politique ou s’il est trop coûteux pour votre déploiement.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Nombre maximal d’octets pour la compréhension vidéo`},help:{"v1-2mp77v-3v":`Limite de taille par défaut des vidéos en entrée pour les modèles configurés et détectés automatiquement. Adaptez cette valeur aux limites de charge utile du fournisseur et à la bande passante du déploiement.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Nombre maximal de caractères pour la compréhension vidéo`},help:{"v1-1j0x40b-3j":`Longueur maximale par défaut des descriptions vidéo. Utilisez une valeur plus faible pour un contexte compact ou plus élevée pour des résumés de scènes détaillés.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Modèle privilégié de compréhension vidéo`},help:{"v1-1cygq5k-3c":`Privilégier une entrée tools.media.models étiquetée par capacité pour la compréhension vidéo avant les autres solutions de repli compatibles.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Prompt de compréhension vidéo`},help:{"v1-692dhv-3m":`Prompt de compréhension vidéo par défaut lorsqu’une entrée ne le remplace pas. Utilisez un prompt fixe lorsque les systèmes qui l’exploitent dépendent de résumés stables.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Périmètre de compréhension vidéo`},help:{"v1-7gfrx3-3s":`Restreindre la compréhension vidéo par canal, type de conversation ou clé source. Limitez ce périmètre dans les canaux très actifs ou non fiables afin de maîtriser le traitement.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Délai d’expiration de la compréhension vidéo (s)`},help:{"v1-e8rzsy-33":`Délai d’expiration par défaut des requêtes de compréhension vidéo. Augmentez-le pour les clips plus longs ou les modèles d’analyse locaux plus lents.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Liste des actions de messagerie autorisées`},help:{"v1-1iceqwa-5c":`Liste globale des actions de messagerie autorisées pour l’outil message. À utiliser uniquement lorsque l’ensemble de l’environnement d’exécution doit proposer et accepter un ensemble réduit d’actions ; privilégiez des listes d’autorisation par agent pour les agents publics ou exécutés dans un bac à sable.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Activer la diffusion de messages`},help:{"v1-1ms74z7-14":`Activer l’action de diffusion (par défaut : true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Autoriser les échanges entre contextes (entre fournisseurs)`},help:{"v1-276qxo-2s":`Autoriser les envois entre différents fournisseurs (par défaut : true). Définissez ce paramètre sur false pour bloquer les messages entre fournisseurs.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Autoriser les envois entre contextes (même fournisseur)`},help:{"v1-1sg4x49-1z":`Autoriser les envois vers d’autres canaux du même fournisseur (par défaut : true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Marqueur intercontexte`},help:{"v1-1fg6jrp-1z":`Ajouter un marqueur d’origine visible lors des envois entre contextes (par défaut : true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Préfixe du marqueur intercontexte`},help:{"v1-eblsru-1p":`Préfixe textuel des marqueurs intercontextes (prend en charge « {channel} »).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Suffixe du marqueur intercontexte`},help:{"v1-1nk0jub-1p":`Suffixe textuel des marqueurs intercontextes (prend en charge « {channel} »).`}},"tools%2Eopenclaw":{label:{"v1-m2tz7g-j":`Délégation à OpenClaw`},help:{"v1-4bdi5v-26":`Politique d’approbation pour les modifications persistantes déléguées à l’agent système OpenClaw.`}},"tools%2Eopenclaw%2EautoApproveChanges":{label:{"v1-1arx74u-u":`Approbation automatique des modifications déléguées`},help:{"v1-1gy96r5-br":`Autorisation permanente pour les opérations d’administration déléguée permises, y compris les configurations permettant d’exécuter du code sur l’hôte Gateway. La valeur true autorise les modifications sans approbation individuelle, même lorsque les outils d’exécution directe sont interdits ; false exige toujours une approbation. Si ce paramètre est omis, un accès complet explicitement accordé ou une autorisation d’exécution sans restriction sur Gateway établie de manière indépendante est utilisé. Les restrictions relatives au système de fichiers, au bac à sable, aux opérations et à l’exécution en cours restent applicables.`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Profil d’outils`},help:{"v1-h6k98q-5k":`Nom du profil global d’outils servant à sélectionner une politique d’outils prédéfinie comme base avant d’appliquer les dérogations d’autorisation ou de refus. Utilisez ce profil pour assurer une configuration cohérente de l’environnement entre les agents et conservez des noms de profil stables.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Politique d’outils du bac à sable`},help:{"v1-ea7awo-4k":`Cadre de politique d’outils pour les exécutions d’agents en bac à sable, permettant de définir des limites de capacité distinctes pour ces exécutions. Utilisez-le pour renforcer la sécurité dans les contextes de bac à sable.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Politique d’autorisation ou de refus des outils du bac à sable`},help:{"v1-ub701o-4t":`Politique d’autorisation ou de refus des outils appliquée lorsque les agents s’exécutent dans des environnements en bac à sable. Limitez les autorisations au strict minimum afin que les tâches en bac à sable ne puissent pas déclencher d’actions externes inutiles.`}},"tools%2Esessions%2EallowThreadTargets":{label:{"v1-1o1dl7e-p":`Autoriser les fils de discussion comme destinations d’envoi`},help:{"v1-1ppcmoz-6v":`Autoriser sessions_send à cibler des sessions de discussion limitées à un fil ou à un sujet, comme les sujets de forum Telegram ou les fils Slack/Discord (par défaut : false). La cible s’exécute dans cette session ; tout ce qu’elle envoie avec l’outil message apparaît dans le fil visible par les utilisateurs.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Visibilité des outils de session`},help:{"v1-1p13n9k-fm":`Détermine quelles sessions peuvent être ciblées par sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all" par défaut = toute session sur le Gateway, y compris celles d’autres agents et utilisateurs ; "agent" = toute session associée à l’identifiant de l’agent actuel ; "self" = uniquement la session actuelle ; "tree" = session actuelle + sessions des sous-agents créés). L’accès entre agents est activé par défaut et encadré par tools.agentToAgent ; utilisez une visibilité plus restreinte pour limiter les lectures et les envois ordinaires. Les destinations explicites définies dans agents.entries.<id>.tools.agentToAgent.send peuvent autoriser les envois sans élargir l’accès en lecture.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Politique des outils des sous-agents`},help:{"v1-1xoug01-4z":`Cadre de politique des outils pour les sous-agents créés, permettant de restreindre ou d’étendre la disponibilité des outils par rapport aux paramètres par défaut du parent. Utilisez-le pour limiter les capacités des agents délégués au périmètre de la tâche.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Politique d’autorisation et de refus des outils des sous-agents`},help:{"v1-7vxsbf-5d":`Politique d’autorisation et de refus des outils appliquée aux environnements d’exécution des sous-agents créés. Gardez un périmètre plus restreint que celui du parent. Les outils réservés au parent, tels que progress_card, sont toujours refusés, y compris via allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Essaim`},help:{"v1-1q96vvs-45":`Orchestration des sous-agents en mode collecteur. Activée par défaut ; définissez la valeur sur false pour la désactiver. Les autorisations des outils s’appliquent toujours à agents_wait et aux options de création de l’essaim.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Agent par défaut de l’essaim`},help:{"v1-p4alpg-2m":`Agent cible par défaut pour les créations de sous-agents dans l’essaim qui omettent agentId. La liste des sous-agents autorisés s’applique toujours.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Activer l’essaim`},help:{"v1-1nnnrq9-2e":`Active les sous-agents en mode collecteur et agents_wait. Activé par défaut ; définissez la valeur sur false pour désactiver.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Collecteurs enfants actifs par groupe d’essaim`},help:{"v1-kfx6qp-1c":`Nombre maximal de collecteurs enfants actifs par groupe d’essaim.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1a16wrf-z":`Nombre d’enfants simultanés par groupe d’essaim`},help:{"v1-1ednj37-70":`Nombre maximal d’enfants collecteurs en cours d’exécution dans la voie d’exécution distincte de chaque groupe d’essaim (par défaut : 32), indépendamment du nombre de sous-agents ordinaires exécutés simultanément. Chaque enfant en cours d’exécution utilise un flux de modèle et une instance isolée de worker Code Mode. Les limites d’admission des groupes s’appliquent toujours.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Nombre total de collecteurs enfants par groupe d’essaim`},help:{"v1-1gc9vl1-1e":`Nombre maximal de créations de collecteurs sur toute la durée de vie d’un groupe d’essaim.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Délai d’attente maximal de l’essaim`},help:{"v1-bog18y-1g":`Délai d’attente maximal accepté par agents_wait, en secondes.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Recherche d’outils`},help:{"v1-g2rpl8-80":`Réduisez la taille des catalogues volumineux d’outils OpenClaw, MCP et clients. Si ce paramètre n’est pas défini, les environnements d’exécution OpenClaw utilisent automatiquement Tool Search en mode structuré ; Code Mode est prioritaire lorsqu’il est activé, et Codex utilise sa recherche native. Définissez ce paramètre sur false pour désactiver cette fonctionnalité, sur true pour utiliser la recherche structurée, ou utilisez la forme objet pour choisir un mode.`}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Activer la recherche d’outils`},help:{"v1-1naa8jz-3v":`Active Tool Search. Lorsque cette fonctionnalité est activée, OpenClaw masque les catalogues d’outils volumineux derrière des outils structurés de recherche, de description et d’appel lors des exécutions dans l’environnement intégré.`}},"tools%2EtoolSearch%2Eexclude":{label:{"v1-1040rv9-t":`Sélecteurs d’exclusion de la recherche d’outils`},help:{"v1-pmx6vl-60":`Outils à garder directement visibles au lieu de les cataloguer. Utilise les mêmes sélecteurs que include ; l’exclusion est prioritaire. Si ce paramètre est omis ou défini sur [], aucun outil n’est exclu. N’accorde aucune autorisation et ne modifie pas le traitement des outils accessibles uniquement en direct ou requis à l’exécution.`}},"tools%2EtoolSearch%2Eexclude%5B%5D%2Ename":{label:{"v1-7sh15i-i":`Nom de l’outil exclu`},help:{"v1-ke0ysb-4v":`Nom d’outil enregistré ou motif générique avec * à garder accessible en direct, selon la normalisation de la politique des outils. Les sélecteurs portant uniquement sur le nom s’appliquent à toutes les sources ; précisez la source pour éviter les correspondances indésirables.`}},"tools%2EtoolSearch%2Eexclude%5B%5D%2Esource":{label:{"v1-1u3p208-k":`Source de l’outil exclu`},help:{"v1-1r3h9ad-2x":`Origine à exclure du catalogage : "openclaw", "mcp" ou "client". Combinée à name par un ET logique lorsque les deux sont présents.`}},"tools%2EtoolSearch%2Einclude":{label:{"v1-130v30b-t":`Sélecteurs d’inclusion de la recherche d’outils`},help:{"v1-1567ter-7t":`Sélecteurs de présentation des outils admissibles au catalogue et autorisés par la politique. Si ce paramètre est omis, tous les outils admissibles sont sélectionnés ; [] n’en sélectionne aucun. Les champs d’un même sélecteur sont combinés par un ET logique ; les sélecteurs sont combinés par un OU logique. Les outils non sélectionnés restent directement appelables. N’affecte pas le mode Code indépendant ni la recherche native de Codex.`}},"tools%2EtoolSearch%2Einclude%5B%5D%2Ename":{label:{"v1-ewc3qk-i":`Nom de l’outil inclus`},help:{"v1-8gy1xg-4o":`Nom d’outil enregistré ou motif générique avec *, selon la normalisation de la politique des outils (alias compris). Les sélecteurs portant uniquement sur le nom s’appliquent à toutes les sources. Les expressions régulières et l’expansion des groupes d’outils ne sont pas prises en charge.`}},"tools%2EtoolSearch%2Einclude%5B%5D%2Esource":{label:{"v1-31fgve-k":`Source de l’outil inclus`},help:{"v1-19ewj5n-52":`Origine de l’outil : "openclaw" pour les plugins du cœur et les plugins non-MCP, "mcp" pour les outils MCP enregistrés, ou "client" pour les outils fournis par le client. Précisez la source des noms pour éviter les correspondances avec des noms similaires.`}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Nombre maximal de résultats de recherche d’outils`},help:{"v1-7du4kh-32":`Nombre maximal de résultats de recherche d’outils qu’un modèle peut demander. À l’exécution, les valeurs sont limitées à la plage prise en charge de 1 à 50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Interface de recherche d’outils`},help:{"v1-1uvcg7i-6z":`Choisissez l’interface présentée au modèle : "tools" (par défaut) expose des outils structurés de recherche, de description et d’appel ; "directory" conserve un répertoire d’outils de taille limitée visible, expose un ensemble limité de schémas susceptibles d’être utilisés ou obligatoires, et rend le reste accessible à la demande via la recherche, la description et l’appel.`}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Nombre de résultats par défaut de la recherche d’outils`},help:{"v1-1uchq7t-39":"Nombre de résultats de recherche d’outils renvoyés par défaut lorsque le modèle ne précise pas de limite. À l’exécution, cette valeur est plafonnée à `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Activer l’outil de planification structurée`},help:{"v1-1xgegme-4o":"Outil de suivi unifié `progress_card` pour les plans persistants et les notes narratives dans les sessions parentes. Activé par défaut ; définissez la valeur sur false pour le désactiver. Toujours indisponible pour les sous-agents."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Outils web`},help:{"v1-fpsy5-4y":`Regroupement des règles des outils web pour configurer les fournisseurs de recherche et de récupération, les limites et le comportement de repli. Veillez à ce que les paramètres activés restent cohérents avec la disponibilité des clés API et la politique de réseau sortant.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL du cache de récupération web (min)`},help:{"v1-1hk89qp-17":`TTL du cache en minutes pour les résultats de web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Activer l’outil de récupération web`},help:{"v1-yrswld-1f":`Activer l’outil web_fetch (récupération HTTP légère).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`En-têtes de requête de récupération web`},help:{"v1-16bjkv5-me":"En-têtes de requête supplémentaires envoyés avec les requêtes web_fetch directes, par exemple pour le routage via une passerelle ou l’authentification. Chaque valeur configurée est traitée comme sensible et masquée dans la configuration exposée et les captures de débogage. Les valeurs sont des chaînes de texte simples, prennent en charge la substitution ${VAR} et l’échappement littéral global $${VAR}, et sont envoyées aux URL choisies par le modèle. Les entrées sont validées lors de la construction de la requête plutôt qu’au chargement de la configuration : un nom incorrect ou une valeur impossible à envoyer est donc ignoré et consigné dans les journaux, sans désactiver la fonctionnalité ; Accept, Accept-Language, User-Agent et les en-têtes de délimitation tels que Transfer-Encoding sont également ignorés. Utilisez tools.web.fetch.userAgent pour modifier l’agent utilisateur. Les redirections entre origines ne conservent que les en-têtes figurant dans la liste d’autorisation sécurisée de guarded-fetch, et toute modification des en-têtes effectivement envoyés partitionne le cache de récupération."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Nombre maximal de caractères pour la récupération web`},help:{"v1-12d1fw7-1d":`Nombre maximal de caractères renvoyés par web_fetch (avec troncature).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Limite absolue de caractères pour la récupération web`},help:{"v1-cl2mf1-1v":`Limite absolue de maxChars pour web_fetch (s’applique à la configuration et aux appels d’outils).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Nombre maximal de redirections pour la récupération web`},help:{"v1-t6eak9-1h":`Nombre maximal de redirections autorisées pour web_fetch (par défaut : 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Taille maximale de téléchargement pour la récupération web (octets)`},help:{"v1-q6ld9c-10":`Taille maximale de téléchargement avant troncature.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Fournisseur de récupération web`},help:{"v1-6pb3nv-v":`Identifiant du fournisseur de secours pour la récupération web.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Extraction Readability pour la récupération web`},help:{"v1-19exqzx-2c":`Utiliser Readability pour extraire le contenu principal du HTML (avec un nettoyage HTML de base en solution de repli).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Politique SSRF pour la récupération web`},help:{"v1-qtn7zx-3c":`Dérogations ciblées à la politique SSRF pour web_fetch. Limitez leur portée et ne les activez que pour des environnements proxy connus sur le réseau local.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Noms d’hôte autorisés pour la récupération web`},help:{"v1-1j9ctya-35":`Noms d’hôte exacts ou adresses IP littérales autorisés pour web_fetch, y compris les cibles autrement bloquées. Limitez cette liste au strict minimum.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Autoriser la plage IPv6 locale unique pour la récupération web`},help:{"v1-1eyz55i-3b":`Autoriser les adresses IPv6 locales uniques (fc00::/7) pour assurer la compatibilité avec des proxys de confiance utilisant des IP fictives, tels que sing-box, Clash ou Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Autoriser la plage de test RFC 2544 pour la récupération web`},help:{"v1-u5asdb-2y":`Autoriser les adresses IP de la plage de test RFC 2544 (198.18.0.0/15) pour assurer la compatibilité avec les proxys utilisant des IP fictives, tels que Clash ou Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Noms d’hôte bloqués pour la récupération web`},help:{"v1-1164vvk-66":`Motifs de noms d’hôte bloqués avant la résolution DNS et l’application des règles d’autorisation à chaque redirection de web_fetch. Prend en charge les noms d’hôte exacts et "*.example.com" pour les sous-domaines uniquement ; ajoutez "example.com" séparément pour bloquer le domaine racine. Si ce champ est vide ou non défini, aucun blocage n’est ajouté.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Récupération web : autoriser l’accès au réseau privé (dangereux)`},help:{"v1-2s6mv7-3t":`Autorise web_fetch à accéder à des cibles sur les réseaux privés et internes. Laissez cette option désactivée, sauf si les URL sélectionnées par le modèle sont fiables dans ce déploiement.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Délai d’expiration de la récupération web (s)`},help:{"v1-1c3yfr4-16":`Délai d’expiration en secondes pour les requêtes web_fetch.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent de la récupération web`},help:{"v1-s7pe8j-1e":`Remplace l’en-tête User-Agent pour les requêtes web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Proxy d’environnement de confiance pour la récupération web`},help:{"v1-1ypkqj7-54":`Achemine web_fetch via un proxy HTTP(S) de confiance défini dans l’environnement et lui confie la résolution DNS. Activez cette option uniquement si ce proxy est contrôlé par l’opérateur et applique la politique de trafic sortant après la résolution DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`Durée de vie du cache de recherche web (min)`},help:{"v1-6trzlf-18":`Durée de vie du cache en minutes pour les résultats de web_search.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Activer l’outil de recherche web`},help:{"v1-n1cm4y-27":`Active la recherche gérée via web_search et la recherche native de Codex facultative pour les modèles compatibles.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Nombre maximal de résultats de recherche Web`},help:{"v1-mrw7mi-z":`Nombre de résultats à renvoyer (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Domaines autorisés pour Codex`},help:{"v1-1cv4y44-43":`Liste des domaines autorisés pour l’outil web_search natif de Codex. Lors des tours utilisant la recherche hébergée native, elle restreint également l’outil web_fetch géré ; les tours utilisant un fournisseur géré restent inchangés.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Taille du contexte de recherche Codex`},help:{"v1-antack-1u":`Indication de la taille du contexte de recherche natif de Codex : "low", "medium" ou "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Activer la recherche Web native de Codex`},help:{"v1-ek2jzd-1k":`Activer la recherche Web native de Codex pour les modèles compatibles avec Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Mode de recherche Web de Codex`},help:{"v1-1ahyq9f-32":`Préférence de recherche Web native de Codex : "cached" (par défaut ; les tours Codex sans restriction utilisent alors le mode "live") ou "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Ville de l’utilisateur pour Codex`},help:{"v1-1y95orp-1d":`Ville approximative transmise à la recherche Web native de Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Pays de l’utilisateur pour Codex`},help:{"v1-1xkm5ms-1g":`Pays approximatif transmis à la recherche Web native de Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Région de l’utilisateur pour Codex`},help:{"v1-lhar02-1l":`Région ou État approximatif transmis à la recherche web native de Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Fuseau horaire de l’utilisateur Codex`},help:{"v1-fgv9fh-1h":`Fuseau horaire approximatif transmis à la recherche web native de Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Fournisseur de recherche web`},help:{"v1-10omglr-1x":`Identifiant du fournisseur de recherche. Détecté automatiquement à partir des clés API disponibles s’il n’est pas renseigné.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Délai d’expiration de la recherche web (s)`},help:{"v1-i0egvw-17":`Délai d’expiration en secondes des requêtes web_search.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transcriptions`},help:{"v1-1i0sc09-66":`Paramètres principaux de capture des transcriptions pour les notes de réunion, les outils d’agent capables d’enregistrer et les sources de démarrage automatique des réunions en direct configurées. Les plugins de réunion conservent les notes par défaut ; définissez enabled sur false pour désactiver cette fonction globalement.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Sources de démarrage automatique des transcriptions`},help:{"v1-1mzsl79-5s":`Sources de transcription en direct gérées automatiquement dès le démarrage du Gateway. Chaque entrée est activée par sa présence ; supprimez une entrée pour désactiver la source correspondante. Les sources capturent en continu, sauf si whenOccupied est activé.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Identifiant du compte de transcription`},help:{"v1-6g2kjj-4b":`Identifiant facultatif du compte fournisseur ou de l’espace de travail pour les sources de transcription nécessitant de distinguer les comptes. Utilisez le format d’identifiant de compte indiqué dans la documentation du fournisseur.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`Identifiant du canal de transcription`},help:{"v1-1lk9d5o-4u":`Identifiant du canal côté fournisseur pour la source de transcription en direct, par exemple un salon vocal Discord ou un canal d’appel d’équipe Slack. Vérifiez la signification des identifiants propres au fournisseur avant d’activer le démarrage automatique.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Identifiant du serveur Discord`},help:{"v1-fyfgnk-4l":`Identifiant facultatif du serveur Discord pour les sources de transcription vocale Discord. Configurez-le avec le channelId correspondant lorsque le fournisseur doit rechercher les salons vocaux au sein d’un serveur.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`URL de la réunion à transcrire`},help:{"v1-1xtt9ci-4f":`URL de réunion facultative pour les fournisseurs qui rejoignent une réunion par URL plutôt que par identifiant de canal. Utilisez uniquement des liens de réunion de confiance, car le démarrage automatique peut rejoindre et enregistrer cette réunion.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`Identifiant du fournisseur de la source de transcription`},help:{"v1-1uur06p-3s":`Identifiant du fournisseur de la source de transcription, par exemple un fournisseur vocal Discord ou un futur fournisseur d’appels d’équipe Slack. Utilisez l’identifiant exact exposé par le plugin du fournisseur.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`Identifiant de la session de transcription`},help:{"v1-xyo4x5-5o":`Identifiant fixe facultatif de session de transcription pour cette source à démarrage automatique. Ignoré lorsque whenOccupied vaut true. Laissez ce champ non défini pour générer les identifiants, sauf si vous avez besoin d’un sélecteur quotidien stable et pouvez éviter les collisions au cours d’une même journée.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Titre de la transcription`},help:{"v1-ycjnmp-5y":`Titre facultatif pour les futures captures de transcription. Modifier uniquement les titres laisse les captures en cours actives et ne modifie ni leur titre initial ni les notes enregistrées. Les autres modifications de source conservent leur comportement habituel de redémarrage.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Capture de transcription en présence de participants`},help:{"v1-34jid4-78":`Démarre une nouvelle session de transcription chaque fois que des personnes sont présentes dans la source et l’arrête (en générant des notes) après le départ de la dernière personne. Nécessite un fournisseur qui signale la présence de participants, tel que discord-voice. Par défaut : false (capture en continu dès le démarrage du Gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transcriptions activées`},help:{"v1-fyqqr0-6d":`Active les notes de réunion automatiques persistantes, l’outil d’agent transcripts et les sources configurées pour démarrer automatiquement. Par défaut : true. Définissez sur false pour désactiver la persistance et l’outil ; le mode explicite de transcription de réunion conserve son historique récent en direct de taille limitée.`}},tts:{label:{"v1-bmxkk9-e":`Synthèse vocale`},help:{"v1-1o27tk2-4n":`Politique de synthèse vocale pour lire à voix haute les réponses de l’agent sur les interfaces vocales ou audio compatibles. Laissez cette option désactivée, sauf si la lecture vocale fait partie du flux de travail de vos opérateurs ou utilisateurs.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Profil de synthèse vocale`},help:{"v1-1r0opcb-29":`Identifiant du profil de synthèse vocale par défaut. Les préférences locales de profil de synthèse vocale peuvent remplacer cette valeur pour chaque hôte.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Profils de synthèse vocale`},help:{"v1-19aybhl-2l":`Profils de synthèse vocale nommés qui définissent une identité vocale stable ainsi que des associations de synthèse vocale propres à chaque fournisseur.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Profil de synthèse vocale`},help:{"v1-10s52ah-2l":`Un profil de synthèse vocale. Utilisez des associations propres à chaque fournisseur pour définir précisément les voix, les modèles et les modèles de prompt.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Associations des profils TTS aux fournisseurs`},help:{"v1-993jop-3e":`Associations des profils TTS propres à chaque fournisseur, indexées par identifiant de fournisseur de synthèse vocale. Elles se superposent à tts.providers pour le profil actif.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Paramètres des fournisseurs TTS`},help:{"v1-1k80nl4-4y":`Paramètres TTS propres à chaque fournisseur, indexés par identifiant de fournisseur de synthèse vocale. Utilisez cette section plutôt que les clés de premier niveau propres aux fournisseurs intégrés, afin que les plugins de synthèse vocale restent indépendants du schéma de configuration principal.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Configuration du fournisseur TTS`},help:{"v1-dwapva-3d":`Configuration TTS propre à un fournisseur de synthèse vocale, identifié par son identifiant. Limitez les champs au périmètre du plugin auquel appartient ce fournisseur.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Clé API du fournisseur TTS`},help:{"v1-1m2fj0i-2o":`Clé API utilisée par ce fournisseur de synthèse vocale lorsque son plugin exige un accès TTS authentifié.`}},tui:{label:{"v1-c8hus1-b":`Interface du terminal`},help:{"v1-1fg9vw2-3s":`Paramètres d’affichage de l’interface du terminal. Utilisez cette section pour les préférences de présentation propres au terminal, sans modifier le comportement de Gateway ni des autres interfaces.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Pied de page de l’interface du terminal`},help:{"v1-6e12l3-3k":`Paramètres d’affichage du pied de page de l’interface du terminal. Gardez le contexte facultatif compact afin que les informations sur la session, le modèle, l’objectif et les jetons restent lisibles.`}},ui:{label:{"v1-ye4dff-2":`Interface utilisateur`},help:{"v1-dt1924-42":`Paramètres de présentation de l’interface pour les accents visuels et les préférences d’affichage de l’opérateur. Utilisez cette section pour personnaliser la lisibilité sans modifier le comportement à l’exécution.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Couleur d’accentuation de l’utilisateur`},help:{"v1-mpxaka-4y":`Couleur d’accentuation de l’application web : #RRGGBB pour une couleur personnalisée, ou 'theme' pour la palette du thème sélectionné. Remplace ui.seamColor ; effacez cette valeur pour utiliser la couleur d’accentuation configurée ou celle par défaut du thème.`}},"ui%2Eprefs%2Elocale":{label:{"v1-sk0cbe-i":`Langue de l’interface`},help:{"v1-6mqtbz-6x":`Langue de l’application web, sous la forme d’un identifiant de paramètres régionaux pris en charge, tel que en, de ou zh-CN. Laissez ce champ non défini pour suivre la langue du navigateur ou du système. Définissez-le dans Paramètres → Apparence → Langue. Ce paramètre ne définit pas le fuseau horaire de l’assistant (agents.defaults.userTimezone).`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Couleur d’accentuation`},help:{"v1-14q3r4h-4g":`Couleur d’accentuation principale utilisée dans l’interface pour la mise en évidence, les badges et les éléments d’identité visuelle. Utilisez des valeurs à contraste élevé qui restent lisibles dans les thèmes clairs et sombres.`}},update:{label:{"v1-k12u1x-7":`Mises à jour`},help:{"v1-11c5k8v-5c":`Canal de mise à jour et comportement de vérification au démarrage permettant de maintenir l’environnement d’exécution OpenClaw à jour. Utilisez des canaux éprouvés en production et réservez les canaux plus expérimentaux aux environnements contrôlés.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Mise à jour automatique activée`},help:{"v1-49xs2h-3c":`Active la mise à jour automatique en arrière-plan pour les installations par paquet des canaux stable et beta ; les mises à jour du canal extended-stable ne sont jamais appliquées automatiquement (par défaut : false).`}},"update%2Eauto%2Eschedule":{label:{"v1-1t6cr06-p":`Planification des mises à jour automatiques`},help:{"v1-zuf1kc-5y":`Expression cron facultative pour le lancement des campagnes de mise à jour automatique de Gateway, dans le fuseau horaire de l’hôte Gateway. Ne renseignez pas ce champ pour conserver la fréquence horaire actuelle. Les délais de déploiement et les comptes à rebours d’inactivité s’appliquent toujours ; les créneaux manqués sont ignorés.`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Canal de mise à jour`},help:{"v1-lqtdvf-5b":`Canal de mise à jour pour les installations git + npm ("stable", "extended-stable", "beta" ou "dev"). Le canal extended-stable est réservé aux paquets : l’installation s’effectue uniquement au premier plan, avec des indications facultatives en lecture seule au démarrage.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Vérification des mises à jour au démarrage`},help:{"v1-qy3q9g-5v":`Vérifie les mises à jour au démarrage du Gateway, y compris les indications en lecture seule pour extended-stable (par défaut : true). Définissez la valeur sur false pour désactiver les vérifications et l’application automatiques des mises à jour du Gateway et des nœuds sans interface graphique, ainsi que les requêtes anonymes de mise à jour.`}},voicewake:{label:{"v1-txt1wb-a":`Activation vocale`}},web:{label:{"v1-1ae9z56-b":`Canal web`}},wizard:{label:{"v1-28jonk-h":`Préférences de configuration`},help:{"v1-14jh6rm-3b":`Préférences de configuration propres à l’utilisateur. L’historique de l’assistant et l’état des confirmations propres à la machine sont stockés dans la base de données d’état partagée.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Accès à la découverte lors de la configuration`},help:{"v1-1nqxt0w-38":`Consentement à la détection pour la configuration guidée : "full" effectue l’analyse sans demander confirmation, tandis que "guarded" demande une autorisation avant d’inspecter les applications locales.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Recommandations d’applications lors de la configuration`},help:{"v1-ub8uoi-30":`Détermine si la configuration guidée peut utiliser les noms des applications installées pour recommander des plugins et des compétences pertinents.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Horodatage de la dernière exécution de l’assistant`},help:{"v1-1y0fbk-1k":`Horodatage de la dernière exécution de l’assistant dont les résultats ont été enregistrés avec succès.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Commande de la dernière exécution de l’assistant`},help:{"v1-x2pfkk-15":`Commande ayant lancé la dernière exécution de l’assistant.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit de la dernière exécution de l’assistant`},help:{"v1-h0jkmt-1i":`Commit du code source utilisé lors de la dernière exécution de l’assistant en version de développement.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Mode de la dernière exécution de l’assistant`},help:{"v1-16508qy-1r":`Indique si la dernière exécution de l’assistant visait une configuration "local" ou "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Version de la dernière exécution de l’assistant`},help:{"v1-1tr4z9d-19":`Version d’OpenClaw utilisée lors de la dernière exécution de l’assistant.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Horodatage de la confirmation de prise de connaissance des consignes de sécurité dans l’assistant`},help:{"v1-86i182-2a":`Horodatage de la confirmation de prise de connaissance des consignes de sécurité lors de la configuration, enregistré avec la configuration cible.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Accélération des arbres de travail`},help:{"v1-9es3gc-4r":`Utiliser l’accélération du système de fichiers pour les nouveaux arbres de travail gérés lorsqu’elle est prise en charge (valeur par défaut : true). Définissez cette option sur false pour utiliser l’extraction Git et la copie de fichiers classiques. S’applique uniquement aux nouveaux arbres de travail.`}},worktreeMaxCount:{label:{"v1-1gj5fhm-p":`Nombre maximal d’arbres de travail gérés`},help:{"v1-6z5l36-7q":`Nombre maximal d’arbres de travail gérés présents, tous agents et dépôts confondus (par défaut : 4096). Supprime d’abord ceux des branches fusionnées ou fusionnées par squash, puis les arbres de travail inactifs les plus anciens, y compris leurs données non enregistrées. Les exécutions en cours sont protégées ; augmentez cette valeur si elles atteignent la limite. Le contrôle de l’espace disque disponible reste applicable.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Racine des arbres de travail`},help:{"v1-1tgti9j-5d":`Répertoire global des nouveaux arbres de travail gérés. Utilisez un chemin absolu ou ~ pour votre répertoire personnel ; la valeur par défaut est <state-dir>/worktrees. Les arbres de travail existants conservent leurs chemins enregistrés lorsque ce paramètre est modifié.`}}}}})))()}export{i as n,n as t};